/* DAWAH X — ahmad, অধ্যায় 2 · খণ্ড 2 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][2]=[[201,201,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏عَطَاءُ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ شَرِيكٍ الْهُذَلِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ مَيْمُونٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ الْجُرَشِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُجَالِسُوا ‏ ‏أَهْلَ الْقَدَرِ ‏ ‏وَلَا تُفَاتِحُوهُمْ ‏ ‏وَقَالَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏مَرَّةً سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[202,202,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُمَيْرٍ الْهَمْدَانِيِّ أَبِي عُمَرَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَبِيبَ بْنَ عُبَيْدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ السِّمْطِ ‏ ‏أَنَّهُ خَرَجَ مَعَ ‏ ‏عُمَرَ ‏ ‏إِلَى ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏فَصَلَّى رَكْعَتَيْنِ فَسَأَلْتُهُ عَنْ ذَلِكَ فَقَالَ إِنَّمَا أَصْنَعُ كَمَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[203,203,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ قُرَادٌ ‏ ‏أَنْبَأَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ الْحَنَفِيُّ أَبُو زُمَيْلٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏حَدَّثَنِي ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏بَدْرٍ ‏ ‏قَالَ نَظَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَصْحَابِهِ وَهُمْ ثَلَاثُ مِائَةٍ وَنَيِّفٌ وَنَظَرَ إِلَى الْمُشْرِكِينَ فَإِذَا هُمْ أَلْفٌ وَزِيَادَةٌ فَاسْتَقْبَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقِبْلَةَ ثُمَّ مَدَّ يَدَيْهِ وَعَلَيْهِ رِدَاؤُهُ وَإِزَارُهُ ثُمَّ قَالَ ‏ ‏اللَّهُمَّ أَيْنَ مَا وَعَدْتَنِي اللَّهُمَّ أَنْجِزْ مَا وَعَدْتَنِي اللَّهُمَّ إِنَّكَ إِنْ تُهْلِكْ هَذِهِ ‏ ‏الْعِصَابَةَ ‏ ‏مِنْ أَهْلِ الْإِسْلَامِ فَلَا تُعْبَدْ فِي الْأَرْضِ أَبَدًا قَالَ فَمَا زَالَ يَسْتَغِيثُ رَبَّهُ عَزَّ وَجَلَّ ‏ ‏وَيَدْعُوهُ حَتَّى سَقَطَ رِدَاؤُهُ فَأَتَاهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَخَذَ رِدَاءَهُ فَرَدَّاهُ ثُمَّ الْتَزَمَهُ مِنْ وَرَائِهِ ثُمَّ قَالَ يَا نَبِيَّ اللَّهِ كَفَاكَ ‏ ‏مُنَاشَدَتُكَ ‏ ‏رَبَّكَ فَإِنَّهُ سَيُنْجِزُ لَكَ مَا وَعَدَكَ وَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُمْ بِأَلْفٍ مِنْ الْمَلَائِكَةِ ‏ ‏مُرْدِفِينَ ‏ } ‏فَلَمَّا كَانَ يَوْمُئِذٍ وَالْتَقَوْا فَهَزَمَ اللَّهُ عَزَّ وَجَلَّ الْمُشْرِكِينَ فَقُتِلَ مِنْهُمْ سَبْعُونَ رَجُلًا وَأُسِرَ مِنْهُمْ سَبْعُونَ رَجُلًا فَاسْتَشَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعَلِيًّا ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَا نَبِيَّ اللَّهِ هَؤُلَاءِ بَنُو الْعَمِّ وَالْعَشِيرَةُ وَالْإِخْوَانُ فَإِنِّي أَرَى أَنْ تَأْخُذَ مِنْهُمْ الْفِدْيَةَ فَيَكُونُ مَا أَخَذْنَا مِنْهُمْ ‏ ‏قُوَّةً ‏ ‏لَنَا عَلَى الْكُفَّارِ وَعَسَى ‏ ‏اللَّهُ أَنْ يَهْدِيَهُمْ فَيَكُونُونَ لَنَا عَضُدًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏تَرَى يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏قَالَ قُلْتُ وَاللَّهِ مَا أَرَى مَا رَأَى ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَلَكِنِّي أَرَى أَنْ تُمَكِّنَنِي مِنْ فُلَانٍ قَرِيبًا ‏ ‏لِعُمَرَ ‏ ‏فَأَضْرِبَ عُنُقَهُ وَتُمَكِّنَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مِنْ ‏ ‏عَقِيلٍ ‏ ‏فَيَضْرِبَ عُنُقَهُ وَتُمَكِّنَ ‏ ‏حَمْزَةَ ‏ ‏مِنْ فُلَانٍ أَخِيهِ فَيَضْرِبَ عُنُقَهُ حَتَّى يَعْلَمَ اللَّهُ أَنَّهُ لَيْسَتْ فِي قُلُوبِنَا هَوَادَةٌ لِلْمُشْرِكِينَ هَؤُلَاءِ ‏ ‏صَنَادِيدُهُمْ وَأَئِمَّتُهُمْ وَقَادَتُهُمْ فَهَوِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَلَمْ يَهْوَ مَا قُلْتُ فَأَخَذَ مِنْهُمْ الْفِدَاءَ فَلَمَّا أَنْ كَانَ مِنْ الْغَدِ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏غَدَوْتُ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا هُوَ قَاعِدٌ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَإِذَا هُمَا يَبْكِيَانِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَخْبِرْنِي مَاذَا يُبْكِيكَ أَنْتَ وَصَاحِبَكَ فَإِنْ وَجَدْتُ بُكَاءً بَكَيْتُ وَإِنْ لَمْ أَجِدْ بُكَاءً تَبَاكَيْتُ لِبُكَائِكُمَا قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي عَرَضَ عَلَيَّ أَصْحَابُكَ مِنْ الْفِدَاءِ لَقَدْ عُرِضَ عَلَيَّ عَذَابُكُمْ ‏ ‏أَدْنَى ‏ ‏مِنْ هَذِهِ الشَّجَرَةِ لِشَجَرَةٍ قَرِيبَةٍ وَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏مَا كَانَ لِنَبِيٍّ أَنْ يَكُونَ لَهُ أَسْرَى حَتَّى ‏ ‏يُثْخِنَ ‏ ‏فِي الْأَرْضِ ‏ ‏إِلَى قَوْلِهِ ‏ ‏لَوْلَا كِتَابٌ مِنْ اللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَا أَخَذْتُمْ ‏} ‏مِنْ الْفِدَاءِ ثُمَّ أُحِلَّ لَهُمْ الْغَنَائِمُ فَلَمَّا كَانَ يَوْمُ ‏ ‏أُحُدٍ ‏ ‏مِنْ الْعَامِ الْمُقْبِلِ عُوقِبُوا بِمَا صَنَعُوا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏مِنْ أَخْذِهِمْ الْفِدَاءَ فَقُتِلَ مِنْهُمْ سَبْعُونَ وَفَرَّ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكُسِرَتْ ‏ ‏رَبَاعِيَتُهُ ‏ ‏وَهُشِمَتْ ‏ ‏الْبَيْضَةُ ‏ ‏عَلَى رَأْسِهِ وَسَالَ الدَّمُ عَلَى وَجْهِهِ وَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏أَوَلَمَّا أَصَابَتْكُمْ مُصِيبَةٌ قَدْ أَصَبْتُمْ مِثْلَيْهَا ‏} ‏الْآيَةَ ‏ ‏بِأَخْذِكُمْ الْفِدَاءَ ‏","","",""],[204,204,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ قَالَ فَسَأَلْتُهُ عَنْ شَيْءٍ ثَلَاثَ مَرَّاتٍ فَلَمْ يَرُدَّ عَلَيَّ قَالَ فَقُلْتُ لِنَفْسِي ‏ ‏ثَكِلَتْكَ ‏ ‏أُمُّكَ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏نَزَرْتَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَ مَرَّاتٍ فَلَمْ يَرُدَّ عَلَيْكَ قَالَ فَرَكِبْتُ رَاحِلَتِي فَتَقَدَّمْتُ مَخَافَةَ أَنْ يَكُونَ نَزَلَ فِيَّ شَيْءٌ قَالَ فَإِذَا أَنَا بِمُنَادٍ يُنَادِي يَا ‏ ‏عُمَرُ ‏ ‏أَيْنَ ‏ ‏عُمَرُ ‏ ‏قَالَ فَرَجَعْتُ وَأَنَا أَظُنُّ أَنَّهُ نَزَلَ فِيَّ شَيْءٌ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَتْ عَلَيَّ الْبَارِحَةَ سُورَةٌ هِيَ أَحَبُّ إِلَيَّ مِنْ الدُّنْيَا وَمَا فِيهَا ‏ { ‏إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ ‏}","","",""],[205,205,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنِ ‏ ‏ابْنِ الْحَوْتَكِيَّةِ ‏ ‏قَالَ ‏ ‏أُتِيَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِطَعَامٍ فَدَعَا إِلَيْهِ رَجُلًا فَقَالَ إِنِّي صَائِمٌ ثُمَّ قَالَ وَأَيُّ الصِّيَامِ تَصُومُ لَوْلَا كَرَاهِيَةُ أَنْ أَزِيدَ أَوْ أَنْقُصَ لَحَدَّثْتُكُمْ بِحَدِيثِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ جَاءَهُ الْأَعْرَابِيُّ بِالْأَرْنَبِ وَلَكِنْ أَرْسِلُوا إِلَى ‏ ‏عَمَّارٍ ‏ ‏فَلَمَّا جَاءَ ‏ ‏عَمَّارٌ ‏ ‏قَالَ أَشَاهِدٌ أَنْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ جَاءَهُ الْأَعْرَابِيُّ بِالْأَرْنَبِ قَالَ نَعَمْ فَقَالَ إِنِّي رَأَيْتُ بِهَا دَمًا فَقَالَ كُلُوهَا قَالَ إِنِّي صَائِمٌ قَالَ وَأَيُّ الصِّيَامِ تَصُومُ قَالَ أَوَّلَ الشَّهْرِ وَآخِرَهُ قَالَ ‏ ‏إِنْ كُنْتَ صَائِمًا فَصُمْ الثَّلَاثَ عَشْرَةَ وَالْأَرْبَعَ عَشْرَةَ وَالْخَمْسَ عَشْرَةَ ‏","","",""],[206,206,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدُ بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَامِرٌ ‏ ‏عَنْ ‏ ‏مَسْرُوقِ بْنِ الْأَجْدَعِ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ لِي مَنْ أَنْتَ قُلْتُ ‏ ‏مَسْرُوقُ بْنُ الْأَجْدَعِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْأَجْدَعُ ‏ ‏شَيْطَانٌ وَلَكِنَّكَ ‏ ‏مَسْرُوقُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏عَامِرٌ ‏ ‏فَرَأَيْتُهُ فِي الدِّيوَانِ مَكْتُوبًا ‏ ‏مَسْرُوقُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏فَقُلْتُ مَا هَذَا فَقَالَ هَكَذَا سَمَّانِي ‏ ‏عُمَرُ ‏","","",""],[207,207,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَرَّرِ بْنِ أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الْعَزْلِ عَنْ الْحُرَّةِ إِلَّا بِإِذْنِهَا ‏","","",""],[208,208,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏يَقُولُ ‏ ‏لَئِنْ عِشْتُ إِلَى هَذَا الْعَامِ الْمُقْبِلِ لَا يُفْتَحُ لِلنَّاسِ قَرْيَةٌ ‏ ‏إِلَّا قَسَمْتُهَا بَيْنَهُمْ كَمَا ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏","","",""],[209,209,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ فَحَلَفْتُ لَا وَأَبِي فَهَتَفَ بِي رَجُلٌ مِنْ خَلْفِي فَقَالَ ‏ ‏لَا تَحْلِفُوا بِآبَائِكُمْ فَإِذَا هُوَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[210,210,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَئِنْ عِشْتُ إِنْ شَاءَ اللَّهُ لَأُخْرِجَنَّ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏مِنْ ‏ ‏جَزِيرَةِ الْعَرَبِ ‏","","",""],[211,211,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏","","",""],[212,212,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامٌ يَعْنِي أَبَا الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏سَيَّارِ بْنِ الْمَعْرُورِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَخْطُبُ وَهُوَ يَقُولُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَنَى هَذَا ‏ ‏الْمَسْجِدَ ‏ ‏وَنَحْنُ مَعَهُ ‏ ‏الْمُهَاجِرُونَ ‏ ‏وَالْأَنْصَارُ ‏ ‏فَإِذَا اشْتَدَّ الزِّحَامُ فَلْيَسْجُدْ الرَّجُلُ مِنْكُمْ عَلَى ظَهْرِ أَخِيهِ وَرَأَى قَوْمًا يُصَلُّونَ فِي الطَّرِيقِ فَقَالَ صَلُّوا فِي الْمَسْجِدِ ‏","","",""],[213,213,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ مُضَرِّبٍ ‏ ‏أَنَّهُ حَجَّ مَعَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَتَاهُ أَشْرَافُ أَهْلِ ‏ ‏الشَّامِ ‏ ‏فَقَالُوا يَا أَمِيرَ الْمُؤْمِنِينَ إِنَّا ‏ ‏أَصَبْنَا مِنْ أَمْوَالِنَا رَقِيقًا وَدَوَابَّ فَخُذْ مِنْ أَمْوَالِنَا ‏ ‏صَدَقَةً ‏ ‏تُطَهِّرُنَا بِهَا وَتَكُونُ لَنَا زَكَاةً فَقَالَ هَذَا شَيْءٌ لَمْ يَفْعَلْهُ اللَّذَانِ كَانَا مِنْ قَبْلِي وَلَكِنْ انْتَظِرُوا حَتَّى أَسْأَلَ الْمُسْلِمِينَ ‏","","",""],[214,214,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَمُؤَمَّلٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَئِنْ عِشْتُ لَأُخْرِجَنَّ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏مِنْ ‏ ‏جَزِيرَةِ الْعَرَبِ ‏ ‏حَتَّى لَا أَتْرُكَ فِيهَا إِلَّا مُسْلِمًا ‏","","",""],[215,215,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏وَعُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَقَدْ بَلَغَ بِهِ أَبِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَاتَهُ شَيْءٌ مِنْ وِرْدِهِ ‏ ‏أَوْ قَالَ مِنْ جُزْئِهِ ‏ ‏مِنْ اللَّيْلِ فَقَرَأَهُ مَا بَيْنَ صَلَاةِ الْفَجْرِ إِلَى الظُّهْرِ فَكَأَنَّمَا قَرَأَهُ مِنْ لَيْلَتِهِ ‏","","",""],[216,216,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ قُرَادٌ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ الْحَنَفِيُّ أَبُو زُمَيْلٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏حَدَّثَنِي ‏ ‏عُمَرُ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏بَدْرٍ ‏ ‏قَالَ نَظَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَصْحَابِهِ وَهُمْ ثَلَاثُ مِائَةٍ وَنَيِّفٌ وَنَظَرَ إِلَى الْمُشْرِكِينَ فَإِذَا هُمْ أَلْفٌ وَزِيَادَةٌ فَاسْتَقْبَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقِبْلَةَ ثُمَّ مَدَّ يَدَهُ وَعَلَيْهِ رِدَاؤُهُ وَإِزَارُهُ ثُمَّ قَالَ ‏ ‏اللَّهُمَّ أَيْنَ مَا وَعَدْتَنِي اللَّهُمَّ أَنْجِزْ مَا وَعَدْتَنِي اللَّهُمَّ إِنْ تُهْلِكْ هَذِهِ ‏ ‏الْعِصَابَةَ ‏ ‏مِنْ أَهْلِ الْإِسْلَامِ فَلَا تُعْبَدْ فِي الْأَرْضِ أَبَدًا قَالَ فَمَا زَالَ يَسْتَغِيثُ رَبَّهُ ‏ ‏وَيَدْعُوهُ حَتَّى سَقَطَ رِدَاؤُهُ فَأَتَاهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَأَخَذَ رِدَاءَهُ فَرَدَّاهُ ثُمَّ الْتَزَمَهُ مِنْ وَرَائِهِ ثُمَّ قَالَ يَا نَبِيَّ اللَّهِ كَفَاكَ مُنَاشَدَتُكَ رَبَّكَ فَإِنَّهُ سَيُنْجِزُ لَكَ مَا وَعَدَكَ وَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُمْ بِأَلْفٍ مِنْ الْمَلَائِكَةِ ‏ ‏مُرْدِفِينَ ‏ } ‏فَلَمَّا كَانَ يَوْمُئِذٍ وَالْتَقَوْا فَهَزَمَ اللَّهُ الْمُشْرِكِينَ فَقُتِلَ مِنْهُمْ سَبْعُونَ رَجُلًا وَأُسِرَ مِنْهُمْ سَبْعُونَ رَجُلًا فَاسْتَشَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعَلِيًّا ‏ ‏وَعُمَرَ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا نَبِيَّ اللَّهِ هَؤُلَاءِ بَنُو الْعَمِّ وَالْعَشِيرَةُ وَالْإِخْوَانُ فَأَنَا أَرَى أَنْ تَأْخُذَ مِنْهُمْ الْفِدَاءَ فَيَكُونُ مَا أَخَذْنَا مِنْهُمْ ‏ ‏قُوَّةً ‏ ‏لَنَا عَلَى الْكُفَّارِ وَعَسَى اللَّهُ عَزَّ وَجَلَّ أَنْ يَهْدِيَهُمْ فَيَكُونُونَ لَنَا ‏ ‏عَضُدًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏تَرَى يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏فَقَالَ قُلْتُ وَاللَّهِ مَا أَرَى مَا رَأَى ‏ ‏أَبُو بَكْرٍ ‏ ‏وَلَكِنِّي أَرَى أَنْ تُمَكِّنَنِي مِنْ فُلَانٍ قَرِيبٍ ‏ ‏لِعُمَرَ ‏ ‏فَأَضْرِبَ عُنُقَهُ وَتُمَكِّنَ ‏ ‏عَلِيًّا ‏ ‏مِنْ ‏ ‏عَقِيلٍ ‏ ‏فَيَضْرِبَ عُنُقَهُ وَتُمَكِّنَ ‏ ‏حَمْزَةَ ‏ ‏مِنْ فُلَانٍ أَخِيهِ فَيَضْرِبَ عُنُقَهُ حَتَّى يَعْلَمَ اللَّهُ أَنَّهُ لَيْسَ فِي قُلُوبِنَا هَوَادَةٌ لِلْمُشْرِكِينَ هَؤُلَاءِ ‏ ‏صَنَادِيدُهُمْ ‏ ‏وَأَئِمَّتُهُمْ وَقَادَتُهُمْ فَهَوِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَلَمْ يَهْوَ مَا قُلْتُ فَأَخَذَ مِنْهُمْ الْفِدَاءَ فَلَمَّا كَانَ مِنْ الْغَدِ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏غَدَوْتُ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا هُوَ قَاعِدٌ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَإِذَا هُمَا يَبْكِيَانِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَخْبِرْنِي مَاذَا يُبْكِيكَ أَنْتَ وَصَاحِبَكَ فَإِنْ وَجَدْتُ بُكَاءً بَكَيْتُ وَإِنْ لَمْ أَجِدْ بُكَاءً تَبَاكَيْتُ لِبُكَائِكُمَا قَالَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي عَرَضَ عَلَيَّ أَصْحَابُكَ مِنْ الْفِدَاءِ وَلَقَدْ عُرِضَ عَلَيَّ عَذَابُكُمْ أَدْنَى مِنْ هَذِهِ الشَّجَرَةِ لِشَجَرَةٍ قَرِيبَةٍ وَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏مَا كَانَ لِنَبِيٍّ أَنْ يَكُونَ لَهُ أَسْرَى حَتَّى ‏ ‏يُثْخِنَ ‏ ‏فِي الْأَرْضِ ‏ ‏إِلَى قَوْلِهِ ‏ ‏لَمَسَّكُمْ فِيمَا أَخَذْتُمْ ‏} ‏مِنْ الْفِدَاءِ ثُمَّ أُحِلَّ لَهُمْ الْغَنَائِمُ فَلَمَّا كَانَ يَوْمُ ‏ ‏أُحُدٍ ‏ ‏مِنْ الْعَامِ الْمُقْبِلِ عُوقِبُوا بِمَا صَنَعُوا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏مِنْ أَخْذِهِمْ الْفِدَاءَ فَقُتِلَ مِنْهُمْ سَبْعُونَ وَفَرَّ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكُسِرَتْ ‏ ‏رَبَاعِيَتُهُ ‏ ‏وَهُشِمَتْ ‏ ‏الْبَيْضَةُ ‏ ‏عَلَى رَأْسِهِ وَسَالَ الدَّمُ عَلَى وَجْهِهِ فَأَنْزَلَ اللَّهُ ‏ { ‏أَوَلَمَّا أَصَابَتْكُمْ مُصِيبَةٌ قَدْ أَصَبْتُمْ مِثْلَيْهَا ‏ ‏إِلَى قَوْلِهِ ‏ ‏إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏} ‏بِأَخْذِكُمْ الْفِدَاءَ ‏","","",""],[217,217,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي ثَوْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏لَمْ أَزَلْ حَرِيصًا عَلَى أَنْ أَسْأَلَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ الْمَرْأَتَيْنِ مِنْ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّتَيْنِ قَالَ اللَّهُ تَعَالَى ‏ { ‏إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ‏} ‏حَتَّى حَجَّ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَحَجَجْتُ مَعَهُ فَلَمَّا كُنَّا بِبَعْضِ الطَّرِيقِ ‏ ‏عَدَلَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَعَدَلْتُ ‏ ‏مَعَهُ ‏ ‏بِالْإِدَاوَةِ ‏ ‏فَتَبَرَّزَ ثُمَّ أَتَانِي فَسَكَبْتُ عَلَى يَدَيْهِ فَتَوَضَّأَ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ مَنْ الْمَرْأَتَانِ مِنْ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّتَانِ قَالَ اللَّهُ تَعَالَى ‏ { ‏إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ‏} ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَاعَجَبًا لَكَ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏كَرِهَ وَاللَّهِ مَا سَأَلَهُ عَنْهُ وَلَمْ يَكْتُمْهُ عَنْهُ ‏ ‏قَالَ هِيَ ‏ ‏حَفْصَةُ ‏ ‏وَعَائِشَةُ ‏ ‏قَالَ ثُمَّ أَخَذَ يَسُوقُ الْحَدِيثَ قَالَ كُنَّا ‏ ‏مَعْشَرَ ‏ ‏قُرَيْشٍ ‏ ‏قَوْمًا نَغْلِبُ النِّسَاءَ فَلَمَّا قَدِمْنَا ‏ ‏الْمَدِينَةَ ‏ ‏وَجَدْنَا قَوْمًا تَغْلِبُهُمْ نِسَاؤُهُمْ ‏ ‏فَطَفِقَ ‏ ‏نِسَاؤُنَا يَتَعَلَّمْنَ مِنْ نِسَائِهِمْ قَالَ وَكَانَ مَنْزِلِي فِي ‏ ‏بَنِي أُمَيَّةَ بْنِ زَيْدٍ ‏ ‏بِالْعَوَالِي ‏ ‏قَالَ فَتَغَضَّبْتُ يَوْمًا عَلَى امْرَأَتِي فَإِذَا هِيَ تُرَاجِعُنِي فَأَنْكَرْتُ أَنْ تُرَاجِعَنِي فَقَالَتْ مَا تُنْكِرُ أَنْ أُرَاجِعَكَ فَوَاللَّهِ إِنَّ أَزْوَاجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُرَاجِعْنَهُ ‏ ‏وَتَهْجُرُهُ إِحْدَاهُنَّ الْيَوْمَ إِلَى اللَّيْلِ قَالَ فَانْطَلَقْتُ فَدَخَلْتُ عَلَى ‏ ‏حَفْصَةَ ‏ ‏فَقُلْتُ أَتُرَاجِعِينَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ نَعَمْ قُلْتُ وَتَهْجُرُهُ إِحْدَاكُنَّ الْيَوْمَ إِلَى اللَّيْلِ قَالَتْ نَعَمْ قُلْتُ قَدْ خَابَ مَنْ فَعَلَ ذَلِكَ مِنْكُنَّ وَخَسِرَ أَفَتَأْمَنُ إِحْدَاكُنَّ أَنْ يَغْضَبَ اللَّهُ عَلَيْهَا لِغَضَبِ رَسُولِهِ فَإِذَا هِيَ قَدْ هَلَكَتْ لَا تُرَاجِعِي رَسُولَ اللَّهِ وَلَا تَسْأَلِيهِ شَيْئًا وَسَلِينِي مَا بَدَا لَكِ وَلَا ‏ ‏يَغُرَّنَّكِ ‏ ‏إِنْ كَانَتْ جَارَتُكِ هِيَ أَوْسَمَ وَأَحَبَّ إِلَى رَسُولِ اللَّهِ مِنْكِ يُرِيدُ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَ وَكَانَ لِي جَارٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَكُنَّا نَتَنَاوَبُ النُّزُولَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَنْزِلُ يَوْمًا وَأَنْزِلُ يَوْمًا فَيَأْتِينِي بِخَبَرِ الْوَحْيِ وَغَيْرِهِ وَآتِيهِ بِمِثْلِ ذَلِكَ قَالَ وَكُنَّا نَتَحَدَّثُ أَنَّ ‏ ‏غَسَّانَ ‏ ‏تُنْعِلُ ‏ ‏الْخَيْلَ لِتَغْزُوَنَا فَنَزَلَ صَاحِبِي يَوْمًا ثُمَّ أَتَانِي عِشَاءً فَضَرَبَ بَابِي ثُمَّ نَادَانِي فَخَرَجْتُ إِلَيْهِ فَقَالَ حَدَثَ أَمْرٌ عَظِيمٌ قُلْتُ وَمَاذَا أَجَاءَتْ ‏ ‏غَسَّانُ ‏ ‏قَالَ لَا بَلْ أَعْظَمُ مِنْ ذَلِكَ وَأَطْوَلُ طَلَّقَ الرَّسُولُ نِسَاءَهُ فَقُلْتُ قَدْ خَابَتْ ‏ ‏حَفْصَةُ ‏ ‏وَخَسِرَتْ قَدْ كُنْتُ أَظُنُّ هَذَا كَائِنًا حَتَّى إِذَا صَلَّيْتُ الصُّبْحَ شَدَدْتُ عَلَيَّ ثِيَابِي ثُمَّ نَزَلْتُ فَدَخَلْتُ عَلَى ‏ ‏حَفْصَةَ ‏ ‏وَهِيَ تَبْكِي فَقُلْتُ أَطَلَّقَكُنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ لَا أَدْرِي هُوَ هَذَا مُعْتَزِلٌ فِي هَذِهِ ‏ ‏الْمَشْرُبَةِ ‏ ‏فَأَتَيْتُ غُلَامًا لَهُ أَسْوَدَ فَقُلْتُ اسْتَأْذِنْ ‏ ‏لِعُمَرَ ‏ ‏فَدَخَلَ الْغُلَامُ ثُمَّ خَرَجَ إِلَيَّ فَقَالَ قَدْ ذَكَرْتُكَ لَهُ فَصَمَتَ فَانْطَلَقْتُ حَتَّى أَتَيْتُ الْمِنْبَرَ فَإِذَا عِنْدَهُ ‏ ‏رَهْطٌ ‏ ‏جُلُوسٌ يَبْكِي بَعْضُهُمْ فَجَلَسْتُ قَلِيلًا ثُمَّ غَلَبَنِي مَا أَجِدُ فَأَتَيْتُ الْغُلَامَ فَقُلْتُ اسْتَأْذِنْ ‏ ‏لِعُمَرَ ‏ ‏فَدَخَلَ الْغُلَامُ ثُمَّ خَرَجَ ‏ ‏عَلَيَّ ‏ ‏فَقَالَ قَدْ ذَكَرْتُكَ لَهُ فَصَمَتَ فَخَرَجْتُ فَجَلَسْتُ إِلَى الْمِنْبَرِ ثُمَّ ‏ ‏غَلَبَنِي ‏ ‏مَا أَجِدُ فَأَتَيْتُ الْغُلَامَ فَقُلْتُ اسْتَأْذِنْ ‏ ‏لِعُمَرَ ‏ ‏فَدَخَلَ ثُمَّ خَرَجَ إِلَيَّ فَقَالَ قَدْ ذَكَرْتُكَ لَهُ فَصَمَتَ فَوَلَّيْتُ ‏ ‏مُدْبِرًا ‏ ‏فَإِذَا الْغُلَامُ يَدْعُونِي فَقَالَ ادْخُلْ فَقَدْ أَذِنَ لَكَ فَدَخَلْتُ فَسَلَّمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا هُوَ مُتَّكِئٌ عَلَى ‏ ‏رَمْلِ ‏ ‏حَصِيرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَاه ‏ ‏يَعْقُوبُ ‏ ‏فِي حَدِيثِ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏رُمَالِ حَصِيرٍ قَدْ أَثَّرَ فِي جَنْبِهِ فَقُلْتُ أَطَلَّقْتَ يَا رَسُولَ اللَّهِ نِسَاءَكَ فَرَفَعَ رَأْسَهُ إِلَيَّ وَقَالَ لَا فَقُلْتُ اللَّهُ أَكْبَرُ لَوْ رَأَيْتَنَا يَا رَسُولَ اللَّهِ وَكُنَّا مَعْشَرَ ‏ ‏قُرَيْشٍ ‏ ‏قَوْمًا نَغْلِبُ النِّسَاءَ فَلَمَّا قَدِمْنَا ‏ ‏الْمَدِينَةَ ‏ ‏وَجَدْنَا قَوْمًا تَغْلِبُهُمْ نِسَاؤُهُمْ فَطَفِقَ نِسَاؤُنَا يَتَعَلَّمْنَ مِنْ نِسَائِهِمْ فَتَغَضَّبْتُ عَلَى امْرَأَتِي يَوْمًا فَإِذَا هِيَ تُرَاجِعُنِي فَأَنْكَرْتُ أَنْ تُرَاجِعَنِي فَقَالَتْ مَا تُنْكِرُ أَنْ أُرَاجِعَكَ فَوَاللَّهِ إِنَّ أَزْوَاجَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُرَاجِعْنَهُ وَتَهْجُرُهُ إِحْدَاهُنَّ الْيَوْمَ إِلَى اللَّيْلِ فَقُلْتُ قَدْ خَابَ مَنْ فَعَلَ ذَلِكَ مِنْهُنَّ وَخَسِرَ أَفَتَأْمَنُ إِحْدَاهُنَّ أَنْ يَغْضَبَ اللَّهُ عَلَيْهَا لِغَضَبِ رَسُولِهِ فَإِذَا هِيَ قَدْ هَلَكَتْ فَتَبَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ فَدَخَلْتُ عَلَى ‏ ‏حَفْصَةَ ‏ ‏فَقُلْتُ لَا يَغُرُّكِ إِنْ كَانَتْ جَارَتُكِ هِيَ أَوْسَمَ وَأَحَبَّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْكِ فَتَبَسَّمَ أُخْرَى فَقُلْتُ أَسْتَأْنِسُ يَا رَسُولَ اللَّهِ قَالَ نَعَمْ فَجَلَسْتُ فَرَفَعْتُ رَأْسِي فِي الْبَيْتِ فَوَاللَّهِ مَا رَأَيْتُ فِيهِ شَيْئًا يَرُدُّ الْبَصَرَ إِلَّا ‏ ‏أَهَبَةً ثَلَاثَةً فَقُلْتُ ادْعُ يَا رَسُولَ اللَّهِ أَنْ يُوَسِّعَ عَلَى أُمَّتِكَ فَقَدْ وُسِّعَ عَلَى ‏ ‏فَارِسَ ‏ ‏وَالرُّومِ ‏ ‏وَهُمْ لَا يَعْبُدُونَ اللَّهَ فَاسْتَوَى جَالِسًا ثُمَّ قَالَ أَفِي شَكٍّ أَنْتَ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏أُولَئِكَ قَوْمٌ عُجِّلَتْ لَهُمْ طَيِّبَاتُهُمْ فِي الْحَيَاةِ الدُّنْيَا فَقُلْتُ اسْتَغْفِرْ لِي يَا رَسُولَ اللَّهِ وَكَانَ أَقْسَمَ أَنْ لَا يَدْخُلَ عَلَيْهِنَّ شَهْرًا مِنْ شِدَّةِ ‏ ‏مَوْجِدَتِهِ ‏ ‏عَلَيْهِنَّ حَتَّى عَاتَبَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[218,218,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ بْنُ سُلَيْمٍ ‏ ‏قَالَ أَمْلَى عَلَيَّ ‏ ‏يُونُسُ بْنُ يَزِيدَ الْأَيْلِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدٍ الْقَارِيِّ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏كَانَ إِذَا نَزَلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَحْيُ يُسْمَعُ عِنْدَ وَجْهِهِ ‏ ‏دَوِيٌّ ‏ ‏كَدَوِيِّ ‏ ‏النَّحْلِ فَمَكَثْنَا سَاعَةً فَاسْتَقْبَلَ الْقِبْلَةَ وَرَفَعَ يَدَيْهِ فَقَالَ ‏ ‏اللَّهُمَّ زِدْنَا وَلَا تَنْقُصْنَا وَأَكْرِمْنَا وَلَا تُهِنَّا وَأَعْطِنَا وَلَا تَحْرِمْنَا وَآثِرْنَا وَلَا تُؤْثِرْ عَلَيْنَا وَارْضَ عَنَّا وَأَرْضِنَا ثُمَّ قَالَ لَقَدْ أُنْزِلَتْ عَلَيَّ عَشْرُ آيَاتٍ مَنْ أَقَامَهُنَّ دَخَلَ الْجَنَّةَ ثُمَّ قَرَأَ عَلَيْنَا ‏ { ‏قَدْ أَفْلَحَ الْمُؤْمِنُونَ ‏} ‏حَتَّى خَتَمَ الْعَشْرَ ‏","","",""],[219,219,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهُ شَهِدَ الْعِيدَ مَعَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَصَلَّى قَبْلَ أَنْ يَخْطُبَ ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ثُمَّ خَطَبَ فَقَالَ يَا أَيُّهَا النَّاسُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ صِيَامِ هَذَيْنِ الْيَوْمَيْنِ أَمَّا أَحَدُهُمَا فَيَوْمُ فِطْرِكُمْ مِنْ صِيَامِكُمْ وَعِيدُكُمْ وَأَمَّا الْآخَرُ فَيَوْمٌ تَأْكُلُونَ فِيهِ مِنْ نُسُكِكُمْ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ ‏ ‏قَالَ ‏ ‏شَهِدْتُ الْعِيدَ مَعَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[220,220,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَبَّلَ الْحَجَرَ ثُمَّ قَالَ قَدْ عَلِمْتُ أَنَّكَ حَجَرٌ وَلَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبَّلَكَ مَا قَبَّلْتُكَ ‏","","",""],[221,221,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنِي ‏ ‏سَيَّارٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏أَنَّ رَجُلًا كَانَ نَصْرَانِيًّا يُقَالُ لَهُ ‏ ‏الصُّبَيُّ بْنُ مَعْبَدٍ ‏ ‏أَسْلَمَ فَأَرَادَ الْجِهَادَ فَقِيلَ لَهُ ابْدَأْ بِالْحَجِّ فَأَتَى ‏ ‏الْأَشْعَرِيَّ ‏ ‏فَأَمَرَهُ أَنْ ‏ ‏يُهِلَّ ‏ ‏بِالْحَجِّ وَالْعُمْرَةِ جَمِيعًا فَفَعَلَ فَبَيْنَمَا هُوَ يُلَبِّي إِذْ مَرَّ ‏ ‏يَزِيدُ بْنُ صُوحَانَ ‏ ‏وَسَلْمَانُ بْنُ رَبِيعَةَ ‏ ‏فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ لَهَذَا أَضَلُّ مِنْ بَعِيرِ أَهْلِهِ فَسَمِعَهَا ‏ ‏الصُّبَيُّ ‏ ‏فَكَبُرَ ذَلِكَ عَلَيْهِ فَلَمَّا قَدِمَ أَتَى ‏ ‏عُمَرَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏هُدِيتَ لِسُنَّةِ نَبِيِّكَ ‏ ‏قَالَ وَسَمِعْتُهُ ‏ ‏مَرَّةً أُخْرَى يَقُولُ وُفِّقْتَ لِسُنَّةِ نَبِيِّكَ ‏","","",""],[222,222,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْمُرُ ‏ ‏عِنْدَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اللَّيْلَةَ كَذَاكَ فِي الْأَمْرِ مِنْ أَمْرِ الْمُسْلِمِينَ وَأَنَا مَعَهُ ‏","","",""],[223,223,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَرْجِسَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏الْأُصَيْلِعَ يَعْنِي عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُقَبِّلُ ‏ ‏الْحَجَرَ وَيَقُولُ إِنِّي لَأُقَبِّلُكَ وَأَعْلَمُ أَنَّكَ حَجَرٌ لَا تَنْفَعُ وَلَا تَضُرُّ وَلَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُكَ لَمْ أُقَبِّلْكَ ‏","","",""],[224,224,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَيَرْقُدُ أَحَدُنَا وَهُوَ جُنُبٌ قَالَ نَعَمْ إِذَا تَوَضَّأَ ‏","","",""],[225,225,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَقْبَلَ اللَّيْلُ ‏ ‏وَأَدْبَرَ ‏ ‏النَّهَارُ وَغَابَتْ الشَّمْسُ فَقَدْ أَفْطَرْتَ ‏","","",""],[226,226,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ عَامِرِ بْنِ وَاثِلَةَ ‏ ‏أَنَّ ‏ ‏نَافِعَ بْنَ عَبْدِ الْحَارِثِ ‏ ‏لَقِيَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِعُسْفَانَ ‏ ‏وَكَانَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اسْتَعْمَلَهُ عَلَى ‏ ‏مَكَّةَ ‏ ‏فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَنْ اسْتَخْلَفْتَ عَلَى أَهْلِ ‏ ‏الْوَادِي ‏ ‏قَالَ اسْتَخْلَفْتُ عَلَيْهِمْ ‏ ‏ابْنَ أَبْزَى ‏ ‏قَالَ وَمَا ‏ ‏ابْنُ أَبْزَى ‏ ‏فَقَالَ رَجُلٌ مِنْ مَوَالِينَا فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اسْتَخْلَفْتَ عَلَيْهِمْ ‏ ‏مَوْلًى ‏ ‏فَقَالَ إِنَّهُ قَارِئٌ لِكِتَابِ اللَّهِ عَالِمٌ ‏ ‏بِالْفَرَائِضِ ‏ ‏قَاضٍ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَمَا إِنَّ نَبِيَّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ قَالَ ‏ ‏إِنَّ اللَّهَ يَرْفَعُ بِهَذَا الْكِتَابِ أَقْوَامًا وَيَضَعُ بِهِ آخَرِينَ ‏","","",""],[227,227,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ سُمَيْعٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏لِأَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏ابْسُطْ يَدَكَ حَتَّى أُبَايِعَكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَنْتَ أَمِينُ هَذِهِ الْأُمَّةِ فَقَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏مَا كُنْتُ لِأَتَقَدَّمَ بَيْنَ يَدَيْ رَجُلٍ أَمَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَؤُمَّنَا فَأَمَّنَا حَتَّى مَاتَ ‏","","",""],[228,228,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِسْمَةً فَقُلْتُ يَا رَسُولَ اللَّهِ لَغَيْرُ هَؤُلَاءِ أَحَقُّ مِنْهُمْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُمْ ‏ ‏خَيَّرُونِي بَيْنَ أَنْ يَسْأَلُونِي بِالْفُحْشِ أَوْ يُبَخِّلُونِي فَلَسْتُ بِبَاخِلٍ ‏","","",""],[229,229,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ يَنَامُ أَحَدُنَا وَهُوَ جُنُبٌ قَالَ نَعَمْ وَيَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[230,230,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏ابْنُ عُمَرَ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏يَمْسَحُ عَلَى خُفَّيْهِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَإِنَّكُمْ لَتَفْعَلُونَ هَذَا فَقَالَ ‏ ‏سَعْدٌ ‏ ‏نَعَمْ فَاجْتَمَعَا عِنْدَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ ‏ ‏سَعْدٌ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ أَفْتِ ابْنَ أَخِي فِي الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كُنَّا وَنَحْنُ مَعَ نَبِيِّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَمْسَحُ عَلَى خِفَافِنَا فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَإِنْ جَاءَ مِنْ الْغَائِطِ وَالْبَوْلِ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏نَعَمْ وَإِنْ جَاءَ مِنْ الْغَائِطِ وَالْبَوْلِ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏فَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏بَعْدَ ذَلِكَ يَمْسَحُ عَلَيْهِمَا مَا لَمْ يَخْلَعْهُمَا وَمَا يُوَقِّتُ لِذَلِكَ وَقْتًا ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏مَعْمَرًا ‏ ‏فَقَالَ حَدَّثَنِيهِ ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏مِثْلَهُ ‏","","",""],[231,231,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكُ بْنُ أَوْسِ بْنِ الْحَدَثَانِ ‏ ‏قَالَ ‏ ‏صَرَفْتُ عِنْدَ ‏ ‏طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏وَرِقًا ‏ ‏بِذَهَبٍ فَقَالَ أَنْظِرْنِي حَتَّى يَأْتِيَنَا خَازِنُنَا مِنْ ‏ ‏الْغَابَةِ ‏ ‏قَالَ فَسَمِعَهَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ لَا وَاللَّهِ لَا تُفَارِقُهُ حَتَّى تَسْتَوْفِيَ مِنْهُ صَرْفَهُ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الذَّهَبُ ‏ ‏بِالْوَرِقِ ‏ ‏رِبًا ‏ ‏إِلَّا ‏ ‏هَاءَ وَهَاءَ ‏","","",""],[232,232,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏لَمَّا ارْتَدَّ أَهْلُ الرِّدَّةِ فِي زَمَانِ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏كَيْفَ تُقَاتِلُ النَّاسَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏وَقَدْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوا لَا إِلَهَ إِلَّا ‏ ‏اللَّهُ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّهَا وَحِسَابُهُمْ عَلَى اللَّهِ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَاللَّهِ لَأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلَاةِ وَالزَّكَاةِ فَإِنَّ الزَّكَاةَ حَقُّ الْمَالِ وَاللَّهِ لَوْ مَنَعُونِي ‏ ‏عَنَاقًا ‏ ‏كَانُوا يُؤَدُّونَهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَاتَلْتُهُمْ عَلَيْهَا ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَوَاللَّهِ مَا هُوَ إِلَّا أَنْ رَأَيْتُ أَنَّ اللَّهَ قَدْ شَرَحَ صَدْرَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لِلْقِتَالِ فَعَرَفْتُ أَنَّهُ الْحَقُّ ‏","","",""],[233,233,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كُنْتُ فِي ‏ ‏رَكْبٍ ‏ ‏أَسِيرُ فِي غَزَاةٍ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَلَفْتُ فَقُلْتُ لَا وَأَبِي فَنَهَرَنِي رَجُلٌ مِنْ خَلْفِي وَقَالَ ‏ ‏لَا تَحْلِفُوا بِآبَائِكُمْ فَالْتَفَتُّ فَإِذَا أَنَا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[234,234,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أَحْلِفُ بِأَبِي فَقَالَ ‏ ‏إِنَّ اللَّهَ يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏فَوَاللَّهِ مَا حَلَفْتُ بِهَا بَعْدُ ذَاكِرًا وَلَا آثِرًا ‏","","",""],[235,235,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي الْحَرِيرِ فِي إِصْبَعَيْنِ ‏","","",""],[236,236,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏عُتْبَةَ بْنِ فَرْقَدٍ ‏ ‏فَكَتَبَ إِلَيْهِ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِأَشْيَاءَ يُحَدِّثُهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ فِيمَا كَتَبَ إِلَيْهِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَلْبَسُ الْحَرِيرَ فِي الدُّنْيَا إِلَّا مَنْ لَيْسَ لَهُ فِي الْآخِرَةِ مِنْهُ شَيْءٌ إِلَّا هَكَذَا وَقَالَ بِإِصْبَعَيْهِ السَّبَّابَةِ وَالْوُسْطَى ‏ ‏قَالَ ‏ ‏أَبُو عُثْمَانَ ‏ ‏فَرَأَيْتُ أَنَّهَا أَزْرَارُ ‏ ‏الطَّيَالِسَةِ ‏ ‏حِينَ رَأَيْنَا ‏ ‏الطَّيَالِسَةَ ‏","","",""],[237,237,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَيْهِ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِقْصَارُ النَّاسِ الصَّلَاةَ الْيَوْمَ وَإِنَّمَا قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنْ خِفْتُمْ أَنْ يَفْتِنَكُمْ الَّذِينَ كَفَرُوا ‏} ‏فَقَدْ ذَهَبَ ذَاكَ الْيَوْمَ فَقَالَ عَجِبْتُ مِمَّا عَجِبْتَ مِنْهُ فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏صَدَقَةٌ ‏ ‏تَصَدَّقَ اللَّهُ بِهَا عَلَيْكُمْ فَاقْبَلُوا صَدَقَتَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَبْدِ اللَّهِ بْنِ أَبِي عَمَّارٍ ‏ ‏يُحَدِّثُ ‏ ‏فَذَكَرَهُ ‏","","",""],[238,238,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ آخِرَ مَا نَزَلَ مِنْ الْقُرْآنِ ‏ ‏آيَةُ الرِّبَا ‏ ‏وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُبِضَ ‏ ‏وَلَمْ يُفَسِّرْهَا ‏ ‏فَدَعُوا الرِّبَا ‏ ‏وَالرِّيبَةَ ‏","","",""],[239,239,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَيِّتُ يُعَذَّبُ فِي قَبْرِهِ ‏ ‏بِالنِّيَاحَةِ ‏ ‏عَلَيْهِ ‏","","",""],[240,240,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُعَذَّبُ الْمَيِّتُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ ‏","","",""],[241,241,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ أَنْ تَهْلِكُوا عَنْ آيَةِ الرَّجْمِ لَا نَجِدُ ‏ ‏حَدَّيْنِ ‏ ‏فِي كِتَابِ اللَّهِ فَقَدْ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏رَجَمَ وَقَدْ رَجَمْنَا ‏","","",""],[242,242,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَافَقْتُ رَبِّي ‏ ‏فِي ثَلَاثٍ وَوَافَقَنِي رَبِّي فِي ثَلَاثٍ قُلْتُ يَا رَسُولَ اللَّهِ لَوْ اتَّخَذْتَ مِنْ ‏ ‏مَقَامِ ‏ ‏إِبْرَاهِيمَ ‏ ‏مُصَلًّى فَأَنْزَلَ اللَّهُ ‏ { ‏وَاتَّخِذُوا مِنْ ‏ ‏مَقَامِ ‏ ‏إِبْرَاهِيمَ ‏ ‏مُصَلًّى ‏} ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّهُ يَدْخُلُ عَلَيْكَ ‏ ‏الْبَرُّ ‏ ‏وَالْفَاجِرُ ‏ ‏فَلَوْ أَمَرْتَ ‏ ‏أُمَّهَاتِ الْمُؤْمِنِينَ بِالْحِجَابِ فَأَنْزَلَ اللَّهُ ‏ ‏آيَةَ الْحِجَابِ ‏ ‏وَبَلَغَنِي مُعَاتَبَةُ النَّبِيِّ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏بَعْضَ نِسَائِهِ قَالَ فَاسْتَقْرَيْتُ ‏ ‏أُمَّهَاتِ الْمُؤْمِنِينَ فَدَخَلْتُ عَلَيْهِنَّ فَجَعَلْتُ ‏ ‏أَسْتَقْرِيهِنَّ وَاحِدَةً وَاحِدَةً وَاللَّهِ لَئِنْ انْتَهَيْتُنَّ وَإِلَّا لَيُبَدِّلَنَّ اللَّهُ رَسُولَهُ خَيْرًا مِنْكُنَّ قَالَ فَأَتَيْتُ عَلَى بَعْضِ نِسَائِهِ قَالَتْ يَا ‏ ‏عُمَرُ ‏ ‏أَمَا فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَعِظُ نِسَاءَهُ حَتَّى تَكُونَ ‏ ‏أَنْتَ تَعِظُهُنَّ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏عَسَى رَبُّهُ إِنْ طَلَّقَكُنَّ أَنْ يُبْدِلَهُ أَزْوَاجًا خَيْرًا مِنْكُنَّ ‏}","","",""],[243,243,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو ذِبْيَانَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏يَقُولُ ‏ ‏لَا تُلْبِسُوا نِسَاءَكُمْ الْحَرِيرَ فَإِنِّي ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏يُحَدِّثُ يَقُولُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الْآخِرَةِ ‏ ‏و قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏مِنْ عِنْدِهِ ‏ ‏وَمَنْ لَمْ يَلْبَسْهُ فِي الْآخِرَةِ لَمْ يَدْخُلْ الْجَنَّةَ قَالَ اللَّهُ تَعَالَى ‏ { ‏وَلِبَاسُهُمْ فِيهَا حَرِيرٌ ‏}","","",""],[244,244,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏مَرَّ ‏ ‏عُمَرُ ‏ ‏بِطَلْحَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏قَالَ ‏ ‏مَرَّ ‏ ‏عُمَرُ ‏ ‏بِطَلْحَةَ ‏ ‏فَرَآهُ مُهْتَمًّا قَالَ لَعَلَّكَ سَاءَكَ ‏ ‏إِمَارَةُ ‏ ‏ابْنِ عَمِّكَ قَالَ ‏ ‏يَعْنِي ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ لَا وَلَكِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنِّي لَأَعْلَمُ كَلِمَةً لَا يَقُولُهَا الرَّجُلُ عِنْدَ مَوْتِهِ إِلَّا كَانَتْ نُورًا فِي صَحِيفَتِهِ أَوْ وَجَدَ لَهَا رَوْحًا عِنْدَ الْمَوْتِ قَالَ ‏ ‏عُمَرُ ‏ ‏أَنَا أُخْبِرُكَ بِهَا هِيَ الْكَلِمَةُ الَّتِي أَرَادَ بِهَا عَمَّهُ ‏ ‏شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ قَالَ فَكَأَنَّمَا كُشِفَ عَنِّي غِطَاءٌ قَالَ صَدَقْتَ لَوْ عَلِمَ كَلِمَةً هِيَ أَفْضَلُ مِنْهَا لَأَمَرَهُ بِهَا ‏","","",""],[245,245,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ بْنُ عَتِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَيْهِ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏طُفْتُ مَعَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَلَمَّا كُنْتُ عِنْدَ الرُّكْنِ الَّذِي ‏ ‏يَلِي ‏ ‏الْبَابَ مِمَّا ‏ ‏يَلِي ‏ ‏الْحَجَرَ أَخَذْتُ بِيَدِهِ لِيَسْتَلِمَ فَقَالَ أَمَا طُفْتَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ بَلَى قَالَ فَهَلْ رَأَيْتَهُ ‏ ‏يَسْتَلِمُهُ ‏ ‏قُلْتُ لَا قَالَ ‏ ‏فَانْفُذْ عَنْكَ فَإِنَّ لَكَ فِي رَسُولِ اللَّهِ أُسْوَةً حَسَنَةً ‏","","",""],[246,246,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏حَدَّثَنَا ‏ ‏شَقِيقٌ ‏ ‏حَدَّثَنِي ‏ ‏الصُّبَيُّ بْنُ مَعْبَدٍ ‏ ‏وَكَانَ رَجُلًا مِنْ ‏ ‏بَنِي تَغْلِبَ ‏ ‏قَالَ ‏ ‏كُنْتُ نَصْرَانِيًّا فَأَسْلَمْتُ فَاجْتَهَدْتُ فَلَمْ آلُ ‏ ‏فَأَهْلَلْتُ ‏ ‏بِحَجَّةٍ وَعُمْرَةٍ فَمَرَرْتُ ‏ ‏بِالْعُذَيْبِ ‏ ‏عَلَى ‏ ‏سَلْمَانَ بْنِ رَبِيعَةَ ‏ ‏وَزَيْدِ بْنِ صُوحَانَ ‏ ‏فَقَالَ أَحَدُهُمَا أَبِهِمَا جَمِيعًا فَقَالَ لَهُ صَاحِبُهُ دَعْهُ فَلَهُوَ أَضَلُّ مِنْ بَعِيرِهِ قَالَ فَكَأَنَّمَا بَعِيرِي عَلَى عُنُقِي فَأَتَيْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ لِي ‏ ‏عُمَرُ ‏ ‏إِنَّهُمَا لَمْ يَقُولَا شَيْئًا ‏ ‏هُدِيتَ لِسُنَّةِ نَبِيِّكَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[247,247,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ إِنِّي ‏ ‏نَذَرْتُ ‏ ‏فِي الْجَاهِلِيَّةِ أَنْ أَعْتَكِفَ فِي ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏لَيْلَةً فَقَالَ لَهُ ‏ ‏فَأَوْفِ ‏ ‏بِنَذْرِكَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏صُبَيِّ بْنِ مَعْبَدٍ التَّغْلِبِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ حَدِيثَ ‏ ‏عَهْدٍ ‏ ‏بِنَصْرَانِيَّةٍ فَأَرَدْتُ الْجِهَادَ أَوْ الْحَجَّ فَأَتَيْتُ رَجُلًا مِنْ قَوْمِي يُقَالُ لَهُ ‏ ‏هُدَيْمٌ ‏ ‏فَسَأَلْتُهُ فَأَمَرَنِي بِالْحَجِّ ‏ ‏فَقَرَنْتُ ‏ ‏بَيْنَ الْحَجِّ وَالْعُمْرَةِ فَذَكَرَهُ ‏","","",""],[248,248,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ الْإِيَامِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏صَلَاةُ السَّفَرِ رَكْعَتَانِ وَصَلَاةُ الْأَضْحَى رَكْعَتَانِ وَصَلَاةُ الْفِطْرِ رَكْعَتَانِ وَصَلَاةُ الْجُمُعَةِ رَكْعَتَانِ تَمَامٌ غَيْرُ قَصْرٍ عَلَى لِسَانِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَقَالَ ‏ ‏زُبَيْدٌ ‏ ‏مَرَّةً أُرَاهُ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَلَى غَيْرِ وَجْهِ الشَّكِّ ‏ ‏و قَالَ ‏ ‏يَزِيدُ يَعْنِي ابْنَ هَارُونَ ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[249,249,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ وَجَدَ فَرَسًا كَانَ حَمَلَ عَلَيْهَا فِي سَبِيلِ اللَّهِ تُبَاعُ فِي السُّوقِ فَأَرَادَ أَنْ يَشْتَرِيَهَا فَسَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَهَاهُ وَقَالَ ‏ ‏لَا تَعُودَنَّ فِي ‏ ‏صَدَقَتِكَ ‏","","",""],[250,250,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَبِيَدِهِ ‏ ‏عَسِيبُ ‏ ‏نَخْلٍ وَهُوَ يُجْلِسُ النَّاسَ يَقُولُ اسْمَعُوا لِقَوْلِ خَلِيفَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏مَوْلًى ‏ ‏لِأَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُقَالُ لَهُ ‏ ‏شَدِيدٌ ‏ ‏بِصَحِيفَةٍ فَقَرَأَهَا عَلَى النَّاسِ فَقَالَ يَقُولُ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اسْمَعُوا وَأَطِيعُوا لِمَا فِي هَذِهِ الصَّحِيفَةِ فَوَاللَّهِ مَا أَلَوْتُكُمْ ‏ ‏قَالَ ‏ ‏قَيْسٌ ‏ ‏فَرَأَيْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَعْدَ ذَلِكَ عَلَى الْمِنْبَرِ ‏","","",""],[251,251,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنْ ‏ ‏عِمْرَانَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏عَنْ ‏ ‏النَّبِيذِ ‏ ‏فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏ ‏فَلَقِيتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَسَأَلْتُهُ فَأَخْبَرَنِي فِيمَا أَظُنُّ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏ ‏شَكَّ ‏ ‏سُفْيَانُ ‏ ‏قَالَ فَلَقِيتُ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏فَسَأَلْتُهُ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏","","",""],[252,252,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سِنَانٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ آدَمَ ‏ ‏وَأَبِي مَرْيَمَ ‏ ‏وَأَبِي شُعَيْبٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كَانَ ‏ ‏بِالْجَابِيَةِ ‏ ‏فَذَكَرَ فَتْحَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏قَالَ فَقَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏فَحَدَّثَنِي ‏ ‏أَبُو سِنَانٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ آدَمَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏لِكَعْبٍ ‏ ‏أَيْنَ تُرَى أَنْ أُصَلِّيَ فَقَالَ إِنْ أَخَذْتَ عَنِّي صَلَّيْتَ خَلْفَ الصَّخْرَةِ فَكَانَتْ ‏ ‏الْقُدْسُ ‏ ‏كُلُّهَا بَيْنَ يَدَيْكَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏ضَاهَيْتَ ‏ ‏الْيَهُودِيَّةَ لَا وَلَكِنْ ‏ ‏أُصَلِّي حَيْثُ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَقَدَّمَ إِلَى الْقِبْلَةِ فَصَلَّى ثُمَّ جَاءَ فَبَسَطَ رِدَاءَهُ فَكَنَسَ الْكُنَاسَةَ فِي رِدَائِهِ وَكَنَسَ النَّاسُ ‏","","",""],[253,253,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْفُضَيْلَ بْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْكَلَالَةِ ‏ ‏فَقَالَ ‏ ‏تَكْفِيكَ ‏ ‏آيَةُ الصَّيْفِ ‏ ‏فَقَالَ لَأَنْ أَكُونَ سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهَا أَحَبُّ إِلَيَّ مِنْ أَنْ يَكُونَ لِي ‏ ‏حُمْرُ النَّعَمِ ‏","","",""],[254,254,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّهُ تُصِيبُنِي الْجَنَابَةُ ‏ ‏فَأَمَرَهُ أَنْ يَغْسِلَ ذَكَرَهُ وَيَتَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[255,255,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏يُعَذِّبُ اللَّهُ هَذَا الْمَيِّتَ بِبُكَاءِ هَذَا الْحَيِّ فَقَالَ ‏ ‏حَدَّثَنِي ‏ ‏عُمَرُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا كَذَبْتُ عَلَى ‏ ‏عُمَرَ ‏ ‏وَلَا كَذَبَ ‏ ‏عُمَرُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[256,256,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏الْقَرْثَعِ ‏ ‏عَنِ ‏ ‏قَيْسٍ ‏ ‏أَوْ ‏ ‏ابْنِ قَيْسٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏جُعْفِيٍّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَهُوَ يَقْرَأُ فَقَامَ فَسَمِعَ قِرَاءَتَهُ ثُمَّ رَكَعَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَسَجَدَ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلْ ‏ ‏تُعْطَهْ ‏ ‏سَلْ ‏ ‏تُعْطَهْ قَالَ ثُمَّ مَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏مَنْ سَرَّهُ أَنْ يَقْرَأَ الْقُرْآنَ ‏ ‏غَضًّا ‏ ‏كَمَا أُنْزِلَ فَلْيَقْرَأْهُ مِنْ ‏ ‏ابْنِ أُمِّ عَبْدٍ ‏ ‏قَالَ ‏ ‏فَأَدْلَجْتُ ‏ ‏إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏لِأُبَشِّرَهُ بِمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَلَمَّا ‏ ‏ضَرَبْتُ ‏ ‏الْبَابَ ‏ ‏أَوْ قَالَ لَمَّا سَمِعَ صَوْتِي ‏ ‏قَالَ مَا جَاءَ بِكَ هَذِهِ السَّاعَةَ قُلْتُ جِئْتُ لِأُبَشِّرَكَ بِمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَدْ سَبَقَكَ ‏ ‏أَبُو بَكْرٍ ‏ ‏قُلْتُ إِنْ يَفْعَلْ فَإِنَّهُ سَبَّاقٌ بِالْخَيْرَاتِ مَا اسْتَبَقْنَا خَيْرًا قَطُّ إِلَّا سَبَقَنَا إِلَيْهَا ‏ ‏أَبُو بَكْرٍ ‏","","",""],[257,257,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أُسَيْرِ بْنِ جَابِرٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَقْبَلَ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏جَعَلَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَسْتَقْرِي الرِّفَاقَ فَيَقُولُ هَلْ فِيكُمْ أَحَدٌ مِنْ ‏ ‏قَرَنٍ ‏ ‏حَتَّى أَتَى عَلَى ‏ ‏قَرَنٍ ‏ ‏فَقَالَ مَنْ أَنْتُمْ قَالُوا ‏ ‏قَرَنٌ ‏ ‏فَوَقَعَ زِمَامُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَوْ زِمَامُ ‏ ‏أُوَيْسٍ ‏ ‏فَنَاوَلَهُ أَحَدُهُمَا الْآخَرَ فَعَرَفَهُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏مَا اسْمُكَ قَالَ أَنَا ‏ ‏أُوَيْسٌ ‏ ‏فَقَالَ هَلْ لَكَ وَالِدَةٌ قَالَ نَعَمْ قَالَ فَهَلْ كَانَ بِكَ مِنْ الْبَيَاضِ شَيْءٌ قَالَ نَعَمْ فَدَعَوْتُ اللَّهَ عَزَّ وَجَلَّ فَأَذْهَبَهُ عَنِّي إِلَّا مَوْضِعَ الدِّرْهَمِ مِنْ سُرَّتِي لِأَذْكُرَ بِهِ رَبِّي قَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اسْتَغْفِرْ لِي قَالَ أَنْتَ أَحَقُّ أَنْ تَسْتَغْفِرَ لِي أَنْتَ صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ خَيْرَ التَّابِعِينَ رَجُلٌ يُقَالُ لَهُ ‏ ‏أُوَيْسٌ ‏ ‏وَلَهُ وَالِدَةٌ وَكَانَ بِهِ بَيَاضٌ فَدَعَا اللَّهَ عَزَّ وَجَلَّ فَأَذْهَبَهُ عَنْهُ إِلَّا مَوْضِعَ ‏ ‏الدِّرْهَمِ فِي سُرَّتِهِ فَاسْتَغْفَرَ لَهُ ثُمَّ دَخَلَ فِي غِمَارِ النَّاسِ فَلَمْ يُدْرَ أَيْنَ وَقَعَ قَالَ فَقَدِمَ ‏ ‏الْكُوفَةَ ‏ ‏قَالَ وَكُنَّا نَجْتَمِعُ فِي حَلْقَةٍ فَنَذْكُرُ اللَّهَ وَكَانَ يَجْلِسُ مَعَنَا فَكَانَ إِذَا ذَكَرَ هُوَ وَقَعَ حَدِيثُهُ مِنْ قُلُوبِنَا مَوْقِعًا لَا يَقَعُ حَدِيثُ غَيْرِهِ فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي الشَّوَارِبِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْقَرْثَعِ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏أَوْ ‏ ‏ابْنِ قَيْسٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏جُعْفِيٍّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏عَفَّانَ ‏","","",""],[258,258,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَمَّا ‏ ‏عَوَّلَتْ ‏ ‏عَلَيْهِ ‏ ‏حَفْصَةُ ‏ ‏فَقَالَ يَا ‏ ‏حَفْصَةُ ‏ ‏أَمَا سَمِعْتِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُعَوَّلُ ‏ ‏عَلَيْهِ يُعَذَّبُ قَالَ ‏ ‏وَعَوَّلَ ‏ ‏صُهَيْبٌ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا ‏ ‏صُهَيْبُ ‏ ‏أَمَا عَلِمْتَ أَنَّ ‏ ‏الْمُعَوَّلَ ‏ ‏عَلَيْهِ يُعَذَّبُ ‏","","",""],[259,259,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ الرِّشْكُ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏أُمِّ عَمْرٍو ‏ ‏ابْنَةِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهَا سَمِعَتْ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَخْطُبُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا فَلَا ‏ ‏يُكْسَاهُ فِي الْآخِرَةِ ‏","","",""],[260,260,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدَّثَنِي ‏ ‏رِجَالٌ مَرْضِيُّونَ فِيهِمْ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً شَهِدَ عِنْدِي رِجَالٌ مَرْضِيُّونَ وَأَرْضَاهُمْ عِنْدِي ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا صَلَاةَ بَعْدَ صَلَاتَيْنِ بَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏بِمِثْلِ هَذَا شَهِدَ عِنْدِي رِجَالٌ مَرْضِيُّونَ ‏","","",""],[261,261,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏الْيَهُودَ ‏ ‏قَالُوا ‏ ‏لِعُمَرَ ‏ ‏إِنَّكُمْ تَقْرَءُونَ آيَةً لَوْ أُنْزِلَتْ فِينَا لَاتَّخَذْنَا ذَلِكَ الْيَوْمَ عِيدًا فَقَالَ إِنِّي لَأَعْلَمُ حَيْثُ أُنْزِلَتْ وَأَيَّ يَوْمٍ أُنْزِلَتْ وَأَيْنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أُنْزِلَتْ ‏ ‏أُنْزِلَتْ يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاقِفٌ ‏ ‏بِعَرَفَةَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَأَشُكُّ يَوْمَ جُمُعَةٍ أَوْ لَا ‏ ‏يَعْنِي ‏ { ‏الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمْ الْإِسْلَامَ دِينًا ‏}","","",""],[262,262,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏فَقَالَ ‏ ‏بِمَ ‏ ‏أَهْلَلْتَ ‏ ‏قُلْتُ ‏ ‏بِإِهْلَالٍ ‏ ‏كَإِهْلَالِ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هَلْ سُقْتَ مِنْ ‏ ‏هَدْيٍ ‏ ‏قُلْتُ لَا قَالَ طُفْ ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ حِلَّ فَطُفْتُ ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ أَتَيْتُ امْرَأَةً مِنْ قَوْمِي فَمَشَّطَتْنِي وَغَسَلَتْ رَأْسِي فَكُنْتُ أُفْتِي النَّاسَ بِذَلِكَ بِإِمَارَةِ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَإِمَارَةِ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَإِنِّي لَقَائِمٌ فِي الْمَوْسِمِ إِذْ جَاءَنِي رَجُلٌ فَقَالَ إِنَّكَ لَا تَدْرِي مَا أَحْدَثَ ‏ ‏أَمِيرُ الْمُؤْمِنِينَ ‏ ‏فِي شَأْنِ ‏ ‏النُّسُكِ ‏ ‏فَقُلْتُ أَيُّهَا النَّاسُ مَنْ كُنَّا أَفْتَيْنَاهُ فُتْيَا فَهَذَا أَمِيرُ الْمُؤْمِنِينَ قَادِمٌ عَلَيْكُمْ فَبِهِ ‏ ‏فَأْتَمُّوا ‏ ‏فَلَمَّا قَدِمَ قُلْتُ مَا هَذَا الَّذِي قَدْ ‏ ‏أَحْدَثْتَ ‏ ‏فِي شَأْنِ ‏ ‏النُّسُكِ ‏ ‏قَالَ إِنْ نَأْخُذْ بِكِتَابِ اللَّهِ تَعَالَى فَإِنَّ اللَّهَ تَعَالَى قَالَ ‏ { ‏وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ ‏} ‏وَإِنْ نَأْخُذْ بِسُنَّةِ نَبِيِّنَا فَإِنَّهُ لَمْ ‏ ‏يَحِلَّ ‏ ‏حَتَّى ‏ ‏نَحَرَ ‏ ‏الْهَدْيَ ‏","","",""],[263,263,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ غَفَلَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُقَبِّلُ الْحَجَرَ وَيَقُولُ ‏ ‏إِنِّي لَأَعْلَمُ أَنَّكَ حَجَرٌ لَا تَضُرُّ وَلَا تَنْفَعُ وَلَكِنِّي رَأَيْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَ ‏ ‏حَفِيًّا ‏","","",""],[264,264,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ الْمُشْرِكِينَ كَانُوا لَا يُفِيضُونَ مِنْ ‏ ‏جَمْعٍ ‏ ‏حَتَّى تُشْرِقَ الشَّمْسُ عَلَى ‏ ‏ثَبِيرٍ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَكَانُوا يَقُولُونَ أَشْرِقْ ‏ ‏ثَبِيرُ ‏ ‏كَيْمَا ‏ ‏نُغِيرُ ‏ ‏يَعْنِي فَخَالَفَهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَفَعَ ‏ ‏قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ ‏","","",""],[265,265,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ اللَّهَ تَعَالَى بَعَثَ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنْزَلَ عَلَيْهِ الْكِتَابَ فَكَانَ فِيمَا أَنْزَلَ عَلَيْهِ آيَةُ الرَّجْمِ فَقَرَأْنَا بِهَا وَعَقَلْنَاهَا وَوَعَيْنَاهَا ‏ ‏فَأَخْشَى أَنْ يَطُولَ بِالنَّاسِ ‏ ‏عَهْدٌ ‏ ‏فَيَقُولُوا إِنَّا لَا نَجِدُ آيَةَ الرَّجْمِ فَتُتْرَكَ فَرِيضَةٌ أَنْزَلَهَا اللَّهُ تَعَالَى ‏ ‏وَإِنَّ الرَّجْمَ فِي كِتَابِ اللَّهِ تَعَالَى حَقٌّ عَلَى مَنْ زَنَى إِذَا أَحْصَنَ مِنْ الرِّجَالِ وَالنِّسَاءِ إِذَا قَامَتْ ‏ ‏الْبَيِّنَةُ ‏ ‏أَوْ كَانَ ‏ ‏الْحَبَلُ ‏ ‏أَوْ ‏ ‏الِاعْتِرَافُ ‏","","",""],[266,266,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏هِشَامَ بْنَ حَكِيمٍ ‏ ‏يَقْرَأُ سُورَةَ ‏ ‏الْفُرْقَانِ ‏ ‏فِي الصَّلَاةِ عَلَى غَيْرِ مَا أَقْرَؤُهَا وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْرَأَنِيهَا فَأَخَذْتُ بِثَوْبِهِ فَذَهَبْتُ بِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي سَمِعْتُهُ يَقْرَأُ سُورَةَ ‏ ‏الْفُرْقَانِ ‏ ‏عَلَى غَيْرِ مَا أَقْرَأْتَنِيهَا فَقَالَ اقْرَأْ فَقَرَأَ الْقِرَاءَةَ الَّتِي سَمِعْتُهَا مِنْهُ فَقَالَ هَكَذَا أُنْزِلَتْ ثُمَّ قَالَ لِي اقْرَأْ فَقَرَأْتُ فَقَالَ هَكَذَا أُنْزِلَتْ ‏ ‏إِنَّ هَذَا الْقُرْآنَ أُنْزِلَ عَلَى سَبْعَةِ ‏ ‏أَحْرُفٍ ‏ ‏فَاقْرَءُوا مَا تَيَسَّرَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنِ ‏ ‏الْمِسْوَرِ بْنِ مَخْرَمَةَ ‏ ‏وَعَبْدِ الرَّحْمَنِ بْنِ عَبْدٍ الْقَارِيِّ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏مَرَرْتُ ‏ ‏بِهِشَامِ بْنِ حَكِيمِ بْنِ حِزَامٍ ‏ ‏يَقْرَأُ سُورَةَ ‏ ‏الْفُرْقَانِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[267,267,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّعْدِيِّ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَلَمْ أُحَدَّثْ أَنَّكَ تَلِي مِنْ أَعْمَالِ النَّاسِ أَعْمَالًا فَإِذَا أُعْطِيتَ الْعُمَالَةَ لَمْ تَقْبَلْهَا قَالَ نَعَمْ قَالَ فَمَا تُرِيدُ إِلَى ذَاكَ قَالَ أَنَا غَنِيٌّ لِي أَعْبُدٌ وَلِي أَفْرَاسٌ أُرِيدُ أَنْ يَكُونَ عَمَلِي ‏ ‏صَدَقَةً ‏ ‏عَلَى الْمُسْلِمِينَ قَالَ لَا تَفْعَلْ فَإِنِّي كُنْتُ أَفْعَلُ مِثْلَ الَّذِي تَفْعَلُ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْطِينِي الْعَطَاءَ فَأَقُولُ أَعْطِهِ مَنْ هُوَ أَفْقَرُ إِلَيْهِ مِنِّي فَقَالَ خُذْهُ فَإِمَّا أَنْ تَمَوَّلَهُ وَإِمَّا أَنْ تَصَدَّقَ بِهِ وَمَا آتَاكَ اللَّهُ مِنْ هَذَا الْمَالِ وَأَنْتَ غَيْرُ ‏ ‏مُشْرِفٍ ‏ ‏لَهُ وَلَا سَائِلِهِ فَخُذْهُ وَمَا لَا فَلَا تُتْبِعْهُ نَفْسَكَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏لَقِيَ ‏ ‏عُمَرُ ‏ ‏عَبْدَ اللَّهِ بْنَ السَّعْدِيِّ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ تَصَدَّقْ بِهِ وَقَالَ لَا تُتْبِعْهُ نَفْسَكَ ‏","","",""],[268,268,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏حَمَلْتُ ‏ ‏عَلَى فَرَسٍ فِي سَبِيلِ اللَّهِ فَأَضَاعَهُ صَاحِبُهُ فَأَرَدْتُ أَنْ أَبْتَاعَهُ وَظَنَنْتُ أَنَّهُ بَائِعُهُ بِرُخْصٍ فَقُلْتُ حَتَّى أَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَا تَبْتَعْهُ وَإِنْ أَعْطَاكَهُ بِدِرْهَمٍ ‏ ‏فَإِنَّ الَّذِي ‏ ‏يَعُودُ ‏ ‏فِي ‏ ‏صَدَقَتِهِ ‏ ‏فَكَالْكَلْبِ يَعُودُ فِي ‏ ‏قَيْئِهِ ‏","","",""],[269,269,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ أَزْهَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏شَهِدْتُ الْعِيدَ مَعَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَجَاءَ فَصَلَّى ثُمَّ انْصَرَفَ فَخَطَبَ النَّاسَ فَقَالَ إِنَّ هَذَيْنِ يَوْمَانِ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صِيَامِهِمَا يَوْمُ فِطْرِكُمْ مِنْ صِيَامِكُمْ وَالْآخَرُ يَوْمٌ تَأْكُلُونَ فِيهِ مِنْ ‏ ‏نُسُكِكُمْ ‏","","",""],[270,270,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُمَرُ ‏ ‏رَجُلًا غَيُورًا فَكَانَ إِذَا خَرَجَ إِلَى الصَّلَاةِ اتَّبَعَتْهُ ‏ ‏عَاتِكَةُ ابْنَةُ زَيْدٍ ‏ ‏فَكَانَ يَكْرَهُ خُرُوجَهَا وَيَكْرَهُ مَنْعَهَا وَكَانَ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَأْذَنَتْكُمْ نِسَاؤُكُمْ إِلَى الصَّلَاةِ فَلَا تَمْنَعُوهُنَّ ‏","","",""],[271,271,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏لَوْلَا آخِرُ الْمُسْلِمِينَ مَا فُتِحَتْ قَرْيَةٌ إِلَّا قَسَمْتُهَا كَمَا ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏","","",""],[272,272,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏نُبِّئْتُ ‏ ‏عَنْ ‏ ‏أَبِي الْعَجْفَاءِ السُّلَمِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏يَقُولُ ‏ ‏أَلَا لَا ‏ ‏تُغْلُوا ‏ ‏صُدُقَ ‏ ‏النِّسَاءِ ‏ ‏أَلَا لَا ‏ ‏تُغْلُوا ‏ ‏صُدُقَ ‏ ‏النِّسَاءِ فَإِنَّهَا لَوْ كَانَتْ ‏ ‏مَكْرُمَةً ‏ ‏فِي الدُّنْيَا أَوْ تَقْوَى عِنْدَ اللَّهِ كَانَ أَوْلَاكُمْ بِهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَصْدَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْرَأَةً مِنْ نِسَائِهِ وَلَا أُصْدِقَتْ امْرَأَةٌ مِنْ بَنَاتِهِ أَكْثَرَ مِنْ ثِنْتَيْ عَشْرَةَ ‏ ‏أُوقِيَّةً ‏ ‏وَإِنَّ الرَّجُلَ ‏ ‏لَيُبْتَلَى ‏ ‏بِصَدُقَةِ ‏ ‏امْرَأَتِهِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً وَإِنَّ الرَّجُلَ ‏ ‏لَيُغْلِي ‏ ‏بِصَدُقَةِ ‏ ‏امْرَأَتِهِ ‏ ‏حَتَّى تَكُونَ لَهَا عَدَاوَةٌ فِي نَفْسِهِ وَحَتَّى يَقُولَ كَلِفْتُ إِلَيْكِ ‏ ‏عَلَقَ ‏ ‏الْقِرْبَةِ ‏ ‏قَالَ وَكُنْتُ غُلَامًا عَرَبِيًّا مُوَلَّدًا لَمْ أَدْرِ مَا ‏ ‏عَلَقُ ‏ ‏الْقِرْبَةِ ‏ ‏قَالَ وَأُخْرَى تَقُولُونَهَا لِمَنْ قُتِلَ فِي مَغَازِيكُمْ وَمَاتَ قُتِلَ فُلَانٌ شَهِيدًا وَمَاتَ فُلَانٌ شَهِيدًا وَلَعَلَّهُ أَنْ يَكُونَ قَدْ ‏ ‏أَوْقَرَ ‏ ‏عَجُزَ ‏ ‏دَابَّتِهِ أَوْ ‏ ‏دَفَّ ‏ ‏رَاحِلَتِهِ ‏ ‏ذَهَبًا أَوْ ‏ ‏وَرِقًا ‏ ‏يَلْتَمِسُ ‏ ‏التِّجَارَةَ لَا تَقُولُوا ‏ ‏ذَاكُمْ وَلَكِنْ قُولُوا كَمَا قَالَ النَّبِيُّ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قُتِلَ ‏ ‏أَوْ مَاتَ ‏ ‏فِي سَبِيلِ اللَّهِ فَهُوَ فِي الْجَنَّةِ ‏","","",""],[273,273,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏الْجُرَيْرِيُّ سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي فِرَاسٍ ‏ ‏قَالَ ‏ ‏خَطَبَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ أَلَا إِنَّا إِنَّمَا كُنَّا نَعْرِفُكُمْ إِذْ بَيْنَ ظَهْرَيْنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِذْ يَنْزِلُ الْوَحْيُ وَإِذْ يُنْبِئُنَا اللَّهُ مِنْ أَخْبَارِكُمْ أَلَا وَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ انْطَلَقَ وَقَدْ انْقَطَعَ الْوَحْيُ وَإِنَّمَا نَعْرِفُكُمْ بِمَا نَقُولُ لَكُمْ مَنْ أَظْهَرَ مِنْكُمْ خَيْرًا ظَنَنَّا بِهِ خَيْرًا وَأَحْبَبْنَاهُ عَلَيْهِ وَمَنْ أَظْهَرَ مِنْكُمْ لَنَا شَرًّا ظَنَنَّا بِهِ شَرًّا وَأَبْغَضْنَاهُ عَلَيْهِ سَرَائِرُكُمْ بَيْنَكُمْ وَبَيْنَ رَبِّكُمْ أَلَا إِنَّهُ قَدْ أَتَى عَلَيَّ حِينٌ وَأَنَا أَحْسِبُ أَنَّ مَنْ قَرَأَ الْقُرْآنَ يُرِيدُ اللَّهَ وَمَا عِنْدَهُ فَقَدْ خُيِّلَ إِلَيَّ بِآخِرَةٍ أَلَا إِنَّ رِجَالًا قَدْ قَرَءُوهُ يُرِيدُونَ بِهِ مَا عِنْدَ النَّاسِ فَأَرِيدُوا اللَّهَ بِقِرَاءَتِكُمْ وَأَرِيدُوهُ بِأَعْمَالِكُمْ أَلَا إِنِّي وَاللَّهِ مَا أُرْسِلُ عُمَّالِي إِلَيْكُمْ لِيَضْرِبُوا أَبْشَارَكُمْ وَلَا لِيَأْخُذُوا أَمْوَالَكُمْ وَلَكِنْ أُرْسِلُهُمْ إِلَيْكُمْ لِيُعَلِّمُوكُمْ دِينَكُمْ وَسُنَّتَكُمْ فَمَنْ فُعِلَ بِهِ شَيْءٌ سِوَى ذَلِكَ فَلْيَرْفَعْهُ إِلَيَّ فَوَالَّذِي نَفْسِي بِيَدِهِ إِذَنْ لَأُقِصَّنَّهُ مِنْهُ ‏ ‏فَوَثَبَ ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ أَوَرَأَيْتَ إِنْ كَانَ رَجُلٌ مِنْ الْمُسْلِمِينَ عَلَى رَعِيَّةٍ فَأَدَّبَ بَعْضَ رَعِيَّتِهِ أَئِنَّكَ لَمُقْتَصُّهُ مِنْهُ قَالَ إِي وَالَّذِي نَفْسُ ‏ ‏عُمَرَ ‏ ‏بِيَدِهِ إِذَنْ لَأُقِصَّنَّهُ مِنْهُ وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقِصُّ مِنْ نَفْسِهِ أَلَا لَا تَضْرِبُوا الْمُسْلِمِينَ فَتُذِلُّوهُمْ وَلَا تُجَمِّرُوهُمْ فَتَفْتِنُوهُمْ وَلَا تَمْنَعُوهُمْ حُقُوقَهُمْ فَتُكَفِّرُوهُمْ وَلَا تُنْزِلُوهُمْ الْغِيَاضَ فَتُضَيِّعُوهُمْ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏مَرَّةً أُخْرَى ‏ ‏أَخْبَرَنَا ‏ ‏سَلَمَةُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏نُبِّئْتُ ‏ ‏عَنْ ‏ ‏أَبِي الْعَجْفَاءِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏يَقُولُ ‏ ‏أَلَا لَا ‏ ‏تُغْلُوا ‏ ‏صُدُقَ ‏ ‏النِّسَاءِ فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏وَذَكَرَ ‏ ‏أَيُّوبُ ‏ ‏وَهِشَامٌ ‏ ‏وَابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَجْفَاءِ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏نَحْوًا مِنْ حَدِيثِ ‏ ‏سَلَمَةَ ‏ ‏إِلَّا أَنَّهُمْ قَالُوا لَمْ يَقُلْ ‏ ‏مُحَمَّدٌ ‏ ‏نُبِّئْتُ عَنْ ‏ ‏أَبِي الْعَجْفَاءِ ‏","","",""],[274,274,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَنَحْنُ نَنْتَظِرُ جَنَازَةَ ‏ ‏أُمِّ أَبَانَ ابْنَةِ عُثْمَانَ بْنِ عَفَّانَ ‏ ‏وَعِنْدَهُ ‏ ‏عَمْرُو بْنُ عُثْمَانَ ‏ ‏فَجَاءَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَقُودُهُ قَائِدُهُ قَالَ فَأُرَاهُ أَخْبَرَهُ بِمَكَانِ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَجَاءَ حَتَّى جَلَسَ إِلَى جَنْبِي وَكُنْتُ بَيْنَهُمَا فَإِذَا صَوْتٌ مِنْ الدَّارِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْمَيِّتَ يُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ ‏ ‏فَأَرْسَلَهَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏مُرْسَلَةً ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏كُنَّا مَعَ أَمِيرِ الْمُؤْمِنِينَ ‏ ‏عُمَرَ ‏ ‏حَتَّى إِذَا كُنَّا ‏ ‏بِالْبَيْدَاءِ ‏ ‏إِذَا هُوَ بِرَجُلٍ نَازِلٍ فِي ظِلِّ شَجَرَةٍ فَقَالَ لِي انْطَلِقْ فَاعْلَمْ مَنْ ذَاكَ فَانْطَلَقْتُ فَإِذَا هُوَ ‏ ‏صُهَيْبٌ ‏ ‏فَرَجَعْتُ إِلَيْهِ فَقُلْتُ إِنَّكَ أَمَرْتَنِي أَنْ أَعْلَمَ لَكَ مَنْ ذَاكَ وَإِنَّهُ ‏ ‏صُهَيْبٌ ‏ ‏فَقَالَ مُرُوهُ فَلْيَلْحَقْ بِنَا فَقُلْتُ إِنَّ مَعَهُ أَهْلَهُ قَالَ وَإِنْ كَانَ مَعَهُ أَهْلُهُ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏أَيُّوبُ ‏ ‏مَرَّةً فَلْيَلْحَقْ بِنَا ‏ ‏فَلَمَّا بَلَغْنَا ‏ ‏الْمَدِينَةَ ‏ ‏لَمْ يَلْبَثْ أَمِيرُ الْمُؤْمِنِينَ أَنْ أُصِيبَ فَجَاءَ ‏ ‏صُهَيْبٌ ‏ ‏فَقَالَ وَا أَخَاهُ وَا صَاحِبَاهُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَلَمْ تَعْلَمْ أَوَلَمْ تَسْمَعْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبَعْضِ بُكَاءِ أَهْلِهِ عَلَيْهِ ‏ ‏فَأَمَّا ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَأَرْسَلَهَا مُرْسَلَةً وَأَمَّا ‏ ‏عُمَرُ ‏ ‏فَقَالَ بِبَعْضِ بُكَاءِ ‏ ‏فَأَتَيْتُ ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرْتُ لَهَا قَوْلَ ‏ ‏عُمَرَ ‏ ‏فَقَالَتْ لَا وَاللَّهِ مَا قَالَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ الْمَيِّتَ يُعَذَّبُ بِبُكَاءِ ‏ ‏أَحَدٍ وَلَكِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْكَافِرَ لَيَزِيدُهُ اللَّهُ عَزَّ وَجَلَّ بِبُكَاءِ أَهْلِهِ عَذَابًا ‏ ‏وَإِنَّ اللَّهَ لَهُوَ أَضْحَكَ وَأَبْكَى ‏ { ‏وَلَا ‏ ‏تَزِرُ ‏ ‏وَازِرَةٌ ‏ ‏وِزْرَ ‏ ‏أُخْرَى ‏} ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏وَقَالَ ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏حَدَّثَنِي ‏ ‏الْقَاسِمُ ‏ ‏قَالَ لَمَّا بَلَغَ ‏ ‏عَائِشَةَ ‏ ‏قَوْلُ ‏ ‏عُمَرَ ‏ ‏وَابْنِ عُمَرَ ‏ ‏قَالَتْ ‏ ‏إِنَّكُمْ لَتُحَدِّثُونِي عَنْ غَيْرِ كَاذِبَيْنِ وَلَا مُكَذَّبَيْنِ وَلَكِنَّ السَّمْعَ يُخْطِئُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏أَيُّوبَ ‏ ‏إِلَّا أَنَّهُ قَالَ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لِعَمْرِو بْنِ عُثْمَانَ ‏ ‏وَهُوَ مُوَاجِهُهُ أَلَا ‏ ‏تَنْهَى عَنْ الْبُكَاءِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏تُوُفِّيَتْ ابْنَةٌ ‏ ‏لِعُثْمَانَ بْنِ عَفَّانَ ‏ ‏بِمَكَّةَ ‏ ‏فَحَضَرَهَا ‏ ‏ابْنُ عُمَرَ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏وَإِنِّي لَجَالِسٌ بَيْنَهُمَا ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لِعَمْرِو بْنِ عُثْمَانَ ‏ ‏وَهُوَ مُوَاجِهُهُ أَلَا ‏ ‏تَنْهَى عَنْ الْبُكَاءِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏","","",""],[275,275,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كُنْتُ فِي ‏ ‏رَكْبٍ ‏ ‏أَسِيرُ فِي غَزَاةٍ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَلَفْتُ فَقُلْتُ لَا وَأَبِي فَهَتَفَ بِي رَجُلٌ مِنْ خَلْفِي ‏ ‏لَا تَحْلِفُوا بِآبَائِكُمْ فَالْتَفَتُّ فَإِذَا هُوَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[276,276,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُيَسَّرٍ أَبُو سَعْدٍ الصَّاغَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُمَرُ ‏ ‏يَحْلِفُ عَلَى أَيْمَانٍ ثَلَاثٍ يَقُولُ ‏ ‏وَاللَّهِ مَا أَحَدٌ أَحَقَّ بِهَذَا الْمَالِ مِنْ أَحَدٍ وَمَا أَنَا بِأَحَقَّ بِهِ مِنْ أَحَدٍ وَاللَّهِ مَا مِنْ الْمُسْلِمِينَ أَحَدٌ إِلَّا وَلَهُ فِي هَذَا الْمَالِ نَصِيبٌ إِلَّا عَبْدًا مَمْلُوكًا وَلَكِنَّا عَلَى مَنَازِلِنَا مِنْ كِتَابِ اللَّهِ تَعَالَى وَقَسْمِنَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَالرَّجُلُ وَبَلَاؤُهُ فِي الْإِسْلَامِ وَالرَّجُلُ وَقَدَمُهُ فِي الْإِسْلَامِ وَالرَّجُلُ وَغَنَاؤُهُ فِي الْإِسْلَامِ وَالرَّجُلُ وَحَاجَتُهُ وَ وَاللَّهِ لَئِنْ بَقِيتُ لَهُمْ لَيَأْتِيَنَّ الرَّاعِيَ بِجَبَلِ ‏ ‏صَنْعَاءَ ‏ ‏حَظُّهُ مِنْ هَذَا الْمَالِ وَهُوَ ‏ ‏يَرْعَى مَكَانَهُ ‏","","",""],[277,277,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْقُدُّوسِ بْنُ الْحَجَّاجِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْمُخَارِقِ زُهَيْرُ بْنُ سَالِمٍ ‏ ‏أَنَّ ‏ ‏عُمَيْرَ بْنَ سَعْدٍ الْأَنْصَارِيَّ ‏ ‏كَانَ وَلَّاهُ ‏ ‏عُمَرُ ‏ ‏حِمْصَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏يَعْنِي ‏ ‏لِكَعْبٍ ‏ ‏إِنِّي أَسْأَلُكَ عَنْ أَمْرٍ فَلَا تَكْتُمْنِي قَالَ وَاللَّهِ لَا أَكْتُمُكَ شَيْئًا أَعْلَمُهُ قَالَ ‏ ‏مَا أَخْوَفُ شَيْءٍ ‏ ‏تَخَوَّفُهُ عَلَى أُمَّةِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَئِمَّةً مُضِلِّينَ قَالَ ‏ ‏عُمَرُ ‏ ‏صَدَقْتَ قَدْ أَسَرَّ ذَلِكَ إِلَيَّ وَأَعْلَمَنِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[278,278,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏فَقَالَ ‏ ‏سَالِمٌ ‏ ‏فَسَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ قَالَ ‏ ‏عُمَرُ ‏ ‏أَرْسِلُوا إِلَيَّ طَبِيبًا يَنْظُرُ إِلَى جُرْحِي هَذَا قَالَ فَأَرْسَلُوا إِلَى طَبِيبٍ مِنْ ‏ ‏الْعَرَبِ ‏ ‏فَسَقَى ‏ ‏عُمَرَ ‏ ‏نَبِيذًا فَشُبِّهَ النَّبِيذُ بِالدَّمِ حِينَ خَرَجَ مِنْ الطَّعْنَةِ الَّتِي تَحْتَ السُّرَّةِ قَالَ فَدَعَوْتُ طَبِيبًا آخَرَ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِنْ ‏ ‏بَنِي مُعَاوِيَةَ ‏ ‏فَسَقَاهُ لَبَنًا فَخَرَجَ اللَّبَنُ مِنْ الطَّعْنَةِ ‏ ‏صَلْدًا ‏ ‏أَبْيَضَ فَقَالَ لَهُ الطَّبِيبُ يَا أَمِيرَ الْمُؤْمِنِينَ ‏ ‏اعْهَدْ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏صَدَقَنِي أَخُو ‏ ‏بَنِي مُعَاوِيَةَ ‏ ‏وَلَوْ قُلْتَ غَيْرَ ذَلِكَ كَذَّبْتُكَ قَالَ فَبَكَى عَلَيْهِ الْقَوْمُ حِينَ سَمِعُوا ذَلِكَ فَقَالَ لَا تَبْكُوا عَلَيْنَا مَنْ كَانَ بَاكِيًا فَلْيَخْرُجْ أَلَمْ تَسْمَعُوا مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُعَذَّبُ الْمَيِّتُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ ‏ ‏فَمِنْ أَجْلِ ذَلِكَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَا يُقِرُّ أَنْ ‏ ‏يُبْكَى عِنْدَهُ عَلَى هَالِكٍ مِنْ وَلَدِهِ وَلَا غَيْرِهِمْ ‏","","",""],[279,279,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏كَانَ ‏ ‏أَهْلُ الْجَاهِلِيَّةِ لَا يُفِيضُونَ مِنْ ‏ ‏جَمْعٍ ‏ ‏حَتَّى يَرَوْا الشَّمْسَ عَلَى ‏ ‏ثَبِيرٍ ‏ ‏وَكَانُوا يَقُولُونَ أَشْرِقْ ‏ ‏ثَبِيرُ ‏ ‏كَيْمَا نُغِيرُ ‏ ‏فَأَفَاضَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ طُلُوعِ الشَّمْسِ ‏","","",""],[280,280,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنِ ‏ ‏الْمِسْوَرِ بْنِ مَخْرَمَةَ ‏ ‏وَعَبْدِ الرَّحْمَنِ بْنِ عَبْدٍ الْقَارِيِّ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏مَرَرْتُ ‏ ‏بِهِشَامِ بْنِ حَكِيمِ بْنِ حِزَامٍ ‏ ‏يَقْرَأُ سُورَةَ ‏ ‏الْفُرْقَانِ ‏ ‏فِي حَيَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَمَعْتُ قِرَاءَتَهُ فَإِذَا هُوَ يَقْرَأُ عَلَى حُرُوفٍ كَثِيرَةٍ لَمْ يُقْرِئْنِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكِدْتُ أَنْ أُسَاوِرَهُ فِي الصَّلَاةِ فَنَظَرْتُ حَتَّى سَلَّمَ فَلَمَّا سَلَّمَ ‏ ‏لَبَّبْتُهُ ‏ ‏بِرِدَائِهِ فَقُلْتُ مَنْ أَقْرَأَكَ هَذِهِ السُّورَةَ الَّتِي تَقْرَؤُهَا قَالَ أَقْرَأَنِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْتُ لَهُ كَذَبْتَ فَوَاللَّهِ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَهُوَ أَقْرَأَنِي هَذِهِ السُّورَةَ الَّتِي تَقْرَؤُهَا قَالَ فَانْطَلَقْتُ أَقُودُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي سَمِعْتُ هَذَا يَقْرَأُ سُورَةَ ‏ ‏الْفُرْقَانِ ‏ ‏عَلَى حُرُوفٍ لَمْ تُقْرِئْنِيهَا وَأَنْتَ أَقْرَأْتَنِي سُورَةَ ‏ ‏الْفُرْقَانِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْسِلْهُ يَا ‏ ‏عُمَرُ ‏ ‏اقْرَأْ يَا ‏ ‏هِشَامُ ‏ ‏فَقَرَأَ عَلَيْهِ الْقِرَاءَةَ الَّتِي سَمِعْتُهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَكَذَا أُنْزِلَتْ ثُمَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَأْ يَا ‏ ‏عُمَرُ ‏ ‏فَقَرَأْتُ الْقِرَاءَةَ الَّتِي أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هَكَذَا أُنْزِلَتْ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْقُرْآنَ أُنْزِلَ عَلَى سَبْعَةِ أَحْرُفٍ فَاقْرَءُوا مِنْهُ مَا تَيَسَّرَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏أَنْبَأَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏الْمِسْوَرِ بْنِ مَخْرَمَةَ ‏ ‏وَعَبْدِ الرَّحْمَنِ بْنِ عَبْدٍ الْقَارِيِّ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏هِشَامَ بْنَ حَكِيمِ بْنِ حِزَامٍ ‏ ‏يَقْرَأُ سُورَةَ ‏ ‏الْفُرْقَانِ ‏ ‏فِي حَيَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَمَعْتُ لِقِرَاءَتِهِ فَإِذَا هُوَ يَقْرَأُ عَلَى حُرُوفٍ كَثِيرَةٍ لَمْ يُقْرِئْنِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكِدْتُ ‏ ‏أُسَاوِرُهُ ‏ ‏فِي الصَّلَاةِ فَنَظَرْتُ حَتَّى سَلَّمَ فَلَمَّا سَلَّمَ فَذَكَرَ مَعْنَاهُ ‏","","",""],[281,281,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ مِنْكُمْ مُلْتَمِسًا لَيْلَةَ الْقَدْرِ فَلْيَلْتَمِسْهَا فِي الْعَشْرِ الْأَوَاخِرِ ‏ ‏وِتْرًا ‏","","",""],[282,282,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قِيلَ لَهُ ‏ ‏أَلَا تَسْتَخْلِفُ فَقَالَ إِنْ أَتْرُكْ فَقَدْ تَرَكَ مَنْ هُوَ خَيْرٌ مِنِّي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنْ أَسْتَخْلِفْ فَقَدْ اسْتَخْلَفَ مَنْ هُوَ خَيْرٌ مِنِّي ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[283,283,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ إِبْرَاهِيمَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏عَلْقَمَةَ بْنَ وَقَّاصٍ اللَّيْثِيَّ ‏ ‏يَقُولُ إِنَّهُ سَمِعَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ يَخْطُبُ النَّاسَ وَهُوَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّمَا الْعَمَلُ بِالنِّيَّةِ وَإِنَّمَا لِامْرِئٍ مَا نَوَى فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَإِلَى رَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَإِلَى رَسُولِهِ وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا ‏ ‏يُصِيبُهَا ‏ ‏أَوْ امْرَأَةٍ يَتَزَوَّجُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ ‏","","",""],[284,284,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قَالَ ‏ ‏اتَّزِرُوا ‏ ‏وَارْتَدُوا وَانْتَعِلُوا وَأَلْقُوا ‏ ‏الْخِفَافَ ‏ ‏وَالسَّرَاوِيلَاتِ وَأَلْقُوا ‏ ‏الرُّكُبَ ‏ ‏وَانْزُوا نَزْوًا وَعَلَيْكُمْ ‏ ‏بِالْمَعَدِّيَّةِ وَارْمُوا الْأَغْرَاضَ ‏ ‏وَذَرُوا ‏ ‏التَّنَعُّمَ وَزِيَّ ‏ ‏الْعَجَمِ ‏ ‏وَإِيَّاكُمْ وَالْحَرِيرَ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏نَهَى عَنْهُ وَقَالَ لَا تَلْبَسُوا مِنْ الْحَرِيرِ إِلَّا مَا كَانَ هَكَذَا وَأَشَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِإِصْبَعَيْهِ ‏","","",""],[285,285,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ أَنْ تَهْلِكُوا عَنْ آيَةِ الرَّجْمِ وَأَنْ يَقُولَ قَائِلٌ لَا نَجِدُ حَدَّيْنِ فِي كِتَابِ اللَّهِ تَعَالَى فَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجَمَ ‏ ‏وَرَجَمْنَا ‏ ‏بَعْدَهُ ‏","","",""],[286,286,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏الْعَوَّامُ ‏ ‏حَدَّثَنِي ‏ ‏شَيْخٌ ‏ ‏كَانَ مُرَابِطًا بِالسَّاحِلِ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏أَبَا صَالِحٍ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيْسَ مِنْ لَيْلَةٍ إِلَّا وَالْبَحْرُ ‏ ‏يُشْرِفُ ‏ ‏فِيهَا ثَلَاثَ مَرَّاتٍ عَلَى الْأَرْضِ يَسْتَأْذِنُ اللَّهَ فِي أَنْ يَنْفَضِخَ عَلَيْهِمْ فَيَكُفُّهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[287,287,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏حَدِّثْنِي عَنْ طَلَاقِكَ امْرَأَتَكَ قَالَ طَلَّقْتُهَا وَهِيَ حَائِضٌ قَالَ فَذَكَرْتُ ذَلِكَ ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَذَكَرَهُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرْهُ فَلْيُرَاجِعْهَا فَإِذَا طَهُرَتْ فَلْيُطَلِّقْهَا فِي طُهْرِهَا ‏ ‏قَالَ ‏ ‏قُلْتُ لَهُ هَلْ ‏ ‏اعْتَدَدْتَ ‏ ‏بِالَّتِي طَلَّقْتَهَا وَهِيَ حَائِضٌ قَالَ ‏ ‏فَمَا لِي لَا أَعْتَدُّ بِهَا وَإِنْ كُنْتُ قَدْ عَجَزْتُ وَاسْتَحْمَقْتُ ‏","","",""],[288,288,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏أَصْبَغُ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ الشَّامِيِّ ‏ ‏قَالَ ‏ ‏لَبِسَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏ثَوْبًا جَدِيدًا فَلَمَّا بَلَغَ ‏ ‏تَرْقُوَتَهُ ‏ ‏قَالَ الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي مَا ‏ ‏أُوَارِي بِهِ عَوْرَتِي وَأَتَجَمَّلُ بِهِ فِي حَيَاتِي ‏ ‏ثُمَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اسْتَجَدَّ ثَوْبًا فَلَبِسَهُ فَقَالَ حِينَ يَبْلُغُ ‏ ‏تَرْقُوَتَهُ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي مَا ‏ ‏أُوَارِي بِهِ عَوْرَتِي وَأَتَجَمَّلُ بِهِ فِي حَيَاتِي ثُمَّ عَمَدَ إِلَى الثَّوْبِ الَّذِي أَخْلَقَ ‏ ‏أَوْ قَالَ أَلْقَى ‏ ‏فَتَصَدَّقَ بِهِ كَانَ فِي ذِمَّةِ اللَّهِ تَعَالَى وَفِي جِوَارِ اللَّهِ وَفِي ‏ ‏كَنَفِ ‏ ‏اللَّهِ حَيًّا وَمَيِّتًا حَيًّا وَمَيِّتًا حَيًّا وَمَيِّتًا ‏","","",""],[289,289,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَحَدُنَا إِذَا أَرَادَ أَنْ يَنَامَ وَهُوَ جُنُبٌ كَيْفَ يَصْنَعُ قَبْلَ أَنْ يَغْتَسِلَ قَالَ يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يَنَامُ ‏","","",""],[290,290,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏وَرْقَاءُ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى الثَّعْلَبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏وَعُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي ‏ ‏الْبَقِيعِ ‏ ‏يَنْظُرُ إِلَى الْهِلَالِ فَأَقْبَلَ رَاكِبٌ فَتَلَقَّاهُ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ مِنْ أَيْنَ جِئْتَ فَقَالَ مِنْ ‏ ‏الْعَرَبِ ‏ ‏قَالَ أَهْلَلْتَ قَالَ نَعَمْ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اللَّهُ أَكْبَرُ إِنَّمَا يَكْفِي الْمُسْلِمِينَ الرَّجُلُ ثُمَّ قَامَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَتَوَضَّأَ فَمَسَحَ عَلَى خُفَّيْهِ ثُمَّ صَلَّى الْمَغْرِبَ ثُمَّ قَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَنَعَ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏ضَيِّقَةُ الْكُمَّيْنِ فَأَخْرَجَ يَدَهُ مِنْ تَحْتِهَا وَمَسَحَ ‏","","",""],[291,291,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏أَنْبَأَنَا ‏ ‏الزُّبَيْرُ بْنُ الْخِرِّيتِ ‏ ‏عَنْ ‏ ‏أَبِي لَبِيدٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَجُلٌ مِنْ ‏ ‏طَاحِيَةَ ‏ ‏مُهَاجِرًا يُقَالُ لَهُ ‏ ‏بَيْرَحُ بْنُ أَسَدٍ ‏ ‏فَقَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏بَعْدَ وَفَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَيَّامٍ فَرَآهُ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَعَلِمَ أَنَّهُ غَرِيبٌ فَقَالَ لَهُ مَنْ أَنْتَ قَالَ مِنْ أَهْلِ ‏ ‏عُمَانَ ‏ ‏قَالَ نَعَمْ قَالَ فَأَخَذَ بِيَدِهِ فَأَدْخَلَهُ عَلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ هَذَا مِنْ أَهْلِ الْأَرْضِ الَّتِي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنِّي لَأَعْلَمُ أَرْضًا يُقَالُ لَهَا ‏ ‏عُمَانُ ‏ ‏يَنْضَحُ ‏ ‏بِنَاحِيَتِهَا الْبَحْرُ بِهَا حَيٌّ مِنْ ‏ ‏الْعَرَبِ ‏ ‏لَوْ أَتَاهُمْ رَسُولِي مَا رَمَوْهُ بِسَهْمٍ وَلَا حَجَرٍ ‏","","",""],[292,292,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏عَاصِمُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا رَفَعَهُ قَالَ يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ ‏مَنْ تَوَاضَعَ لِي هَكَذَا وَجَعَلَ يَزِيدُ بَاطِنَ كَفِّهِ إِلَى الْأَرْضِ وَأَدْنَاهَا إِلَى الْأَرْضِ رَفَعْتُهُ هَكَذَا وَجَعَلَ بَاطِنَ كَفِّهِ إِلَى السَّمَاءِ وَرَفَعَهَا نَحْوَ السَّمَاءِ ‏","","",""],[293,293,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏دَيْلَمُ بْنُ غَزْوَانَ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَيْمُونٌ الْكُرْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏قَالَ ‏ ‏إِنِّي لَجَالِسٌ تَحْتَ مِنْبَرِ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ يَخْطُبُ النَّاسَ فَقَالَ فِي خُطْبَتِهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَخْوَفَ مَا أَخَافُ عَلَى هَذِهِ الْأُمَّةِ كُلُّ مُنَافِقٍ عَلِيمِ اللِّسَانِ ‏","","",""],[294,294,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏ح ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏و حَدَّثَنَا ‏ ‏مُصْعَبٌ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي أُنَيْسَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ الْحَمِيدِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏مُسْلِمِ بْنِ يَسَارٍ الْجُهَنِيِّ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سُئِلَ عَنْ هَذِهِ الْآيَةِ ‏ { ‏وَإِذْ أَخَذَ رَبُّكَ مِنْ بَنِي ‏ ‏آدَمَ ‏ ‏مِنْ ظُهُورِهِمْ ‏ ‏ذُرِّيَّاتِهِمْ ‏ } ‏الْآيَةَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ خَلَقَ ‏ ‏آدَمَ ‏ ‏ثُمَّ مَسَحَ ظَهْرَهُ بِيَمِينِهِ وَاسْتَخْرَجَ مِنْهُ ذُرِّيَّةً فَقَالَ خَلَقْتُ هَؤُلَاءِ ‏ ‏لِلْجَنَّةِ وَبِعَمَلِ أَهْلِ الْجَنَّةِ يَعْمَلُونَ ثُمَّ مَسَحَ ظَهْرَهُ فَاسْتَخْرَجَ مِنْهُ ذُرِّيَّةً فَقَالَ خَلَقْتُ هَؤُلَاءِ لِلنَّارِ وَبِعَمَلِ أَهْلِ النَّارِ يَعْمَلُونَ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ فَفِيمَ الْعَمَلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا خَلَقَ الْعَبْدَ لِلْجَنَّةِ اسْتَعْمَلَهُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى يَمُوتَ عَلَى عَمَلٍ مِنْ أَعْمَالِ أَهْلِ الْجَنَّةِ فَيُدْخِلَهُ بِهِ الْجَنَّةَ وَإِذَا خَلَقَ الْعَبْدَ لِلنَّارِ اسْتَعْمَلَهُ بِعَمَلِ أَهْلِ النَّارِ حَتَّى يَمُوتَ عَلَى عَمَلٍ مِنْ أَعْمَالِ أَهْلِ النَّارِ فَيُدْخِلَهُ بِهِ النَّارَ ‏","","",""],[295,295,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ الْمَسْجِدَ يَوْمَ الْجُمُعَةِ ‏ ‏وَعُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَائِمٌ يَخْطُبُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَيَّةُ سَاعَةٍ هَذِهِ فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ ‏ ‏انْقَلَبْتُ ‏ ‏مِنْ السُّوقِ فَسَمِعْتُ النِّدَاءَ فَمَا زِدْتُ عَلَى أَنْ تَوَضَّأْتُ فَأَقْبَلْتُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏الْوُضُوءُ أَيْضًا وَقَدْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْمُرُنَا بِالْغُسْلِ ‏","","",""],[296,296,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏سُلَيْمَانُ بْنُ عَتِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَيْهِ ‏ ‏عَنْ ‏ ‏بَعْضِ ‏ ‏بَنِي يَعْلَى ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏طُفْتُ مَعَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَاسْتَلَمَ الرُّكْنَ قَالَ ‏ ‏يَعْلَى ‏ ‏فَكُنْتُ مِمَّا ‏ ‏يَلِي ‏ ‏الْبَيْتَ ‏ ‏فَلَمَّا بَلَغْتُ الرُّكْنَ الْغَرْبِيَّ الَّذِي ‏ ‏يَلِي ‏ ‏الْأَسْوَدَ جَرَرْتُ بِيَدِهِ لِيَسْتَلِمَ فَقَالَ مَا شَأْنُكَ فَقُلْتُ أَلَا تَسْتَلِمُ قَالَ أَلَمْ تَطُفْ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ بَلَى فَقَالَ ‏ ‏أَفَرَأَيْتَهُ يَسْتَلِمُ هَذَيْنِ الرُّكْنَيْنِ الْغَرْبِيَّيْنِ قَالَ فَقُلْتُ لَا قَالَ أَفَلَيْسَ لَكَ فِيهِ أُسْوَةٌ حَسَنَةٌ قَالَ قُلْتُ بَلَى قَالَ فَانْفُذْ عَنْكَ ‏","","",""],[297,297,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ ‏ ‏قَالَ ‏ ‏جِئْتُ بِدَنَانِيرَ لِي فَأَرَدْتُ أَنْ أَصْرِفَهَا فَلَقِيَنِي ‏ ‏طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏فَاصْطَرَفَهَا وَأَخَذَهَا فَقَالَ حَتَّى يَجِيءَ ‏ ‏سَلْمٌ ‏ ‏خَازِنِي ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏مِنْ ‏ ‏الْغَابَةِ ‏ ‏وَقَالَ فِيهَا كُلِّهَا ‏ ‏هَاءَ وَهَاءَ ‏ ‏قَالَ فَسَأَلْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ذَلِكَ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الذَّهَبُ ‏ ‏بِالْوَرِقِ ‏ ‏رِبًا إِلَّا ‏ ‏هَاءَ وَهَاءَ ‏ ‏وَالْبُرُّ ‏ ‏بِالْبُرِّ ‏ ‏رِبًا إِلَّا ‏ ‏هَاءَ وَهَاءَ ‏ ‏وَالشَّعِيرُ بِالشَّعِيرِ ‏ ‏رِبًا ‏ ‏إِلَّا ‏ ‏هَاءَ وَهَاءَ ‏ ‏وَالتَّمْرُ بِالتَّمْرِ رِبًا إِلَّا ‏ ‏هَاءَ وَهَاءَ ‏","","",""],[298,298,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَيِّتَ يُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ ‏","","",""],[299,299,"","","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي أُنَاسٍ مِنْ قَوْمِي فَجَعَلَ ‏ ‏يَفْرِضُ ‏ ‏لِلرَّجُلِ مِنْ ‏ ‏طَيِّئٍ ‏ ‏فِي أَلْفَيْنِ وَيُعْرِضُ عَنِّي قَالَ فَاسْتَقْبَلْتُهُ فَأَعْرَضَ عَنِّي ثُمَّ أَتَيْتُهُ مِنْ حِيَالِ وَجْهِهِ فَأَعْرَضَ عَنِّي قَالَ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ أَتَعْرِفُنِي قَالَ فَضَحِكَ حَتَّى اسْتَلْقَى لِقَفَاهُ ثُمَّ قَالَ نَعَمْ وَاللَّهِ إِنِّي لَأَعْرِفُكَ آمَنْتَ إِذْ كَفَرُوا وَأَقْبَلْتَ إِذْ أَدْبَرُوا وَوَفَيْتَ إِذْ غَدَرُوا ‏ ‏وَإِنَّ أَوَّلَ ‏ ‏صَدَقَةٍ ‏ ‏بَيَّضَتْ وَجْهَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَوُجُوهَ أَصْحَابِهِ ‏ ‏صَدَقَةُ ‏ ‏طَيِّئٍ ‏ ‏جِئْتَ بِهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَخَذَ يَعْتَذِرُ ثُمَّ قَالَ إِنَّمَا فَرَضْتُ لِقَوْمٍ أَجْحَفَتْ بِهِمْ ‏ ‏الْفَاقَةُ ‏ ‏وَهُمْ سَادَةُ عَشَائِرِهِمْ لِمَا يَنُوبُهُمْ مِنْ الْحُقُوقِ ‏","","",""],[300,300,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏فِيمَا ‏ ‏الرَّمَلَانُ ‏ ‏الْآنَ وَالْكَشْفُ عَنْ الْمَنَاكِبِ وَقَدْ ‏ ‏أَطَّأَ ‏ ‏اللَّهُ الْإِسْلَامَ وَنَفَى الْكُفْرَ وَأَهْلَهُ وَمَعَ ذَلِكَ لَا نَدَعُ شَيْئًا كُنَّا نَفْعَلُهُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[301,301,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي الْفُرَاتِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏عَنِ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ الدِّيلِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏الْمَدِينَةَ ‏ ‏وَقَدْ وَقَعَ بِهَا مَرَضٌ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فَهُمْ يَمُوتُونَ مَوْتًا ذَرِيعًا ‏ ‏فَجَلَسْتُ إِلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَمَرَّتْ بِهِ جَنَازَةٌ فَأُثْنِيَ عَلَى صَاحِبِهَا خَيْرٌ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَجَبَتْ ثُمَّ مُرَّ بِأُخْرَى فَأُثْنِيَ عَلَى صَاحِبِهَا خَيْرٌ فَقَالَ وَجَبَتْ ثُمَّ مُرَّ بِأُخْرَى فَأُثْنِيَ عَلَيْهَا شَرٌّ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَجَبَتْ فَقَالَ ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏فَقُلْتُ لَهُ يَا أَمِيرَ الْمُؤْمِنِينَ مَا وَجَبَتْ فَقَالَ قُلْتُ كَمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا مُسْلِمٍ شَهِدَ لَهُ أَرْبَعَةٌ بِخَيْرٍ إِلَّا أَدْخَلَهُ اللَّهُ الْجَنَّةَ قَالَ قُلْنَا وَثَلَاثَةٌ قَالَ وَثَلَاثَةٌ قُلْنَا وَاثْنَانِ قَالَ وَاثْنَانِ قَالَ وَلَمْ نَسْأَلْهُ عَنْ الْوَاحِدِ ‏","","",""],[302,302,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ يَعْنِي ابْنَ شَدَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَخْطُبُ إِذْ جَاءَ ‏ ‏رَجُلٌ ‏ ‏فَجَلَسَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏لِمَ تَحْتَبِسُونَ عَنْ الْجُمُعَةِ فَقَالَ الرَّجُلُ يَا أَمِيرَ الْمُؤْمِنِينَ مَا هُوَ إِلَّا أَنْ سَمِعْتُ النِّدَاءَ فَتَوَضَّأْتُ ثُمَّ أَقْبَلْتُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَأَيْضًا أَلَمْ تَسْمَعُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا رَاحَ أَحَدُكُمْ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ الْمُعَلِّمُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَيْنَا هُوَ يَخْطُبُ ‏ ‏فَذَكَرَهُ ‏","","",""],[303,303,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حِطَّانَ ‏ ‏فِيمَا يَحْسِبُ ‏ ‏حَرْبٌ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ لَبُوسِ الْحَرِيرِ فَقَالَ سَلْ عَنْهُ ‏ ‏عَائِشَةَ ‏ ‏فَسَأَلَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ سَلْ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَسَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏أَبُو حَفْصٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا فَلَا ‏ ‏خَلَاقَ ‏ ‏لَهُ فِي الْآخِرَةِ ‏","","",""],[304,304,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَبْدِ اللَّهِ الْأَوْدِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏بِالْبَصْرَةِ ‏ ‏قَالَ ‏ ‏أَنَا أَوَّلُ مَنْ أَتَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حِينَ ‏ ‏طُعِنَ ‏ ‏فَقَالَ احْفَظْ عَنِّي ثَلَاثًا فَإِنِّي أَخَافُ أَنْ لَا يُدْرِكَنِي النَّاسُ أَمَّا أَنَا فَلَمْ أَقْضِ فِي ‏ ‏الْكَلَالَةِ ‏ ‏قَضَاءً وَلَمْ أَسْتَخْلِفْ عَلَى النَّاسِ خَلِيفَةً وَكُلُّ مَمْلُوكٍ لَهُ ‏ ‏عَتِيقٌ ‏ ‏فَقَالَ لَهُ النَّاسُ اسْتَخْلِفْ فَقَالَ أَيَّ ذَلِكَ أَفْعَلُ فَقَدْ فَعَلَهُ مَنْ هُوَ خَيْرٌ مِنِّي ‏ ‏إِنْ أَدَعْ إِلَى النَّاسِ أَمْرَهُمْ فَقَدْ تَرَكَهُ نَبِيُّ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏وَإِنْ أَسْتَخْلِفْ فَقَدْ اسْتَخْلَفَ مَنْ هُوَ خَيْرٌ مِنِّي ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقُلْتُ لَهُ أَبْشِرْ بِالْجَنَّةِ صَاحَبْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَطَلْتَ صُحْبَتَهُ وَوُلِّيتَ أَمْرَ الْمُؤْمِنِينَ فَقَوِيتَ وَأَدَّيْتَ الْأَمَانَةَ فَقَالَ أَمَّا تَبْشِيرُكَ إِيَّايَ بِالْجَنَّةِ فَوَاللَّهِ لَوْ أَنَّ لِي ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فَلَا وَاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ لَوْ أَنَّ لِي ‏ ‏الدُّنْيَا بِمَا فِيهَا لَافْتَدَيْتُ بِهِ مِنْ هَوْلِ مَا أَمَامِي قَبْلَ أَنْ أَعْلَمَ الْخَبَرَ وَأَمَّا قَوْلُكَ فِي أَمْرِ الْمُؤْمِنِينَ فَوَاللَّهِ لَوَدِدْتُ أَنَّ ذَلِكَ كَفَافًا لَا لِي وَلَا عَلَيَّ وَأَمَّا مَا ذَكَرْتَ مِنْ صُحْبَةِ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَلِكَ ‏","","",""],[305,305,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِلَى ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏أَنْ عَلِّمُوا غِلْمَانَكُمْ الْعَوْمَ وَمُقَاتِلَتَكُمْ الرَّمْيَ فَكَانُوا يَخْتَلِفُونَ إِلَى الْأَغْرَاضِ فَجَاءَ سَهْمٌ غَرْبٌ إِلَى غُلَامٍ فَقَتَلَهُ فَلَمْ يُوجَدْ لَهُ أَصْلٌ وَكَانَ فِي حَجْرِ خَالٍ لَهُ فَكَتَبَ فِيهِ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏إِلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِلَى مَنْ أَدْفَعُ ‏ ‏عَقْلَهُ ‏ ‏فَكَتَبَ إِلَيْهِ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُ وَرَسُولُهُ مَوْلَى مَنْ لَا مَوْلَى لَهُ وَالْخَالُ وَارِثُ مَنْ لَا وَارِثَ لَهُ ‏","","",""],[306,306,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَرِثُ ‏ ‏الْوَلَاءَ ‏ ‏مَنْ وَرِثَ الْمَالَ مِنْ وَالِدٍ أَوْ وَلَدٍ ‏","","",""],[307,307,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَابِسِ بْنِ رَبِيعَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَتَى الْحَجَرَ فَقَالَ أَمَا وَاللَّهِ ‏ ‏إِنِّي لَأَعْلَمُ أَنَّكَ حَجَرٌ لَا تَضُرُّ وَلَا تَنْفَعُ وَلَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبَّلَكَ مَا قَبَّلْتُكَ ثُمَّ دَنَا فَقَبَّلَهُ ‏","","",""],[308,308,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏دُجَيْنٌ أَبُو الْغُصْنِ ‏ ‏بَصْرِيٌّ ‏ ‏قَالَ ‏ ‏قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَلَقِيتُ ‏ ‏أَسْلَمَ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقُلْتُ حَدِّثْنِي عَنْ ‏ ‏عُمَرَ ‏ ‏فَقَالَ لَا أَسْتَطِيعُ أَخَافُ أَنْ أَزِيدَ أَوْ أَنْقُصَ كُنَّا إِذَا قُلْنَا ‏ ‏لِعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَخَافُ أَنْ أَزِيدَ حَرْفًا أَوْ أَنْقُصَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَذَبَ عَلَيَّ فَهُوَ فِي النَّارِ ‏","","",""],[309,309,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏مَوْلَى آلِ ‏ ‏الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ فِي سُوقٍ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ بِيَدِهِ الْخَيْرُ ‏ ‏يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ كَتَبَ اللَّهُ لَهُ بِهَا أَلْفَ أَلْفِ حَسَنَةٍ وَمَحَا عَنْهُ بِهَا أَلْفَ أَلْفِ سَيِّئَةٍ وَبَنَى لَهُ بَيْتًا فِي الْجَنَّةِ ‏","","",""],[310,310,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو زُمَيْلٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏حَدَّثَنِي ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏خَيْبَرَ ‏ ‏أَقْبَلَ نَفَرٌ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُونَ فُلَانٌ شَهِيدٌ وَفُلَانٌ شَهِيدٌ حَتَّى مَرُّوا بِرَجُلٍ فَقَالُوا فُلَانٌ شَهِيدٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلَّا ‏ ‏إِنِّي رَأَيْتُهُ يُجَرُّ إِلَى النَّارِ فِي عَبَاءَةٍ ‏ ‏غَلَّهَا ‏ ‏اخْرُجْ يَا ‏ ‏عُمَرُ ‏ ‏فَنَادِ فِي النَّاسِ إِنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا الْمُؤْمِنُونَ فَخَرَجْتُ فَنَادَيْتُ إِنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا الْمُؤْمِنُونَ ‏","","",""],[311,311,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا وَأَبِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَهْ ‏ ‏إِنَّهُ ‏ ‏مَنْ حَلَفَ بِشَيْءٍ دُونَ اللَّهِ فَقَدْ أَشْرَكَ ‏","","",""],[312,312,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ الْخَيَّاطُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏زَادَ فِي الْمَسْجِدِ مِنْ الْأُسْطُوَانَةِ إِلَى الْمَقْصُورَةِ وَزَادَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَوْلَا أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏نَبْغِي نَزِيدُ فِي مَسْجِدِنَا مَا زِدْتُ فِيهِ ‏","","",""],[313,313,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ بَعَثَ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَقِّ وَأَنْزَلَ مَعَهُ الْكِتَابَ فَكَانَ مِمَّا أُنْزِلَ عَلَيْهِ آيَةُ الرَّجْمِ ‏ ‏فَرَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَجَمْنَا ‏ ‏بَعْدَهُ ثُمَّ قَالَ قَدْ كُنَّا نَقْرَأُ وَلَا تَرْغَبُوا عَنْ آبَائِكُمْ فَإِنَّهُ كُفْرٌ بِكُمْ ‏ ‏أَوْ إِنَّ كُفْرًا بِكُمْ أَنْ تَرْغَبُوا عَنْ آبَائِكُمْ ‏ ‏ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تُطْرُونِي ‏ ‏كَمَا ‏ ‏أُطْرِيَ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏وَإِنَّمَا أَنَا عَبْدٌ فَقُولُوا عَبْدُهُ وَرَسُولُهُ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏مَعْمَرٌ ‏ ‏كَمَا أَطْرَتْ ‏ ‏النَّصَارَى ‏ ‏ابْنَ مَرْيَمَ ‏","","",""],[314,314,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنِّي سَمِعْتُ النَّاسَ يَقُولُونَ مَقَالَةً ‏ ‏فَآلَيْتُ ‏ ‏أَنْ أَقُولَهَا لَكُمْ زَعَمُوا أَنَّكَ غَيْرُ مُسْتَخْلِفٍ فَوَضَعَ رَأْسَهُ سَاعَةً ثُمَّ رَفَعَهُ فَقَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَحْفَظُ دِينَهُ ‏ ‏وَإِنِّي إِنْ لَا أَسْتَخْلِفْ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَسْتَخْلِفْ وَإِنْ أَسْتَخْلِفْ فَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَدْ اسْتَخْلَفَ قَالَ فَوَاللَّهِ مَا هُوَ إِلَّا أَنْ ذَكَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏فَعَلِمْتُ أَنَّهُ لَمْ يَكُنْ يَعْدِلُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَدًا وَأَنَّهُ غَيْرُ مُسْتَخْلِفٍ ‏","","",""],[315,315,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ ‏ ‏قَالَ ‏ ‏أَرْسَلَ إِلَيَّ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقُلْتُ لَكُمَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا نُورَثُ مَا تَرَكْنَا ‏ ‏صَدَقَةٌ ‏","","",""],[316,316,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏لَمَّا مَاتَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بُكِيَ عَلَيْهِ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَيِّتَ يُعَذَّبُ بِبُكَاءِ الْحَيِّ ‏","","",""],[317,317,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَفَرَ مَنْ كَفَرَ قَالَ قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏كَيْفَ تُقَاتِلُ النَّاسَ وَقَدْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَمَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ فَقَدْ عَصَمَ مِنِّي مَالَهُ وَنَفْسَهُ وَحِسَابُهُ عَلَى اللَّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلَاةِ وَالزَّكَاةِ إِنَّ الزَّكَاةَ حَقُّ الْمَالِ وَاللَّهِ لَوْ مَنَعُونِي ‏ ‏عَنَاقًا ‏ ‏كَانُوا يُؤَدُّونَهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَاتَلْتُهُمْ عَلَى مَنْعِهَا ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَاللَّهِ مَا هُوَ إِلَّا أَنْ رَأَيْتُ أَنَّ اللَّهَ قَدْ شَرَحَ صَدْرَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِالْقِتَالِ فَعَرَفْتُ أَنَّهُ الْحَقُّ ‏","","",""],[318,318,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا لَا نُورَثُ مَا تَرَكْنَا ‏ ‏صَدَقَةٌ ‏","","",""],[319,319,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَ إِلَيَّ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏وَقَالَ ‏ ‏إِنَّ أَمْوَالَ ‏ ‏بَنِي النَّضِيرِ ‏ ‏كَانَتْ مِمَّا ‏ ‏أَفَاءَ ‏ ‏اللَّهُ عَلَى رَسُولِهِ مِمَّا لَمْ ‏ ‏يُوجِفْ ‏ ‏عَلَيْهِ الْمُسْلِمُونَ بِخَيْلٍ وَلَا رِكَابٍ فَكَانَ يُنْفِقُ عَلَى أَهْلِهِ مِنْهَا نَفَقَةَ سَنَةٍ وَمَا بَقِيَ جَعَلَهُ فِي ‏ ‏الْكُرَاعِ ‏ ‏وَالسِّلَاحِ عُدَّةً فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[320,320,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَقْبَلَ اللَّيْلُ وَأَدْبَرَ النَّهَارُ وَغَرَبَتْ الشَّمْسُ فَقَدْ أَفْطَرَ الصَّائِمُ ‏","","",""],[321,321,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَرَدْتُ أَنْ أَسْأَلَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَمَا رَأَيْتُ مَوْضِعًا فَمَكَثْتُ سَنَتَيْنِ فَلَمَّا كُنَّا ‏ ‏بِمَرِّ الظَّهْرَانِ ‏ ‏وَذَهَبَ لِيَقْضِيَ حَاجَتَهُ فَجَاءَ وَقَدْ قَضَى حَاجَتَهُ فَذَهَبْتُ أَصُبُّ عَلَيْهِ مِنْ الْمَاءِ قُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ ‏ ‏مَنْ الْمَرْأَتَانِ اللَّتَانِ ‏ ‏تَظَاهَرَتَا ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَائِشَةُ ‏ ‏وَحَفْصَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏","","",""],[322,322,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَبِي الْعَجْفَاءِ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏لَا تُغْلُوا ‏ ‏صُدُقَ ‏ ‏النِّسَاءِ فَإِنَّهَا لَوْ كَانَتْ ‏ ‏مَكْرُمَةً ‏ ‏فِي الدُّنْيَا أَوْ تَقْوَى فِي الْآخِرَةِ لَكَانَ أَوْلَاكُمْ بِهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَنْكَحَ شَيْئًا مِنْ بَنَاتِهِ وَلَا نِسَائِهِ فَوْقَ اثْنَتَيْ عَشْرَةَ ‏ ‏وُقِيَّةً ‏ ‏وَأُخْرَى تَقُولُونَهَا فِي مَغَازِيكُمْ قُتِلَ فُلَانٌ شَهِيدًا مَاتَ فُلَانٌ شَهِيدًا وَلَعَلَّهُ أَنْ يَكُونَ قَدْ أَوْقَرَ عَجُزَ دَابَّتِهِ أَوْ ‏ ‏دَفَّ ‏ ‏رَاحِلَتِهِ ‏ ‏ذَهَبًا وَفِضَّةً يَبْتَغِي التِّجَارَةَ فَلَا تَقُولُوا ‏ ‏ذَاكُمْ وَلَكِنْ قُولُوا كَمَا قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قُتِلَ فِي سَبِيلِ اللَّهِ فَهُوَ فِي الْجَنَّةِ ‏","","",""],[323,323,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏أَمَلَّهُ عَلَيَّ عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ الْغَطَفَانِيِّ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمَرِيِّ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَامَ خَطِيبًا فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ وَذَكَرَ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏ثُمَّ قَالَ إِنِّي رَأَيْتُ رُؤْيَا كَأَنَّ دِيكًا نَقَرَنِي نَقْرَتَيْنِ وَلَا ‏ ‏أُرَى ذَلِكَ إِلَّا لِحُضُورِ أَجَلِي وَإِنَّ نَاسًا يَأْمُرُونَنِي أَنْ أَسْتَخْلِفَ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَمْ يَكُنْ لِيُضِيعَ خِلَافَتَهُ وَدِينَهُ وَلَا الَّذِي بَعَثَ بِهِ نَبِيَّهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنْ عَجِلَ بِي أَمْرٌ فَالْخِلَافَةُ شُورَى فِي هَؤُلَاءِ ‏ ‏الرَّهْطِ ‏ ‏السِّتَّةِ الَّذِينَ تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَنْهُمْ رَاضٍ فَأَيُّهُمْ بَايَعْتُمْ لَهُ فَاسْمَعُوا لَهُ وَأَطِيعُوا وَقَدْ عَرَفْتُ أَنَّ رِجَالًا سَيَطْعَنُونَ فِي هَذَا الْأَمْرِ وَإِنِّي قَاتَلْتُهُمْ بِيَدِي هَذِهِ عَلَى الْإِسْلَامِ فَإِنْ فَعَلُوا فَأُولَئِكَ أَعْدَاءُ اللَّهِ الْكَفَرَةُ الضُّلَّالُ وَإِنِّي وَاللَّهِ ‏ ‏مَا أَدَعُ بَعْدِي شَيْئًا هُوَ أَهَمُّ إِلَيَّ مِنْ أَمْرِ ‏ ‏الْكَلَالَةِ ‏ ‏وَلَقَدْ سَأَلْتُ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهَا فَمَا أَغْلَظَ لِي فِي شَيْءٍ قَطُّ مَا أَغْلَظَ لِي فِيهَا حَتَّى طَعَنَ بِيَدِهِ ‏ ‏أَوْ بِإِصْبَعِهِ ‏ ‏فِي صَدْرِي ‏ ‏أَوْ جَنْبِي ‏ ‏وَقَالَ يَا ‏ ‏عُمَرُ ‏ ‏تَكْفِيكَ الْآيَةُ الَّتِي نَزَلَتْ فِي الصَّيْفِ الَّتِي فِي آخِرِ سُورَةِ ‏ ‏النِّسَاءِ ‏ ‏وَإِنِّي إِنْ أَعِشْ أَقْضِ فِيهَا قَضِيَّةً لَا يَخْتَلِفُ فِيهَا أَحَدٌ يَقْرَأُ الْقُرْآنَ أَوْ لَا يَقْرَأُ الْقُرْآنَ ثُمَّ قَالَ اللَّهُمَّ إِنِّي أُشْهِدُكَ عَلَى أُمَرَاءِ ‏ ‏الْأَمْصَارِ ‏ ‏فَإِنِّي بَعَثْتُهُمْ يُعَلِّمُونَ النَّاسَ دِينَهُمْ وَسُنَّةَ نَبِيِّهِمْ وَيَقْسِمُونَ فِيهِمْ فَيْئَهُمْ وَيُعَدِّلُونَ عَلَيْهِمْ وَمَا أَشْكَلَ عَلَيْهِمْ يَرْفَعُونَهُ ‏ ‏إِلَيَّ ثُمَّ قَالَ يَا أَيُّهَا النَّاسُ إِنَّكُمْ تَأْكُلُونَ مِنْ شَجَرَتَيْنِ لَا ‏ ‏أُرَاهُمَا إِلَّا خَبِيثَتَيْنِ هَذَا الثُّومُ وَالْبَصَلُ لَقَدْ كُنْتُ أَرَى الرَّجُلَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوجَدُ رِيحُهُ مِنْهُ فَيُؤْخَذُ بِيَدِهِ حَتَّى يُخْرَجَ بِهِ إِلَى ‏ ‏الْبَقِيعِ ‏ ‏فَمَنْ كَانَ آكِلَهُمَا لَا بُدَّ فَلْيُمِتْهُمَا طَبْخًا ‏ ‏قَالَ ‏ ‏فَخَطَبَ بِهَا ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَوْمَ الْجُمُعَةِ وَأُصِيبَ يَوْمَ الْأَرْبِعَاءِ لِأَرْبَعِ لَيَالٍ بَقِينَ مِنْ ذِي الْحِجَّةِ ‏","","",""],[324,324,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏وَأَخْبَرَنِي ‏ ‏هُشَيْمٌ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ أَرْطَاةَ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏هِيَ سُنَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي الْمُتْعَةَ ‏ ‏وَلَكِنِّي أَخْشَى أَنْ يُعَرِّسُوا بِهِنَّ تَحْتَ الْأَرَاكِ ثُمَّ يَرُوحُوا بِهِنَّ حُجَّاجًا ‏","","",""],[325,325,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَنْبَأَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏جَدِّهِ ‏ ‏الشَّكُّ مِنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ بَعْدَ ‏ ‏الْحَدَثِ ‏ ‏وَمَسَحَ عَلَى خُفَّيْهِ وَصَلَّى ‏","","",""],[326,326,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِيَاضًا الْأَشْعَرِيَّ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏الْيَرْمُوكَ ‏ ‏وَعَلَيْنَا خَمْسَةُ أُمَرَاءَ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏وَيَزِيدُ بْنُ أَبِي سُفْيَانَ ‏ ‏وَابْنُ حَسَنَةَ ‏ ‏وَخَالِدُ بْنُ الْوَلِيدِ ‏ ‏وَعِيَاضٌ ‏ ‏وَلَيْسَ ‏ ‏عِيَاضٌ ‏ ‏هَذَا بِالَّذِي حَدَّثَ ‏ ‏سِمَاكًا ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِذَا كَانَ قِتَالٌ فَعَلَيْكُمْ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏قَالَ فَكَتَبْنَا إِلَيْهِ إِنَّهُ قَدْ جَاشَ إِلَيْنَا الْمَوْتُ وَاسْتَمْدَدْنَاهُ فَكَتَبَ إِلَيْنَا إِنَّهُ قَدْ جَاءَنِي كِتَابُكُمْ تَسْتَمِدُّونِي وَإِنِّي أَدُلُّكُمْ عَلَى مَنْ هُوَ أَعَزُّ نَصْرًا ‏ ‏وَأَحْضَرُ جُنْدًا اللَّهُ عَزَّ وَجَلَّ فَاسْتَنْصِرُوهُ ‏ ‏فَإِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ نُصِرَ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فِي أَقَلَّ مِنْ عِدَّتِكُمْ فَإِذَا أَتَاكُمْ كِتَابِي هَذَا فَقَاتِلُوهُمْ وَلَا تُرَاجِعُونِي قَالَ فَقَاتَلْنَاهُمْ فَهَزَمْنَاهُمْ وَقَتَلْنَاهُمْ أَرْبَعَ فَرَاسِخَ قَالَ وَأَصَبْنَا أَمْوَالًا فَتَشَاوَرُوا فَأَشَارَ عَلَيْنَا ‏ ‏عِيَاضٌ ‏ ‏أَنْ نُعْطِيَ عَنْ كُلِّ رَأْسٍ عَشْرَةً قَالَ وَقَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏مَنْ يُرَاهِنِّي فَقَالَ شَابٌّ أَنَا إِنْ لَمْ تَغْضَبْ قَالَ فَسَبَقَهُ فَرَأَيْتُ ‏ ‏عَقِيصَتَيْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏تَنْقُزَانِ ‏ ‏وَهُوَ خَلْفَهُ عَلَى فَرَسٍ عَرَبِيٍّ ‏","","",""],[327,327,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَنْبَأَنَا ‏ ‏عُيَيْنَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَعَلَيَّ ‏ ‏جُبَّةُ ‏ ‏خَزٍّ ‏ ‏فَقَالَ لِي ‏ ‏سَالِمٌ ‏ ‏مَا تَصْنَعُ بِهَذِهِ الثِّيَابِ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ‏","","",""],[328,328,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُنْذِرِ إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏أُرَاهُ ‏ ‏عَنِ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَتَلَ رَجُلٌ ابْنَهُ عَمْدًا فَرُفِعَ إِلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَجَعَلَ عَلَيْهِ مِائَةً مِنْ الْإِبِلِ ثَلَاثِينَ ‏ ‏حِقَّةً ‏ ‏وَثَلَاثِينَ ‏ ‏جَذَعَةً ‏ ‏وَأَرْبَعِينَ ثَنِيَّةً وَقَالَ لَا يَرِثُ الْقَاتِلُ وَلَوْلَا أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يُقْتَلُ وَالِدٌ بِوَلَدِهِ لَقَتَلْتُكَ ‏","","",""],[329,329,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏وَيَزِيدُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَوْلَا أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْسَ لِقَاتِلٍ شَيْءٌ لَوَرَّثْتُكَ قَالَ وَدَعَا خَالَ الْمَقْتُولِ فَأَعْطَاهُ الْإِبِلَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي نَجِيحٍ ‏ ‏وَعَمْرُو بْنُ شُعَيْبٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ جَبْرٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏وَقَالَ ‏ ‏أَخَذَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مِنْ الْإِبِلِ ثَلَاثِينَ ‏ ‏حِقَّةً ‏ ‏وَثَلَاثِينَ ‏ ‏جَذَعَةً ‏ ‏وَأَرْبَعِينَ ‏ ‏ثَنِيَّةً ‏ ‏إِلَى ‏ ‏بَازِلِ ‏ ‏عَامِهَا كُلُّهَا ‏ ‏خَلِفَةٌ ‏ ‏قَالَ ثُمَّ دَعَا أَخَا الْمَقْتُولِ فَأَعْطَاهَا إِيَّاهُ دُونَ أَبِيهِ وَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لَيْسَ لِقَاتِلٍ شَيْءٌ ‏","","",""],[330,330,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏الْعَبَّاسُ ‏ ‏وَعَلِيٌّ ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏إِلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَخْتَصِمَانِ فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏اقْضِ بَيْنِي وَبَيْنَ هَذَا ‏ ‏الْكَذَا كَذَا فَقَالَ النَّاسُ افْصِلْ بَيْنَهُمَا افْصِلْ بَيْنَهُمَا قَالَ لَا أَفْصِلُ بَيْنَهُمَا قَدْ عَلِمَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا نُورَثُ مَا تَرَكْنَا ‏ ‏صَدَقَةٌ ‏","","",""],[331,331,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ آخِرِ مَا أُنْزِلَ ‏ ‏آيَةُ الرِّبَا ‏ ‏وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُوُفِّيَ وَلَمْ يُفَسِّرْهَا فَدَعُوا الرِّبَا وَالرِّيبَةَ ‏","","",""],[332,332,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّهُ كَانَ ‏ ‏يُفْتِي بِالْمُتْعَةِ فَقَالَ لَهُ رَجُلٌ رُوَيْدَكَ بِبَعْضِ فُتْيَاكَ فَإِنَّكَ لَا تَدْرِي مَا أَحْدَثَ أَمِيرُ الْمُؤْمِنِينَ فِي النُّسُكِ بَعْدَكَ حَتَّى لَقِيَهُ بَعْدُ فَسَأَلَهُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَدْ عَلِمْتُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ فَعَلَهُ وَأَصْحَابُهُ وَلَكِنِّي كَرِهْتُ أَنْ يَظَلُّوا بِهِنَّ ‏ ‏مُعَرِّسِينَ ‏ ‏فِي ‏ ‏الْأَرَاكِ ‏ ‏وَيَرُوحُوا لِلْحَجِّ ‏ ‏تَقْطُرُ رُءُوسُهُمْ ‏","","",""],[333,333,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏حَجَّ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَرَادَ أَنْ يَخْطُبَ النَّاسَ خُطْبَةً فَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏إِنَّهُ قَدْ اجْتَمَعَ عِنْدَكَ ‏ ‏رَعَاعُ ‏ ‏النَّاسِ فَأَخِّرْ ذَلِكَ حَتَّى تَأْتِيَ ‏ ‏الْمَدِينَةَ ‏ ‏فَلَمَّا قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏دَنَوْتُ مِنْهُ قَرِيبًا مِنْ الْمِنْبَرِ فَسَمِعْتُهُ يَقُولُ وَإِنَّ نَاسًا يَقُولُونَ مَا بَالُ الرَّجْمِ وَإِنَّمَا فِي كِتَابِ اللَّهِ الْجَلْدُ ‏ ‏وَقَدْ ‏ ‏رَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَجَمْنَا ‏ ‏بَعْدَهُ وَلَوْلَا أَنْ يَقُولُوا أَثْبَتَ فِي كِتَابِ اللَّهِ مَا لَيْسَ فِيهِ لَأَثْبَتُّهَا كَمَا أُنْزِلَتْ ‏","","",""],[334,334,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ يَعْنِي ابْنَ بَشِيرٍ ‏ ‏يَخْطُبُ ‏ ‏قَالَ ‏ ‏ذَكَرَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَا أَصَابَ النَّاسُ مِنْ الدُّنْيَا فَقَالَ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَظَلُّ الْيَوْمَ ‏ ‏يَلْتَوِي مَا يَجِدُ ‏ ‏دَقَلًا ‏ ‏يَمْلَأُ بِهِ بَطْنَهُ ‏","","",""],[335,335,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَيِّتُ يُعَذَّبُ فِي قَبْرِهِ بِمَا ‏ ‏نِيحَ ‏ ‏عَلَيْهِ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏بِالنِّيَاحَةِ ‏ ‏عَلَيْهِ ‏","","",""],[336,336,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رُفَيْعًا أَبَا الْعَالِيَةِ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدَّثَنِي ‏ ‏رِجَالٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَحْسِبُهُ قَالَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَأَعْجَبُهُمْ إِلَيَّ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الصَّلَاةِ فِي سَاعَتَيْنِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَبَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ ‏","","",""],[337,337,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ النَّهْدِيَّ ‏ ‏قَالَ ‏ ‏جَاءَنَا كِتَابُ ‏ ‏عُمَرَ ‏ ‏وَنَحْنُ ‏ ‏بِأَذْرَبِيجَانَ ‏ ‏مَعَ ‏ ‏عُتْبَةَ بْنِ فَرْقَدٍ ‏ ‏أَوْ ‏ ‏بِالشَّامِ ‏ ‏أَمَّا بَعْدُ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الْحَرِيرِ إِلَّا هَكَذَا أُصْبُعَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عُثْمَانَ ‏ ‏فَمَا عَتَّمْنَا إِلَّا أَنَّهُ ‏ ‏الْأَعْلَامُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ النَّهْدِيَّ ‏ ‏قَالَ ‏ ‏جَاءَنَا كِتَابُ ‏ ‏عُمَرَ ‏","","",""],[338,338,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏قَالَ ‏ ‏صَلَّى ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏الصُّبْحَ وَهُوَ ‏ ‏بِجَمْعٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُدَ ‏ ‏كُنَّا مَعَ ‏ ‏عُمَرَ ‏ ‏بِجَمْعٍ ‏ ‏فَقَالَ ‏ ‏إِنَّ الْمُشْرِكِينَ كَانُوا لَا يُفِيضُونَ حَتَّى تَطْلُعَ الشَّمْسُ وَيَقُولُونَ أَشْرِقْ ‏ ‏ثَبِيرُ ‏ ‏وَإِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَالَفَهُمْ ‏ ‏فَأَفَاضَ ‏ ‏قَبْلَ طُلُوعِ الشَّمْسِ ‏","","",""],[339,339,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَأَلَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏تُصِيبُنِي الْجَنَابَةُ مِنْ اللَّيْلِ فَمَا أَصْنَعُ قَالَ اغْسِلْ ذَكَرَكَ ثُمَّ تَوَضَّأْ ثُمَّ ارْقُدْ ‏","","",""],[340,340,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْحَكَمِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنِ ‏ ‏الْجَرِّ ‏ ‏فَحَدَّثَنَا عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْجَرِّ ‏ ‏وَعَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَعَنْ ‏ ‏الْمُزَفَّتِ ‏","","",""],[341,341,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَرْجِسَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏الْأُصَيْلِعَ يَعْنِي عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُقَبِّلُ الْحَجَرَ وَيَقُولُ أَمَا إِنِّي أَعْلَمُ أَنَّكَ حَجَرٌ وَلَكِنْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُكَ ‏","","",""],[342,342,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا جَمْرَةَ الضُّبَعِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جُوَيْرِيَةَ بْنِ قُدَامَةَ ‏ ‏قَالَ ‏ ‏حَجَجْتُ فَأَتَيْتُ ‏ ‏الْمَدِينَةَ ‏ ‏الْعَامَ الَّذِي أُصِيبَ فِيهِ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ فَخَطَبَ فَقَالَ إِنِّي رَأَيْتُ كَأَنَّ دِيكًا أَحْمَرَ نَقَرَنِي نَقْرَةً ‏ ‏أَوْ نَقْرَتَيْنِ ‏ ‏شُعْبَةُ ‏ ‏الشَّاكُّ ‏ ‏فَكَانَ مِنْ أَمْرِهِ أَنَّهُ طُعِنَ فَأُذِنَ لِلنَّاسِ عَلَيْهِ فَكَانَ أَوَّلَ مَنْ دَخَلَ عَلَيْهِ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏ثُمَّ أَهْلُ ‏ ‏الشَّامِ ‏ ‏ثُمَّ أُذِنَ لِأَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏فَدَخَلْتُ فِيمَنْ دَخَلَ قَالَ فَكَانَ كُلَّمَا دَخَلَ عَلَيْهِ قَوْمٌ أَثْنَوْا عَلَيْهِ وَبَكَوْا قَالَ فَلَمَّا دَخَلْنَا عَلَيْهِ قَالَ وَقَدْ ‏ ‏عَصَبَ ‏ ‏بَطْنَهُ بِعِمَامَةٍ سَوْدَاءَ وَالدَّمُ يَسِيلُ قَالَ فَقُلْنَا أَوْصِنَا قَالَ وَمَا سَأَلَهُ الْوَصِيَّةَ أَحَدٌ غَيْرُنَا فَقَالَ ‏ ‏عَلَيْكُمْ بِكِتَابِ اللَّهِ فَإِنَّكُمْ لَنْ تَضِلُّوا مَا اتَّبَعْتُمُوهُ فَقُلْنَا أَوْصِنَا فَقَالَ ‏ ‏أُوصِيكُمْ ‏ ‏بِالْمُهَاجِرِينَ ‏ ‏فَإِنَّ النَّاسَ سَيَكْثُرُونَ وَيَقِلُّونَ ‏ ‏وَأُوصِيكُمْ ‏ ‏بِالْأَنْصَارِ ‏ ‏فَإِنَّهُمْ شَعْبُ الْإِسْلَامِ الَّذِي ‏ ‏لَجِئَ إِلَيْهِ ‏ ‏وَأُوصِيكُمْ ‏ ‏بِالْأَعْرَابِ ‏ ‏فَإِنَّهُمْ أَصْلُكُمْ وَمَادَّتُكُمْ ‏ ‏وَأُوصِيكُمْ بِأَهْلِ ‏ ‏ذِمَّتِكُمْ ‏ ‏فَإِنَّهُمْ عَهْدُ نَبِيِّكُمْ وَرِزْقُ عِيَالِكُمْ قُومُوا عَنِّي قَالَ فَمَا زَادَنَا عَلَى هَؤُلَاءِ الْكَلِمَاتِ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏ثُمَّ سَأَلْتُهُ بَعْدَ ذَلِكَ فَقَالَ فِي ‏ ‏الْأَعْرَابِ ‏ ‏وَأُوصِيكُمْ ‏ ‏بِالْأَعْرَابِ ‏ ‏فَإِنَّهُمْ إِخْوَانُكُمْ وَعَدُوُّ عَدُوِّكُمْ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا جَمْرَةَ الضُّبَعِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جُوَيْرِيَةَ بْنِ قُدَامَةَ ‏ ‏قَالَ ‏ ‏حَجَجْتُ فَأَتَيْتُ ‏ ‏الْمَدِينَةَ ‏ ‏الْعَامَ الَّذِي أُصِيبَ فِيهِ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ فَخَطَبَ فَقَالَ إِنِّي رَأَيْتُ كَأَنَّ دِيكًا أَحْمَرَ نَقَرَنِي نَقْرَةً ‏ ‏أَوْ نَقْرَتَيْنِ ‏ ‏شُعْبَةُ ‏ ‏الشَّاكُّ ‏ ‏قَالَ فَمَا لَبِثَ إِلَّا جُمُعَةً حَتَّى طُعِنَ فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ ‏ ‏وَأُوصِيكُمْ بِأَهْلِ ذِمَّتِكُمْ فَإِنَّهُمْ ذِمَّةُ نَبِيِّكُمْ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏ثُمَّ سَأَلْتُهُ بَعْدَ ذَلِكَ فَقَالَ فِي ‏ ‏الْأَعْرَابِ ‏ ‏وَأُوصِيكُمْ ‏ ‏بِالْأَعْرَابِ ‏ ‏فَإِنَّهُمْ إِخْوَانُكُمْ وَعَدُوُّ عَدُوِّكُمْ ‏","","",""],[343,343,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قَالَ ‏ ‏شَهِدَ عِنْدِي رِجَالٌ مَرْضِيُّونَ فِيهِمْ ‏ ‏عُمَرُ ‏ ‏وَأَرْضَاهُمْ عِنْدِي ‏ ‏عُمَرُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ صَلَاةٍ بَعْدَ صَلَاةِ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ ‏","","",""],[344,344,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ غَفَلَةَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏خَطَبَ النَّاسَ ‏ ‏بِالْجَابِيَةِ ‏ ‏فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسِ الْحَرِيرِ إِلَّا مَوْضِعَ أُصْبُعَيْنِ أَوْ ثَلَاثَةٍ أَوْ أَرْبَعَةٍ وَأَشَارَ بِكَفِّهِ ‏","","",""],[345,345,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَيِّتُ يُعَذَّبُ فِي قَبْرِهِ بِمَا ‏ ‏نِيحَ ‏ ‏عَلَيْهِ ‏","","",""],[346,346,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنِ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنِ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ ذَاتَ يَوْمٍ عِنْدَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ شَدِيدُ سَوَادِ الشَّعَرِ لَا يُرَى ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏لَا نَرَى ‏ ‏عَلَيْهِ أَثَرَ السَّفَرِ وَلَا يَعْرِفُهُ مِنَّا أَحَدٌ حَتَّى جَلَسَ إِلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْنَدَ رُكْبَتَيْهِ إِلَى رُكْبَتَيْهِ وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ ثُمَّ قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏أَخْبِرْنِي عَنْ الْإِسْلَامِ مَا الْإِسْلَامُ فَقَالَ ‏ ‏الْإِسْلَامُ أَنْ تَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ وَتُقِيمَ الصَّلَاةَ وَتُؤْتِيَ الزَّكَاةَ وَتَصُومَ رَمَضَانَ وَتَحُجَّ ‏ ‏الْبَيْتَ ‏ ‏إِنْ اسْتَطَعْتَ إِلَيْهِ سَبِيلًا قَالَ صَدَقْتَ قَالَ فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ قَالَ ثُمَّ قَالَ أَخْبِرْنِي عَنْ الْإِيمَانِ قَالَ الْإِيمَانُ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ وَالْقَدَرِ كُلِّهِ خَيْرِهِ وَشَرِّهِ قَالَ صَدَقْتَ قَالَ فَأَخْبِرْنِي عَنْ الْإِحْسَانِ مَا الْإِحْسَانُ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ ‏ ‏قَالَ فَأَخْبِرْنِي عَنْ السَّاعَةِ قَالَ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ بِهَا ‏ ‏مِنْ السَّائِلِ قَالَ فَأَخْبِرْنِي عَنْ أَمَارَاتِهَا قَالَ أَنْ تَلِدَ الْأَمَةُ ‏ ‏رَبَّتَهَا ‏ ‏وَأَنْ ‏ ‏تَرَى الْحُفَاةَ الْعُرَاةَ رِعَاءَ الشَّاءِ ‏ ‏يَتَطَاوَلُونَ ‏ ‏فِي الْبِنَاءِ قَالَ ثُمَّ انْطَلَقَ قَالَ فَلَبِثَ ‏ ‏مَلِيًّا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏ثَلَاثًا ‏ ‏فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عُمَرُ ‏ ‏أَتَدْرِي مَنْ السَّائِلُ قَالَ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَإِنَّهُ ‏ ‏جِبْرِيلُ ‏ ‏أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ وَلَا يُرَى عَلَيْهِ أَثَرُ السَّفَرِ وَقَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَلَبِثْتُ ثَلَاثًا فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عُمَرُ ‏","","",""],[347,347,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏إِنَّ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَنْهَى عَنْ الْمُتْعَةِ وَإِنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَأْمُرُ بِهَا قَالَ فَقَالَ لِي عَلَى يَدِي جَرَى الْحَدِيثُ تَمَتَّعْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَلَمَّا وَلِيَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏خَطَبَ النَّاسَ فَقَالَ ‏ ‏إِنَّ الْقُرْآنَ هُوَ الْقُرْآنُ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ الرَّسُولُ وَإِنَّهُمَا كَانَتَا مُتْعَتَانِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِحْدَاهُمَا مُتْعَةُ الْحَجِّ وَالْأُخْرَى مُتْعَةُ النِّسَاءِ ‏","","",""],[348,348,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ أَنَّكُمْ تَوَكَّلْتُمْ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُمْ كَمَا يَرْزُقُ الطَّيْرَ تَغْدُو ‏ ‏خِمَاصًا ‏ ‏وَتَرُوحُ ‏ ‏بِطَانًا ‏","","",""],[349,349,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ابْنِ السَّاعِدِيِّ الْمَالِكِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏اسْتَعْمَلَنِي ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى ‏ ‏الصَّدَقَةِ ‏ ‏فَلَمَّا فَرَغْتُ مِنْهَا وَأَدَّيْتُهَا إِلَيْهِ أَمَرَ لِي بِعِمَالَةٍ فَقُلْتُ لَهُ إِنَّمَا عَمِلْتُ لِلَّهِ وَأَجْرِي عَلَى اللَّهِ قَالَ خُذْ مَا أُعْطِيتَ فَإِنِّي قَدْ عَمِلْتُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَمَّلَنِي فَقُلْتُ مِثْلَ قَوْلِكَ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُعْطِيتَ شَيْئًا مِنْ غَيْرِ أَنْ تَسْأَلَ فَكُلْ وَتَصَدَّقْ ‏","","",""],[350,350,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏بُكَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سَعِيدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قَالَ ‏ ‏هَشَشْتُ ‏ ‏يَوْمًا فَقَبَّلْتُ وَأَنَا صَائِمٌ فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ ‏ ‏صَنَعْتُ الْيَوْمَ أَمْرًا عَظِيمًا قَبَّلْتُ وَأَنَا صَائِمٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتَ لَوْ تَمَضْمَضْتَ بِمَاءٍ وَأَنْتَ صَائِمٌ فَقُلْتُ لَا بَأْسَ بِذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَفِيمَ ‏","","",""],[351,351,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ هُبَيْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا تَمِيمٍ الْجَيْشَانِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ أَنَّكُمْ كُنْتُمْ ‏ ‏تَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُمْ كَمَا يَرْزُقُ الطَّيْرَ أَلَا تَرَوْنَ أَنَّهَا ‏ ‏تَغْدُو ‏ ‏خِمَاصًا ‏ ‏وَتَرُوحُ ‏ ‏بِطَانًا ‏","","",""],[352,352,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ بُرَيْدَةَ ‏ ‏عَنِ ‏ ‏ابْنِ يَعْمَرَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّا نُسَافِرُ فِي الْآفَاقِ ‏ ‏فَنَلْقَى قَوْمًا يَقُولُونَ لَا ‏ ‏قَدَرَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا لَقِيتُمُوهُمْ فَأَخْبِرُوهُمْ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏مِنْهُمْ بَرِيءٌ وَأَنَّهُمْ مِنْهُ بُرَآءُ ثَلَاثًا ثُمَّ أَنْشَأَ يُحَدِّثُ بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ رَجُلٌ فَذَكَرَ مِنْ هَيْئَتِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ادْنُهْ ‏ ‏فَدَنَا فَقَالَ ‏ ‏ادْنُهْ ‏ ‏فَدَنَا فَقَالَ ‏ ‏ادْنُهْ ‏ ‏فَدَنَا حَتَّى كَادَ رُكْبَتَاهُ تَمَسَّانِ رُكْبَتَيْهِ فَقَالَ يَا رَسُولَ اللَّهِ أَخْبِرْنِي ‏ ‏مَا الْإِيمَانُ ‏ ‏أَوْ عَنْ الْإِيمَانِ ‏ ‏قَالَ تُؤْمِنُ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ وَتُؤْمِنُ بِالْقَدَرِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏أُرَاهُ قَالَ خَيْرِهِ وَشَرِّهِ ‏ ‏قَالَ فَمَا الْإِسْلَامُ قَالَ إِقَامُ الصَّلَاةِ وَإِيتَاءُ الزَّكَاةِ وَحَجُّ ‏ ‏الْبَيْتِ ‏ ‏وَصِيَامُ شَهْرِ رَمَضَانَ وَغُسْلٌ مِنْ الْجَنَابَةِ كُلُّ ذَلِكَ قَالَ صَدَقْتَ صَدَقْتَ قَالَ الْقَوْمُ مَا رَأَيْنَا رَجُلًا أَشَدَّ ‏ ‏تَوْقِيرًا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ هَذَا كَأَنَّهُ يُعَلِّمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ يَا رَسُولَ اللَّهِ أَخْبِرْنِي عَنْ الْإِحْسَانِ قَالَ أَنْ تَعْبُدَ اللَّهَ ‏ ‏أَوْ تَعْبُدَهُ ‏ ‏كَأَنَّكَ تَرَاهُ فَإِنْ لَا تَرَاهُ فَإِنَّهُ يَرَاكَ كُلُّ ذَلِكَ نَقُولُ مَا رَأَيْنَا رَجُلًا أَشَدَّ تَوْقِيرًا لِرَسُولِ اللَّهِ مِنْ هَذَا فَيَقُولُ صَدَقْتَ صَدَقْتَ قَالَ أَخْبِرْنِي عَنْ السَّاعَةِ قَالَ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ بِهَا مِنْ السَّائِلِ قَالَ فَقَالَ صَدَقْتَ قَالَ ذَلِكَ مِرَارًا مَا رَأَيْنَا رَجُلًا أَشَدَّ تَوْقِيرًا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ هَذَا ثُمَّ وَلَّى ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏فَبَلَغَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْتَمِسُوهُ فَلَمْ يَجِدُوهُ قَالَ هَذَا ‏ ‏جِبْرِيلُ ‏ ‏جَاءَكُمْ يُعَلِّمُكُمْ دِينَكُمْ مَا أَتَانِي فِي صُورَةٍ إِلَّا عَرَفْتُهُ غَيْرَ هَذِهِ الصُّورَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ بُرَيْدَةَ ‏ ‏عَنِ ‏ ‏ابْنِ يَعْمَرَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَوْ سَأَلَهُ رَجُلٌ ‏ ‏إِنَّا نَسِيرُ فِي هَذِهِ الْأَرْضِ ‏ ‏فَنَلْقَى قَوْمًا يَقُولُونَ لَا ‏ ‏قَدَرَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا لَقِيتَ أُولَئِكَ فَأَخْبِرْهُمْ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏مِنْهُمْ بَرِيءٌ وَهُمْ مِنْهُ بُرَآءُ قَالَهَا ثَلَاثَ مَرَّاتٍ ثُمَّ أَنْشَأَ يُحَدِّثُنَا قَالَ بَيْنَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَدْنُو ‏ ‏فَقَالَ ‏ ‏ادْنُهْ ‏ ‏فَدَنَا ‏ ‏رَتْوَةً ‏ ‏ثُمَّ قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَدْنُو ‏ ‏فَقَالَ ‏ ‏ادْنُهْ ‏ ‏فَدَنَا ‏ ‏رَتْوَةً ‏ ‏ثُمَّ قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَدْنُو ‏ ‏فَقَالَ ‏ ‏ادْنُهْ ‏ ‏فَدَنَا ‏ ‏رَتْوَةً ‏ ‏حَتَّى كَادَتْ أَنْ تَمَسَّ رُكْبَتَاهُ رُكْبَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَا الْإِيمَانُ فَذَكَرَ مَعْنَاهُ ‏","","",""],[353,353,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى الْأَشْيَبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ سُرَاقَةَ الْعَدَوِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَظَلَّ رَأْسَ غَازٍ أَظَلَّهُ اللَّهُ يَوْمَ الْقِيَامَةِ وَمَنْ جَهَّزَ غَازِيًا حَتَّى يَسْتَقِلَّ بِجَهَازِهِ كَانَ لَهُ مِثْلُ أَجْرِهِ وَمَنْ بَنَى مَسْجِدًا يُذْكَرُ فِيهِ اسْمُ اللَّهِ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ ‏","","",""],[354,354,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ يَعْنِي ابْنَ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَنْبَأَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏وَعُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَقَدْ بَلَغَ بِهِ أَبِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَاتَهُ شَيْءٌ مِنْ وِرْدِهِ ‏ ‏أَوْ قَالَ مِنْ جُزْئِهِ ‏ ‏مِنْ اللَّيْلِ فَقَرَأَهُ مَا بَيْنَ صَلَاةِ الْفَجْرِ إِلَى الظُّهْرِ فَكَأَنَّمَا قَرَأَهُ مِنْ لَيْلَتِهِ ‏","","",""],[355,355,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَ تَحْرِيمُ الْخَمْرِ قَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شَافِيًا فَنَزَلَتْ هَذِهِ الْآيَةُ الَّتِي فِي سُورَةِ ‏ ‏الْبَقَرَةِ ‏ { ‏يَسْأَلُونَكَ عَنْ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ ‏} ‏قَالَ فَدُعِيَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقُرِئَتْ عَلَيْهِ فَقَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شَافِيًا فَنَزَلَتْ الْآيَةُ الَّتِي فِي سُورَةِ ‏ ‏النِّسَاءِ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى ‏} ‏فَكَانَ مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَقَامَ الصَّلَاةَ نَادَى أَنْ لَا يَقْرَبَنَّ الصَّلَاةَ سَكْرَانُ فَدُعِيَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقُرِئَتْ عَلَيْهِ فَقَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شَافِيًا فَنَزَلَتْ الْآيَةُ الَّتِي فِي ‏ ‏الْمَائِدَةِ ‏ ‏فَدُعِيَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقُرِئَتْ عَلَيْهِ فَلَمَّا بَلَغَ ‏ { ‏فَهَلْ أَنْتُمْ مُنْتَهُونَ ‏} ‏قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏انْتَهَيْنَا انْتَهَيْنَا ‏","","",""],[356,356,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏صُبَيِّ بْنِ مَعْبَدٍ ‏ ‏أَنَّهُ كَانَ نَصْرَانِيًّا ‏ ‏تَغْلِبِيًّا فَأَسْلَمَ فَسَأَلَ ‏ ‏أَيُّ الْعَمَلِ أَفْضَلُ فَقِيلَ لَهُ الْجِهَادُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَأَرَادَ أَنْ يُجَاهِدَ فَقِيلَ لَهُ أَحَجَجْتَ قَالَ لَا فَقِيلَ لَهُ حُجَّ وَاعْتَمِرْ ثُمَّ جَاهِدْ فَأَهَلَّ بِهِمَا جَمِيعًا فَوَافَقَ ‏ ‏زَيْدَ بْنَ صُوحَانَ ‏ ‏وَسَلْمَانَ بْنَ رَبِيعَةَ ‏ ‏فَقَالَا هُوَ أَضَلُّ مِنْ نَاقَتِهِ ‏ ‏أَوْ مَا هُوَ بِأَهْدَى مِنْ جَمَلِهِ ‏ ‏فَانْطَلَقَ إِلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَخْبَرَهُ بِقَوْلِهِمَا فَقَالَ هُدِيتَ لِسُنَّةِ نَبِيِّكَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ لِسُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[357,357,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ لِلْحَجَرِ إِنَّمَا أَنْتَ حَجَرٌ وَلَوْلَا أَنِّي ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُكَ ‏ ‏مَا قَبَّلْتُكَ ثُمَّ قَبَّلَهُ ‏","","",""],[358,358,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَتَى الْحَجَرَ فَقَالَ ‏ ‏إِنِّي لَأَعْلَمُ أَنَّكَ حَجَرٌ لَا تَضُرُّ وَلَا تَنْفَعُ وَلَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُكَ مَا قَبَّلْتُكَ قَالَ ثُمَّ قَبَّلَهُ ‏","","",""],[359,359,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ غَفَلَةَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَبَّلَهُ وَالْتَزَمَهُ ثُمَّ قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَ ‏ ‏حَفِيًّا ‏ ‏يَعْنِي الْحَجَرَ ‏","","",""],[360,360,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ اللَّيْلُ مِنْ هَهُنَا وَذَهَبَ النَّهَارُ مِنْ هَهُنَا فَقَدْ أَفْطَرَ الصَّائِمُ ‏","","",""],[361,361,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الَّذِي يَعُودُ فِي ‏ ‏صَدَقَتِهِ ‏ ‏كَمَثَلِ الَّذِي يَعُودُ فِي قَيْئِهِ ‏","","",""],[362,362,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَهْلُ الْجَاهِلِيَّةِ لَا يُفِيضُونَ مِنْ ‏ ‏جَمْعٍ ‏ ‏حَتَّى يَقُولُوا أَشْرِقْ ‏ ‏ثَبِيرُ ‏ ‏كَيْمَا ‏ ‏نُغِيرُ ‏ ‏فَلَمَّا جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَالَفَهُمْ فَكَانَ ‏ ‏يَدْفَعُ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏مِقْدَارَ صَلَاةِ الْمُسْفِرِينَ بِصَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏قَبْلَ طُلُوعِ الشَّمْسِ ‏","","",""],[363,363,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحُ بْنُ أَبِي مَعْرُوفٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ قَالَ لِي ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ ‏","","",""],[364,364,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَسَنِ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى خُفَّيْهِ فِي السَّفَرِ ‏","","",""],[365,365,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَعَوَّذُ مِنْ الْبُخْلِ وَالْجُبْنِ وَعَذَابِ الْقَبْرِ ‏ ‏وَأَرْذَلِ ‏ ‏الْعُمُرِ ‏ ‏وَفِتْنَةِ ‏ ‏الصَّدْرِ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏فِتْنَةُ ‏ ‏الصَّدْرِ أَنْ يَمُوتَ الرَّجُلُ وَذَكَرَ ‏ ‏وَكِيعٌ ‏ ‏الْفِتْنَةَ ‏ ‏لَمْ يَتُبْ مِنْهَا ‏","","",""],[366,366,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ الْوَلِيدِ الشَّنِّيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏قَالَ ‏ ‏جَلَسَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَجْلِسًا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْلِسُهُ تَمُرُّ عَلَيْهِ الْجَنَائِزُ قَالَ فَمَرُّوا بِجِنَازَةٍ فَأَثْنَوْا خَيْرًا فَقَالَ وَجَبَتْ ثُمَّ مَرُّوا بِجِنَازَةٍ فَأَثْنَوْا خَيْرًا فَقَالَ وَجَبَتْ ثُمَّ مَرُّوا بِجِنَازَةٍ فَقَالُوا خَيْرًا فَقَالَ وَجَبَتْ ثُمَّ مَرُّوا بِجِنَازَةٍ فَقَالُوا هَذَا كَانَ أَكْذَبَ النَّاسِ فَقَالَ ‏ ‏إِنَّ أَكْذَبَ النَّاسِ أَكْذَبُهُمْ عَلَى اللَّهِ ثُمَّ الَّذِينَ يَلُونَهُمْ مَنْ كَذَبَ عَلَى رُوحِهِ فِي جَسَدِهِ قَالَ قَالُوا أَرَأَيْتَ إِذَا شَهِدَ أَرْبَعَةٌ قَالَ وَجَبَتْ قَالُوا أَوْ ثَلَاثَةٌ قَالَ وَثَلَاثَةٌ وَجَبَتْ قَالُوا وَاثْنَيْنِ قَالَ وَجَبَتْ وَلَأَنْ أَكُونَ قُلْتُ وَاحِدًا أَحَبُّ إِلَيَّ مِنْ ‏ ‏حُمْرِ النَّعَمِ ‏ ‏قَالَ فَقِيلَ ‏ ‏لِعُمَرَ ‏ ‏هَذَا شَيْءٌ تَقُولُهُ بِرَأْيِكَ أَمْ شَيْءٌ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا بَلْ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[367,367,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ ‏ ‏قَالَ ‏ ‏بَلَغَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ ‏ ‏سَعْدًا ‏ ‏لَمَّا بَنَى الْقَصْرَ قَالَ انْقَطَعَ ‏ ‏الصُّوَيْتُ فَبَعَثَ إِلَيْهِ ‏ ‏مُحَمَّدَ بْنَ مَسْلَمَةَ ‏ ‏فَلَمَّا قَدِمَ أَخْرَجَ ‏ ‏زَنْدَهُ ‏ ‏وَأَوْرَى نَارَهُ وَابْتَاعَ حَطَبًا بِدِرْهَمٍ وَقِيلَ ‏ ‏لِسَعْدٍ ‏ ‏إِنَّ رَجُلًا فَعَلَ كَذَا وَكَذَا فَقَالَ ذَاكَ ‏ ‏مُحَمَّدُ بْنُ مَسْلَمَةَ ‏ ‏فَخَرَجَ إِلَيْهِ فَحَلَفَ بِاللَّهِ مَا قَالَهُ فَقَالَ ‏ ‏نُؤَدِّي عَنْكَ الَّذِي تَقُولُهُ وَنَفْعَلُ مَا أُمِرْنَا بِهِ فَأَحْرَقَ الْبَابَ ثُمَّ أَقْبَلَ يَعْرِضُ عَلَيْهِ أَنْ يُزَوِّدَهُ فَأَبَى فَخَرَجَ فَقَدِمَ عَلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَهَجَّرَ إِلَيْهِ فَسَارَ ذَهَابَهُ وَرُجُوعَهُ تِسْعَ عَشْرَةَ فَقَالَ لَوْلَا حُسْنُ الظَّنِّ بِكَ لَرَأَيْنَا أَنَّكَ لَمْ تُؤَدِّ عَنَّا قَالَ بَلَى أَرْسَلَ يَقْرَأُ السَّلَامَ وَيَعْتَذِرُ وَيَحْلِفُ بِاللَّهِ مَا قَالَهُ قَالَ فَهَلْ زَوَّدَكَ شَيْئًا قَالَ لَا قَالَ فَمَا مَنَعَكَ أَنْ تُزَوِّدَنِي أَنْتَ قَالَ إِنِّي كَرِهْتُ أَنْ آمُرَ لَكَ فَيَكُونَ لَكَ الْبَارِدُ وَيَكُونَ لِي الْحَارُّ وَحَوْلِي أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏قَدْ قَتَلَهُمْ الْجُوعُ وَقَدْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَشْبَعُ الرَّجُلُ دُونَ جَارِهِ ‏ ‏آخِرُ مُسْنَدِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدِيثُ ‏ ‏السَّقِيفَةِ ‏","","",""],[368,368,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى الطَّبَّاعُ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏رَجَعَ إِلَى رَحْلِهِ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَكُنْتُ أُقْرِئُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏فَوَجَدَنِي وَأَنَا أَنْتَظِرُهُ وَذَلِكَ ‏ ‏بِمِنًى ‏ ‏فِي آخِرِ حَجَّةٍ حَجَّهَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏إِنَّ رَجُلًا أَتَى ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ إِنَّ فُلَانًا يَقُولُ لَوْ قَدْ مَاتَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَايَعْتُ فُلَانًا فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنِّي قَائِمٌ الْعَشِيَّةَ فِي النَّاسِ فَمُحَذِّرُهُمْ هَؤُلَاءِ ‏ ‏الرَّهْطَ ‏ ‏الَّذِينَ يُرِيدُونَ أَنْ يَغْصِبُوهُمْ أَمْرَهُمْ قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ لَا تَفْعَلْ فَإِنَّ الْمَوْسِمَ يَجْمَعُ ‏ ‏رَعَاعَ ‏ ‏النَّاسِ ‏ ‏وَغَوْغَاءَهُمْ ‏ ‏وَإِنَّهُمْ الَّذِينَ يَغْلِبُونَ عَلَى مَجْلِسِكَ إِذَا قُمْتَ فِي النَّاسِ ‏ ‏فَأَخْشَى أَنْ تَقُولَ مَقَالَةً يَطِيرُ بِهَا أُولَئِكَ فَلَا يَعُوهَا وَلَا يَضَعُوهَا عَلَى مَوَاضِعِهَا وَلَكِنْ حَتَّى تَقْدَمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَإِنَّهَا دَارُ الْهِجْرَةِ وَالسُّنَّةِ وَتَخْلُصَ بِعُلَمَاءِ النَّاسِ وَأَشْرَافِهِمْ فَتَقُولَ مَا قُلْتَ مُتَمَكِّنًا فَيَعُونَ مَقَالَتَكَ وَيَضَعُونَهَا مَوَاضِعَهَا فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَئِنْ قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏سَالِمًا صَالِحًا لَأُكَلِّمَنَّ بِهَا النَّاسَ فِي أَوَّلِ مَقَامٍ أَقُومُهُ فَلَمَّا قَدِمْنَا ‏ ‏الْمَدِينَةَ ‏ ‏فِي عَقِبِ ذِي الْحِجَّةِ وَكَانَ يَوْمَ الْجُمُعَةِ عَجَّلْتُ الرَّوَاحَ ‏ ‏صَكَّةَ ‏ ‏الْأَعْمَى فَقُلْتُ ‏ ‏لِمَالِكٍ ‏ ‏وَمَا ‏ ‏صَكَّةُ ‏ ‏الْأَعْمَى قَالَ إِنَّهُ لَا يُبَالِي أَيَّ سَاعَةٍ خَرَجَ لَا يَعْرِفُ الْحَرَّ وَالْبَرْدَ وَنَحْوَ هَذَا فَوَجَدْتُ ‏ ‏سَعِيدَ بْنَ زَيْدٍ ‏ ‏عِنْدَ رُكْنِ الْمِنْبَرِ الْأَيْمَنِ قَدْ سَبَقَنِي فَجَلَسْتُ حِذَاءَهُ تَحُكُّ رُكْبَتِي رُكْبَتَهُ فَلَمْ أَنْشَبْ أَنْ طَلَعَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَلَمَّا رَأَيْتُهُ قُلْتُ لَيَقُولَنَّ الْعَشِيَّةَ عَلَى هَذَا الْمِنْبَرِ مَقَالَةً مَا قَالَهَا عَلَيْهِ أَحَدٌ قَبْلَهُ قَالَ فَأَنْكَرَ ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏ذَلِكَ فَقَالَ مَا عَسَيْتَ أَنْ يَقُولَ مَا لَمْ يَقُلْ أَحَدٌ فَجَلَسَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى الْمِنْبَرِ فَلَمَّا سَكَتَ الْمُؤَذِّنُ قَامَ فَأَثْنَى عَلَى اللَّهِ بِمَا هُوَ أَهْلُهُ ثُمَّ قَالَ أَمَّا بَعْدُ أَيُّهَا النَّاسُ فَإِنِّي قَائِلٌ مَقَالَةً قَدْ قُدِّرَ لِي أَنْ أَقُولَهَا لَا أَدْرِي لَعَلَّهَا بَيْنَ يَدَيْ أَجَلِي فَمَنْ وَعَاهَا وَعَقَلَهَا فَلْيُحَدِّثْ بِهَا حَيْثُ انْتَهَتْ بِهِ رَاحِلَتُهُ وَمَنْ لَمْ يَعِهَا فَلَا أُحِلُّ لَهُ أَنْ يَكْذِبَ عَلَيَّ إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى بَعَثَ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَقِّ وَأَنْزَلَ عَلَيْهِ الْكِتَابَ وَكَانَ مِمَّا أَنْزَلَ عَلَيْهِ آيَةُ الرَّجْمِ فَقَرَأْنَاهَا وَوَعَيْنَاهَا ‏ ‏وَرَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَجَمْنَا ‏ ‏بَعْدَهُ ‏ ‏فَأَخْشَى إِنْ طَالَ بِالنَّاسِ زَمَانٌ أَنْ يَقُولَ قَائِلٌ لَا نَجِدُ آيَةَ الرَّجْمِ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ فَيَضِلُّوا بِتَرْكِ فَرِيضَةٍ قَدْ أَنْزَلَهَا اللَّهُ عَزَّ وَجَلَّ ‏ ‏فَالرَّجْمُ ‏ ‏فِي كِتَابِ اللَّهِ حَقٌّ عَلَى مَنْ زَنَى إِذَا أُحْصِنَ مِنْ الرِّجَالِ وَالنِّسَاءِ إِذَا قَامَتْ الْبَيِّنَةُ أَوْ الْحَبَلُ أَوْ ‏ ‏الِاعْتِرَافُ أَلَا وَإِنَّا قَدْ كُنَّا نَقْرَأُ لَا تَرْغَبُوا عَنْ آبَائِكُمْ فَإِنَّ كُفْرًا بِكُمْ أَنْ تَرْغَبُوا عَنْ آبَائِكُمْ أَلَا وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا تُطْرُونِي كَمَا أُطْرِيَ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِنَّمَا أَنَا عَبْدُ اللَّهِ فَقُولُوا عَبْدُ اللَّهِ وَرَسُولُهُ وَقَدْ بَلَغَنِي أَنَّ قَائِلًا مِنْكُمْ يَقُولُ لَوْ قَدْ مَاتَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَايَعْتُ فُلَانًا فَلَا يَغْتَرَّنَّ امْرُؤٌ أَنْ يَقُولَ إِنَّ بَيْعَةَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كَانَتْ فَلْتَةً أَلَا وَإِنَّهَا كَانَتْ كَذَلِكَ أَلَا وَإِنَّ اللَّهَ عَزَّ وَجَلَّ وَقَى شَرَّهَا وَلَيْسَ فِيكُمْ الْيَوْمَ مَنْ تُقْطَعُ إِلَيْهِ الْأَعْنَاقُ مِثْلُ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَلَا وَإِنَّهُ كَانَ مِنْ خَبَرِنَا حِينَ تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏وَالزُّبَيْرَ ‏ ‏وَمَنْ كَانَ مَعَهُمَا تَخَلَّفُوا فِي بَيْتِ ‏ ‏فَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏بِنْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَخَلَّفَتْ عَنَّا ‏ ‏الْأَنْصَارُ ‏ ‏بِأَجْمَعِهَا فِي سَقِيفَةِ ‏ ‏بَنِي سَاعِدَةَ ‏ ‏وَاجْتَمَعَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقُلْتُ لَهُ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏انْطَلِقْ بِنَا إِلَى إِخْوَانِنَا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَانْطَلَقْنَا نَؤُمُّهُمْ حَتَّى لَقِيَنَا ‏ ‏رَجُلَانِ ‏ ‏صَالِحَانِ فَذَكَرَا لَنَا الَّذِي صَنَعَ الْقَوْمُ فَقَالَا أَيْنَ تُرِيدُونَ يَا مَعْشَرَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏فَقُلْتُ نُرِيدُ إِخْوَانَنَا هَؤُلَاءِ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَا لَا عَلَيْكُمْ أَنْ لَا تَقْرَبُوهُمْ وَاقْضُوا أَمْرَكُمْ يَا مَعْشَرَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏فَقُلْتُ وَاللَّهِ لَنَأْتِيَنَّهُمْ ‏ ‏فَانْطَلَقْنَا حَتَّى جِئْنَاهُمْ فِي سَقِيفَةِ ‏ ‏بَنِي سَاعِدَةَ ‏ ‏فَإِذَا هُمْ مُجْتَمِعُونَ وَإِذَا بَيْنَ ‏ ‏ظَهْرَانَيْهِمْ ‏ ‏رَجُلٌ ‏ ‏مُزَمَّلٌ ‏ ‏فَقُلْتُ مَنْ هَذَا فَقَالُوا ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏فَقُلْتُ مَا لَهُ قَالُوا وَجِعٌ فَلَمَّا جَلَسْنَا قَامَ خَطِيبُهُمْ فَأَثْنَى عَلَى اللَّهِ عَزَّ وَجَلَّ بِمَا هُوَ أَهْلُهُ وَقَالَ أَمَّا بَعْدُ فَنَحْنُ أَنْصَارُ اللَّهِ عَزَّ وَجَلَّ وَكَتِيبَةُ الْإِسْلَامِ وَأَنْتُمْ يَا مَعْشَرَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏رَهْطٌ ‏ ‏مِنَّا وَقَدْ ‏ ‏دَفَّتْ ‏ ‏دَافَّةٌ ‏ ‏مِنْكُمْ يُرِيدُونَ أَنْ يَخْزِلُونَا مِنْ أَصْلِنَا وَيَحْضُنُونَا مِنْ الْأَمْرِ فَلَمَّا سَكَتَ أَرَدْتُ أَنْ أَتَكَلَّمَ وَكُنْتُ قَدْ زَوَّرْتُ مَقَالَةً أَعْجَبَتْنِي أَرَدْتُ أَنْ أَقُولَهَا بَيْنَ يَدَيْ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَقَدْ كُنْتُ أُدَارِي مِنْهُ بَعْضَ الْحَدِّ وَهُوَ كَانَ أَحْلَمَ مِنِّي وَأَوْقَرَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى رِسْلِكَ فَكَرِهْتُ أَنْ أُغْضِبَهُ وَكَانَ أَعْلَمَ مِنِّي وَأَوْقَرَ وَاللَّهِ مَا تَرَكَ مِنْ كَلِمَةٍ أَعْجَبَتْنِي فِي تَزْوِيرِي إِلَّا قَالَهَا فِي بَدِيهَتِهِ وَأَفْضَلَ حَتَّى سَكَتَ فَقَالَ أَمَّا بَعْدُ فَمَا ذَكَرْتُمْ مِنْ خَيْرٍ فَأَنْتُمْ أَهْلُهُ وَلَمْ تَعْرِفْ ‏ ‏الْعَرَبُ ‏ ‏هَذَا الْأَمْرَ إِلَّا لِهَذَا الْحَيِّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏هُمْ أَوْسَطُ ‏ ‏الْعَرَبِ ‏ ‏نَسَبًا وَدَارًا وَقَدْ رَضِيتُ لَكُمْ أَحَدَ هَذَيْنِ الرَّجُلَيْنِ أَيَّهُمَا شِئْتُمْ وَأَخَذَ بِيَدِي وَبِيَدِ ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏فَلَمْ أَكْرَهْ مِمَّا قَالَ غَيْرَهَا وَكَانَ وَاللَّهِ أَنْ أُقَدَّمَ فَتُضْرَبَ عُنُقِي لَا يُقَرِّبُنِي ذَلِكَ إِلَى إِثْمٍ أَحَبَّ إِلَيَّ مِنْ أَنْ أَتَأَمَّرَ عَلَى قَوْمٍ فِيهِمْ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِلَّا أَنْ تَغَيَّرَ نَفْسِي عِنْدَ الْمَوْتِ فَقَالَ قَائِلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَا ‏ ‏جُذَيْلُهَا الْمُحَكَّكُ ‏ ‏وَعُذَيْقُهَا الْمُرَجَّبُ ‏ ‏مِنَّا أَمِيرٌ وَمِنْكُمْ أَمِيرٌ يَا مَعْشَرَ ‏ ‏قُرَيْشٍ ‏ ‏فَقُلْتُ ‏ ‏لِمَالِكٍ ‏ ‏مَا مَعْنَى أَنَا ‏ ‏جُذَيْلُهَا الْمُحَكَّكُ ‏ ‏وَعُذَيْقُهَا الْمُرَجَّبُ ‏ ‏قَالَ كَأَنَّهُ يَقُولُ أَنَا دَاهِيَتُهَا قَالَ وَكَثُرَ ‏ ‏اللَّغَطُ ‏ ‏وَارْتَفَعَتْ الْأَصْوَاتُ حَتَّى خَشِيتُ ‏ ‏الِاخْتِلَافَ فَقُلْتُ ابْسُطْ يَدَكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَبَسَطَ يَدَهُ فَبَايَعْتُهُ وَبَايَعَهُ ‏ ‏الْمُهَاجِرُونَ ‏ ‏ثُمَّ بَايَعَهُ ‏ ‏الْأَنْصَارُ ‏ ‏وَنَزَوْنَا ‏ ‏عَلَى ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏فَقَالَ قَائِلٌ مِنْهُمْ قَتَلْتُمْ ‏ ‏سَعْدًا ‏ ‏فَقُلْتُ قَتَلَ اللَّهُ ‏ ‏سَعْدًا ‏ ‏وَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَمَا وَاللَّهِ مَا وَجَدْنَا فِيمَا حَضَرْنَا أَمْرًا هُوَ أَقْوَى مِنْ مُبَايَعَةِ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏خَشِينَا إِنْ فَارَقْنَا الْقَوْمَ وَلَمْ تَكُنْ بَيْعَةٌ أَنْ يُحْدِثُوا بَعْدَنَا بَيْعَةً فَإِمَّا أَنْ نُتَابِعَهُمْ عَلَى مَا لَا ‏ ‏نَرْضَى وَإِمَّا أَنْ نُخَالِفَهُمْ فَيَكُونَ فِيهِ فَسَادٌ فَمَنْ بَايَعَ أَمِيرًا عَنْ غَيْرِ مَشُورَةِ الْمُسْلِمِينَ فَلَا بَيْعَةَ لَهُ وَلَا بَيْعَةَ لِلَّذِي بَايَعَهُ تَغِرَّةً أَنْ يُقْتَلَا ‏ ‏قَالَ ‏ ‏مَالِكٌ ‏ ‏وَأَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ الرَّجُلَيْنِ اللَّذَيْنِ لَقِيَاهُمَا ‏ ‏عُوَيْمِرُ بْنُ سَاعِدَةَ ‏ ‏وَمَعْنُ بْنُ عَدِيٍّ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَأَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّ الَّذِي قَالَ أَنَا ‏ ‏جُذَيْلُهَا الْمُحَكَّكُ ‏ ‏وَعُذَيْقُهَا الْمُرَجَّبُ ‏ ‏الْحُبَابُ بْنُ الْمُنْذِرِ ‏","","",""],[369,369,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏بَنِي النَّجَّارِ ‏ ‏ثُمَّ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏ثُمَّ ‏ ‏بَلْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏ثُمَّ ‏ ‏بَنِي سَاعِدَةَ ‏ ‏وَقَالَ فِي كُلِّ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏خَيْرٌ ‏","","",""],[370,370,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُتَبَايِعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا أَوْ يَكُونُ الْبَيْعُ خِيَارًا ‏","","",""],[371,371,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ ‏ ‏حَبَلِ الْحَبَلَةِ ‏","","",""],[372,372,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنَّا نَتَبَايَعُ الطَّعَامَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْعَثُ عَلَيْنَا مَنْ يَأْمُرُنَا بِنَقْلِهِ مِنْ الْمَكَانِ الَّذِي ابْتَعْنَاهُ فِيهِ إِلَى مَكَانٍ سِوَاهُ قَبْلَ أَنْ نَبِيعَهُ ‏","","",""],[373,373,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ابْتَاعَ طَعَامًا فَلَا يَبِعْهُ حَتَّى ‏ ‏يَسْتَوْفِيَهُ ‏","","",""],[374,374,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ ‏ ‏شِرْكًا ‏ ‏لَهُ فِي عَبْدٍ فَكَانَ لَهُ مَا يَبْلُغُ ثَمَنَ الْعَبْدِ فَإِنَّهُ يُقَوَّمُ قِيمَةَ عَدْلٍ فَيُعْطَى شُرَكَاؤُهُ ‏ ‏حَقَّهُمْ وَعَتَقَ عَلَيْهِ الْعَبْدَ وَإِلَّا فَقَدْ أَعْتَقَ مَا أَعْتَقَ ‏","","",""],[375,375,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏رَجُلٌ لَاعَنَ امْرَأَتَهُ فَقَالَ فَرَّقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَهُمَا ‏ ‏وَذَكَرَ الْحَدِيثَ ‏","","",""],[376,376,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي الْفَارِسِيَّ ‏ ‏قَالَ أَبِي ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قُلْتُ ‏ ‏لِعُثْمَانَ بْنِ عَفَّانَ ‏ ‏مَا حَمَلَكُمْ عَلَى أَنْ عَمَدْتُمْ إِلَى ‏ ‏الْأَنْفَالِ ‏ ‏وَهِيَ مِنْ الْمَثَانِي وَإِلَى ‏ ‏بَرَاءَةٌ ‏ ‏وَهِيَ مِنْ ‏ ‏الْمِئِينَ فَقَرَنْتُمْ بَيْنَهُمَا وَلَمْ تَكْتُبُوا ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏بَيْنَهُمَا سَطْرًا ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏وَوَضَعْتُمُوهَا فِي السَّبْعِ الطِّوَالِ مَا حَمَلَكُمْ عَلَى ذَلِكَ قَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ مِمَّا يَأْتِي عَلَيْهِ الزَّمَانُ يُنْزَلُ عَلَيْهِ مِنْ السُّوَرِ ذَوَاتِ الْعَدَدِ وَكَانَ إِذَا أُنْزِلَ عَلَيْهِ الشَّيْءُ يَدْعُو بَعْضَ مَنْ يَكْتُبُ عِنْدَهُ يَقُولُ ‏ ‏ضَعُوا هَذَا فِي السُّورَةِ الَّتِي يُذْكَرُ فِيهَا كَذَا وَكَذَا وَيُنْزَلُ عَلَيْهِ الْآيَاتُ فَيَقُولُ ضَعُوا هَذِهِ الْآيَاتِ فِي السُّورَةِ الَّتِي يُذْكَرُ فِيهَا كَذَا وَكَذَا وَيُنْزَلُ عَلَيْهِ الْآيَةُ فَيَقُولُ ضَعُوا هَذِهِ الْآيَةَ فِي السُّورَةِ الَّتِي يُذْكَرُ فِيهَا كَذَا وَكَذَا وَكَانَتْ ‏ ‏الْأَنْفَالُ ‏ ‏مِنْ أَوَائِلِ مَا أُنْزِلَ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَبَرَاءَةٌ ‏ ‏مِنْ آخِرِ الْقُرْآنِ فَكَانَتْ قِصَّتُهَا شَبِيهًا بِقِصَّتِهَا فَقُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يُبَيِّنْ لَنَا أَنَّهَا مِنْهَا وَظَنَنْتُ أَنَّهَا مِنْهَا فَمِنْ ثَمَّ قَرَنْتُ بَيْنَهُمَا وَلَمْ أَكْتُبْ بَيْنَهُمَا سَطْرًا ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏وَوَضَعْتُهَا ‏ ‏فِ ‏ ‏السَّبْعِ الطِّوَالِ ‏","","",""],[377,377,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَنَّ ‏ ‏حُمْرَانَ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏تَوَضَّأَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى الْبَلَاطِ ثُمَّ قَالَ لَأُحَدِّثَنَّكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا آيَةٌ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُكُمُوهُ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ دَخَلَ فَصَلَّى غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الصَّلَاةِ الْأُخْرَى حَتَّى يُصَلِّيَهَا ‏","","",""],[378,378,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُحْرِمُ ‏ ‏لَا يَنْكِحُ وَلَا يُنْكِحُ وَلَا يَخْطُبُ ‏","","",""],[379,379,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ حَرْمَلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدًا يَعْنِي ابْنَ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَاجًّا حَتَّى إِذَا كَانَ بِبَعْضِ الطَّرِيقِ قِيلَ ‏ ‏لِعَلِيٍّ ‏ ‏رِضْوَانُ اللَّهِ عَلَيْهِمَا إِنَّهُ قَدْ نَهَى عَنْ ‏ ‏التَّمَتُّعِ ‏ ‏بِالْعُمْرَةِ إِلَى الْحَجِّ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لِأَصْحَابِهِ إِذَا ارْتَحَلَ فَارْتَحِلُوا ‏ ‏فَأَهَلَّ ‏ ‏عَلِيٌّ ‏ ‏وَأَصْحَابُهُ بِعُمْرَةٍ فَلَمْ يُكَلِّمْهُ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي ذَلِكَ فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَلَمْ أُخْبَرْ أَنَّكَ نَهَيْتَ عَنْ ‏ ‏التَّمَتُّعِ ‏ ‏بِالْعُمْرَةِ قَالَ فَقَالَ بَلَى قَالَ فَلَمْ تَسْمَعْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمَتَّعَ ‏ ‏قَالَ بَلَى ‏","","",""],[380,380,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ثَلَاثًا ثَلَاثًا ‏","","",""],[381,381,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبُو أَنَسٍ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَوَضَّأَ ‏ ‏بِالْمَقَاعِدِ ‏ ‏ثَلَاثًا ثَلَاثًا وَعِنْدَهُ ‏ ‏رِجَالٌ ‏ ‏مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَلَيْسَ هَكَذَا رَأَيْتُمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ قَالُوا نَعَمْ ‏","","",""],[382,382,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ ‏","","",""],[383,383,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمْرَانَ بْنَ أَبَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَتَمَّ الْوُضُوءَ كَمَا أَمَرَهُ اللَّهُ عَزَّ وَجَلَّ فَالصَّلَوَاتُ ‏ ‏الْمَكْتُوبَاتُ ‏ ‏كَفَّارَاتٌ لِمَا بَيْنَهُنَّ ‏","","",""],[384,384,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏قَالَ قَالَ ‏ ‏قَيْسٌ ‏ ‏فَحَدَّثَنِي ‏ ‏أَبُو سَهْلَةَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ يَوْمَ الدَّارِ حِينَ ‏ ‏حُصِرَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهِدَ ‏ ‏إِلَيَّ ‏ ‏عَهْدًا ‏ ‏فَأَنَا صَابِرٌ عَلَيْهِ ‏ ‏قَالَ ‏ ‏قَيْسٌ ‏ ‏فَكَانُوا يَرَوْنَهُ ذَلِكَ الْيَوْمَ ‏","","",""],[385,385,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى صَلَاةَ الْعِشَاءِ وَالصُّبْحِ فِي جَمَاعَةٍ فَهُوَ كَقِيَامِ لَيْلَةٍ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏مَنْ صَلَّى الْعِشَاءَ فِي جَمَاعَةٍ فَهُوَ كَقِيَامِ نِصْفِ لَيْلَةٍ وَمَنْ صَلَّى الصُّبْحَ فِي جَمَاعَةٍ فَهُوَ كَقِيَامِ لَيْلَةٍ ‏","","",""],[386,386,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى الْعِشَاءَ فِي جَمَاعَةٍ فَهُوَ كَمَنْ قَامَ نِصْفَ اللَّيْلِ وَمَنْ صَلَّى الصُّبْحَ فِي جَمَاعَةٍ فَهُوَ كَمَنْ قَامَ اللَّيْلَ كُلَّهُ ‏","","",""],[387,387,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ يَعْنِي ابْنَ عُبَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَطَاءُ بْنُ فَرُّوخَ ‏ ‏مَوْلَى ‏ ‏الْقُرَشِيِّينَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اشْتَرَى مِنْ رَجُلٍ أَرْضًا فَأَبْطَأَ عَلَيْهِ فَلَقِيَهُ فَقَالَ لَهُ مَا مَنَعَكَ مِنْ قَبْضِ مَالِكَ قَالَ إِنَّكَ ‏ ‏غَبَنْتَنِي ‏ ‏فَمَا أَلْقَى مِنْ النَّاسِ أَحَدًا إِلَّا وَهُوَ يَلُومُنِي قَالَ ‏ ‏أَوَ ذَلِكَ يَمْنَعُكَ قَالَ نَعَمْ قَالَ فَاخْتَرْ بَيْنَ أَرْضِكَ وَمَالِكَ ثُمَّ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدْخَلَ اللَّهُ عَزَّ وَجَلَّ الْجَنَّةَ رَجُلًا كَانَ سَهْلًا مُشْتَرِيًا وَبَائِعًا وَقَاضِيًا ‏ ‏وَمُقْتَضِيًا ‏","","",""],[388,388,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏وَهُوَ عِنْدَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ لَهُ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَا بَقِيَ لِلنِّسَاءِ مِنْكَ قَالَ فَلَمَّا ذُكِرَتْ النِّسَاءُ قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏ادْنُ يَا ‏ ‏عَلْقَمَةُ ‏ ‏قَالَ وَأَنَا رَجُلٌ شَابٌّ ‏ ‏فَقَالَ لَهُ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى فِتْيَةٍ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏فَقَالَ ‏ ‏مَنْ كَانَ مِنْكُمْ ذَا ‏ ‏طَوْلٍ ‏ ‏فَلْيَتَزَوَّجْ فَإِنَّهُ ‏ ‏أَغَضُّ ‏ ‏لِلطَّرْفِ ‏ ‏وَأَحْصَنُ ‏ ‏لِلْفَرْجِ وَمَنْ لَا فَإِنَّ الصَّوْمَ لَهُ ‏ ‏وِجَاءٌ ‏","","",""],[389,389,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلْقَمَةَ بْنَ مَرْثَدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ خَيْرَكُمْ مَنْ عَلَّمَ الْقُرْآنَ ‏ ‏أَوْ تَعَلَّمَهُ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏فَقَالَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏فَذَاكَ الَّذِي أَقْعَدَنِي هَذَا الْمَقْعَدَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَلَمْ يَسْمَعْ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏مِنْ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَلَا مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَلَكِنْ قَدْ سَمِعَ مِنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏أَخْبَرَنِي وَقَالَ ‏ ‏خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏وَقَالَ فِيهِ مَنْ تَعَلَّمَ الْقُرْآنَ أَوْ عَلَّمَهُ ‏","","",""],[390,390,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ سَمْحًا بَائِعًا وَمُبْتَاعًا وَقَاضِيًا وَمُقْتَضِيًا فَدَخَلَ الْجَنَّةَ ‏","","",""],[391,391,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ ‏ ‏دَعَا بِمَاءٍ فَتَوَضَّأَ وَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَظَهْرِ قَدَمَيْهِ ثُمَّ ضَحِكَ فَقَالَ لِأَصْحَابِهِ أَلَا تَسْأَلُونِي عَمَّا أَضْحَكَنِي فَقَالُوا مِمَّ ضَحِكْتَ يَا أَمِيرَ الْمُؤْمِنِينَ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا بِمَاءٍ قَرِيبًا مِنْ هَذِهِ الْبُقْعَةِ فَتَوَضَّأَ كَمَا تَوَضَّأْتُ ثُمَّ ضَحِكَ فَقَالَ أَلَا تَسْأَلُونِي مَا أَضْحَكَنِي فَقَالُوا مَا أَضْحَكَكَ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏إِنَّ الْعَبْدَ إِذَا دَعَا ‏ ‏بِوَضُوءٍ ‏ ‏فَغَسَلَ وَجْهَهُ حَطَّ اللَّهُ عَنْهُ كُلَّ خَطِيئَةٍ أَصَابَهَا بِوَجْهِهِ فَإِذَا غَسَلَ ذِرَاعَيْهِ كَانَ كَذَلِكَ وَإِنْ مَسَحَ بِرَأْسِهِ ‏ ‏كَانَ كَذَلِكَ وَإِذَا طَهَّرَ قَدَمَيْهِ كَانَ كَذَلِكَ ‏","","",""],[392,392,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏مَوْلَى ‏ ‏حَسَنِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏رَبَاحٍ ‏ ‏قَالَ ‏ ‏زَوَّجَنِي أَهْلِي أَمَةً لَهُمْ رُومِيَّةً ‏ ‏فَوَقَعْتُ ‏ ‏عَلَيْهَا فَوَلَدَتْ لِي غُلَامًا أَسْوَدَ مِثْلِي فَسَمَّيْتُهُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏ثُمَّ ‏ ‏وَقَعْتُ ‏ ‏عَلَيْهَا فَوَلَدَتْ لِي غُلَامًا أَسْوَدَ مِثْلِي فَسَمَّيْتُهُ ‏ ‏عُبَيْدَ اللَّهِ ‏ ‏ثُمَّ ‏ ‏طَبِنَ ‏ ‏لَهَا غُلَامٌ لِأَهْلِي رُومِيٌّ يُقَالُ لَهُ ‏ ‏يُوحَنَّسُ ‏ ‏فَرَاطَنَهَا ‏ ‏بِلِسَانِهِ قَالَ فَوَلَدَتْ غُلَامًا كَأَنَّهُ ‏ ‏وَزَغَةٌ ‏ ‏مِنْ ‏ ‏الْوَزَغَاتِ ‏ ‏فَقُلْتُ لَهَا مَا هَذَا قَالَتْ هُوَ ‏ ‏لِيُوحَنَّسَ ‏ ‏قَالَ فَرُفِعْنَا إِلَى أَمِيرِ الْمُؤْمِنِينَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏مَهْدِيٌّ ‏ ‏أَحْسَبُهُ قَالَ سَأَلَهُمَا ‏ ‏فَاعْتَرَفَا فَقَالَ أَتَرْضَيَانِ أَنْ أَقْضِيَ بَيْنَكُمَا بِقَضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى ‏ ‏أَنَّ ‏ ‏الْوَلَدَ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرَ ‏ ‏قَالَ ‏ ‏مَهْدِيٌّ ‏ ‏وَأَحْسَبُهُ قَالَ جَلَدَهَا وَجَلَدَهُ وَكَانَا مَمْلُوكَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ أَبُو مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏رَبَاحٍ ‏ ‏فَذَكَرَ الْحَدِيثَ قَالَ فَرَفَعْتُهُمَا إِلَى أَمِيرِ الْمُؤْمِنِينَ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى أَنَّ الْوَلَدَ ‏ ‏لِلْفِرَاشِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[393,393,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏قَالَ ‏ ‏دَعَا ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِمَاءٍ وَهُوَ عَلَى الْمَقَاعِدِ فَسَكَبَ عَلَى يَمِينِهِ فَغَسَلَهَا ثُمَّ أَدْخَلَ يَمِينَهُ فِي الْإِنَاءِ فَغَسَلَ كَفَّيْهِ ثَلَاثًا ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثَ مِرَارٍ وَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏وَغَسَلَ ذِرَاعَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثَ مَرَّاتٍ ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ رِجْلَيْهِ إِلَى الْكَعْبَيْنِ ثَلَاثَ مِرَارٍ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ نَفْسَهُ فِيهِمَا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ نَصْرٍ التِّرْمِذِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏أَنَّهُ رَأَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏دَعَا بِإِنَاءٍ فَذَكَرَ نَحْوَهُ ‏","","",""],[394,394,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ يَعْنِي ابْنَ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏أَشْرَفَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مِنْ الْقَصْرِ وَهُوَ مَحْصُورٌ فَقَالَ أَنْشُدُ بِاللَّهِ مَنْ شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏حِرَاءٍ ‏ ‏إِذْ اهْتَزَّ الْجَبَلُ فَرَكَلَهُ بِقَدَمِهِ ثُمَّ قَالَ ‏ ‏اسْكُنْ ‏ ‏حِرَاءُ ‏ ‏لَيْسَ عَلَيْكَ إِلَّا نَبِيٌّ أَوْ صِدِّيقٌ أَوْ شَهِيدٌ وَأَنَا مَعَهُ ‏ ‏فَانْتَشَدَ لَهُ رِجَالٌ قَالَ أَنْشُدُ بِاللَّهِ مَنْ شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ بَيْعَةِ الرِّضْوَانِ إِذْ بَعَثَنِي إِلَى الْمُشْرِكِينَ إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏قَالَ هَذِهِ يَدِي وَهَذِهِ يَدُ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَبَايَعَ ‏ ‏لِي ‏ ‏فَانْتَشَدَ ‏ ‏لَهُ رِجَالٌ قَالَ أَنْشُدُ بِاللَّهِ مَنْ شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ يُوَسِّعُ لَنَا بِهَذَا الْبَيْتِ فِي الْمَسْجِدِ بِبَيْتٍ فِي الْجَنَّةِ ‏ ‏فَابْتَعْتُهُ ‏ ‏مِنْ مَالِي فَوَسَّعْتُ بِهِ الْمَسْجِدَ ‏ ‏فَانْتَشَدَ ‏ ‏لَهُ رِجَالٌ قَالَ وَأَنْشُدُ بِاللَّهِ مَنْ شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ جَيْشِ الْعُسْرَةِ قَالَ مَنْ يُنْفِقُ الْيَوْمَ نَفَقَةً مُتَقَبَّلَةً فَجَهَّزْتُ نِصْفَ الْجَيْشِ مِنْ مَالِي قَالَ ‏ ‏فَانْتَشَدَ ‏ ‏لَهُ رِجَالٌ وَأَنْشُدُ بِاللَّهِ مَنْ شَهِدَ ‏ ‏رُومَةَ ‏ ‏يُبَاعُ مَاؤُهَا ابْنَ السَّبِيلِ ‏ ‏فَابْتَعْتُهَا ‏ ‏مِنْ مَالِي فَأَبَحْتُهَا لِابْنِ السَّبِيلِ قَالَ ‏ ‏فَانْتَشَدَ ‏ ‏لَهُ رِجَالٌ ‏","","",""],[395,395,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَوَضَّأَ فَأَفْرَغَ عَلَى يَدَيْهِ ثَلَاثًا فَغَسَلَهُمَا ثُمَّ مَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى إِلَى الْمِرْفَقِ ثَلَاثًا ثُمَّ الْيُسْرَى مِثْلَ ذَلِكَ ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ قَدَمَهُ الْيُمْنَى ثَلَاثًا ثُمَّ الْيُسْرَى مِثْلَ ذَلِكَ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ نَحْوًا مِنْ وُضُوئِي هَذَا ثُمَّ قَالَ ‏ ‏مَنْ تَوَضَّأَ وُضُوئِي هَذَا ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[396,396,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَ ‏ ‏عُمَرُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏إِلَى ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَيُكَحِّلُ عَيْنَيْهِ وَهُوَ مُحْرِمٌ أَوْ بِأَيِّ شَيْءٍ يُكَحِّلُهُمَا وَهُوَ مُحْرِمٌ فَأَرْسَلَ إِلَيْهِ ‏ ‏أَنْ يُضَمِّدَهُمَا بِالصَّبِرِ ‏ ‏فَإِنِّي ‏ ‏سَمِعْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُحَدِّثُ ذَلِكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[397,397,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ حُدَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ عَلِمَ أَنَّ الصَّلَاةَ حَقٌّ وَاجِبٌ دَخَلَ الْجَنَّةَ ‏","","",""],[398,398,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مَعْشَرٍ يَعْنِي الْبَرَّاءَ وَاسْمُهُ يُوسُفُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏حَجَّ ‏ ‏عُثْمَانُ ‏ ‏حَتَّى إِذَا كَانَ فِي بَعْضِ الطَّرِيقِ أُخْبِرَ ‏ ‏عَلِيٌّ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏نَهَى أَصْحَابَهُ عَنْ التَّمَتُّعِ بِالْعُمْرَةِ وَالْحَجِّ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏لِأَصْحَابِهِ إِذَا رَاحَ فَرُوحُوا ‏ ‏فَأَهَلَّ ‏ ‏عَلِيٌّ ‏ ‏وَأَصْحَابُهُ بِعُمْرَةٍ فَلَمْ يُكَلِّمْهُمْ ‏ ‏عُثْمَانُ ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَلَمْ أُخْبَرْ أَنَّكَ نَهَيْتَ عَنْ التَّمَتُّعِ أَلَمْ يَتَمَتَّعْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَمَا أَدْرِي مَا أَجَابَهُ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[399,399,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ ‏ ‏قَالَ ‏ ‏أَرْسَلَ إِلَيَّ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَبَيْنَا أَنَا كَذَلِكَ إِذْ جَاءَهُ ‏ ‏مَوْلَاهُ ‏ ‏يَرْفَأُ ‏ ‏فَقَالَ هَذَا ‏ ‏عُثْمَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏وَسَعْدٌ ‏ ‏وَالزُّبَيْرُ بْنُ الْعَوَّامِ ‏ ‏قَالَ ‏ ‏وَلَا أَدْرِي أَذَكَرَ ‏ ‏طَلْحَةَ ‏ ‏أَمْ لَا ‏ ‏يَسْتَأْذِنُونَ عَلَيْكَ قَالَ ائْذَنْ لَهُمْ ثُمَّ مَكَثَ سَاعَةً ثُمَّ جَاءَ فَقَالَ هَذَا ‏ ‏الْعَبَّاسُ ‏ ‏وَعَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏يَسْتَأْذِنَانِ عَلَيْكَ قَالَ ائْذَنْ لَهُمَا فَلَمَّا دَخَلَ ‏ ‏الْعَبَّاسُ ‏ ‏قَالَ يَا أَمِيرَ الْمُؤْمِنِينَ اقْضِ بَيْنِي وَبَيْنَ هَذَا وَهُمَا حِينَئِذٍ يَخْتَصِمَانِ فِيمَا ‏ ‏أَفَاءَ ‏ ‏اللَّهُ عَلَى رَسُولِهِ مِنْ أَمْوَالِ ‏ ‏بَنِي النَّضِيرِ ‏ ‏فَقَالَ الْقَوْمُ اقْضِ بَيْنَهُمَا يَا أَمِيرَ الْمُؤْمِنِينَ وَأَرِحْ كُلَّ وَاحِدٍ مِنْ صَاحِبِهِ فَقَدْ طَالَتْ خُصُومَتُهُمَا فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنْشُدُكُمْ ‏ ‏اللَّهَ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَوَاتُ وَالْأَرْضُ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا نُورَثُ مَا تَرَكْنَا ‏ ‏صَدَقَةٌ ‏ ‏قَالُوا قَدْ قَالَ ذَلِكَ وَقَالَ لَهُمَا مِثْلَ ذَلِكَ فَقَالَا نَعَمْ قَالَ فَإِنِّي سَأُخْبِرُكُمْ عَنْ هَذَا ‏ ‏الْفَيْءِ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ خَصَّ نَبِيَّهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُ بِشَيْءٍ لَمْ يُعْطِهِ غَيْرَهُ فَقَالَ ‏ { ‏وَمَا ‏ ‏أَفَاءَ ‏ ‏اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ ‏} ‏وَكَانَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاصَّةً وَاللَّهِ مَا احْتَازَهَا دُونَكُمْ وَلَا اسْتَأْثَرَ بِهَا عَلَيْكُمْ لَقَدْ قَسَمَهَا بَيْنَكُمْ ‏ ‏وَبَثَّهَا ‏ ‏فِيكُمْ حَتَّى بَقِيَ مِنْهَا هَذَا الْمَالُ فَكَانَ يُنْفِقُ عَلَى أَهْلِهِ مِنْهُ سَنَةً ثُمَّ يَجْعَلُ مَا بَقِيَ مِنْهُ مَجْعَلَ مَالِ اللَّهِ ‏ ‏فَلَمَّا ‏ ‏قُبِضَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَا وَلِيُّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَهُ أَعْمَلُ فِيهَا بِمَا كَانَ يَعْمَلُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا ‏","","",""],[400,400,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ أَبُو مَعْمَرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمٍ الطَّائِفِيُّ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عِمْرَانَ بْنِ مَنَّاحٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ رَأَى جَنَازَةً فَقَامَ إِلَيْهَا وَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى جَنَازَةً فَقَامَ لَهَا ‏","","",""]];
